window.IA = {"lang": "pt", "ui": {"app_title": "Academia de Intérpretes ClayArena", "tagline": "Tiro aos pratos para intérpretes — do zero", "hero_p": "Doze missões para aprender a linguagem do Parcours de Chasse – Sporting™ e do Compak® Sporting: os pratos e as suas trajetórias, a espingarda, o avanço e a técnica de tiro, as regras da FITASC, as decisões do árbitro e a etiqueta da modalidade. Depois, pratique como num posto de tiro a sério: traduza o treinador, reconheça o prato, encontre o avanço e tome a decisão do árbitro.", "missions": "Missões", "practice": "Prática", "start": "Começar", "continue": "Continuar", "lessons_n": "lições", "min": "min", "back": "Voltar", "back_mission": "Voltar à missão", "home": "Início", "key_points": "Pontos-chave", "coach_says": "O treinador diz", "listen": "Ouvir", "reveal": "Mostrar significado", "meaning": "Significado", "say_it": "Como traduzir", "terms": "Termos", "rules_refs": "Nas regras da FITASC", "sources": "Fontes", "quiz": "Teste-se", "correct": "Correto!", "wrong": "Não exatamente.", "next": "Seguinte", "next_lesson": "Lição seguinte", "finish_lesson": "Lição concluída", "xp": "XP", "level": "Nível", "levels": ["Principiante", "Ouvinte", "Intérprete de campo de tiro", "Intérprete de posto de tiro", "Intérprete profissional"], "done_of": "concluídas", "game_coach": "Traduza o treinador", "game_coach_d": "Ouça uma frase do treinador em inglês e escolha o que ela quer realmente dizer.", "game_flight": "Identifique a trajetória", "game_flight_d": "Veja o prato a voar e identifique a mostra.", "game_lead": "Laboratório do avanço", "game_lead_d": "Veja como funciona o avanço em cada método — e depois carregue no gatilho você mesmo.", "game_call": "Decisão do árbitro", "game_call_d": "Situações reais no posto de tiro: o que decide o árbitro?", "game_terms": "Cartões de termos", "game_terms_d": "Associe o termo inglês à palavra que os atiradores usam na sua língua.", "game_exam": "Exame final", "game_exam_d": "30 perguntas de todas as missões. Obtenha 80% e receba o seu certificado.", "which_flight": "Que mostra é esta?", "which_meaning": "O que quer dizer o treinador?", "which_term": "Como dizem isto os atiradores na sua língua?", "which_def": "O que significa este termo?", "launch": "Lançar", "again": "Outra vez", "score": "Pontuação", "play_again": "Jogar outra vez", "method": "Método", "m_maintained": "Avanço mantido (maintained lead)", "m_swing": "Swing-through (vir por trás)", "m_pullaway": "Pull-away (sair do prato)", "m_ambush": "Emboscada (ambush)", "speed": "Velocidade do prato", "distance": "Distância", "demo": "Ver o método", "try": "A sua vez: carregue quando dispararia", "shoot": "Disparar", "hit": "Acertou! O prato parte-se.", "behind": "Atrás — o chumbo passou atrás do prato", "ahead": "À frente — o chumbo passou à frente do prato", "perceived": "Avanço que vê no momento da decisão", "actual": "Avanço real no momento do disparo", "lab_note": "Câmara lenta, física simplificada para fins didácticos: velocidade média do chumbo de cerca de 330 m/s e 0,15 s entre a decisão e o disparo. O avanço real depende também do atirador, do cartucho e do ângulo.", "exam_pass": "Aprovado! Já pode obter o seu certificado.", "exam_fail": "Ainda não — são precisos 80%. Reveja as missões e tente outra vez.", "cert_name": "O seu nome para o certificado", "cert_print": "Imprimir ou guardar como PDF", "cert_title": "Certificado", "cert_text": "concluiu o curso da Academia de Intérpretes ClayArena sobre terminologia, técnica, regras da FITASC e etiqueta do Parcours de Chasse – Sporting™ e do Compak® Sporting.", "cert_note": "Certificado de autoformação da ClayArena; não constitui uma qualificação da FITASC.", "question": "Pergunta", "of": "de", "term_all": "Em todas as línguas da ClayArena", "term_note_anglicism": "Os atiradores usam muitas vezes simplesmente a palavra inglesa.", "confidence_low": "a confirmar", "reset": "Repor o progresso", "reset_confirm": "Apagar todo o progresso e XP neste dispositivo?", "saved_local": "O progresso é guardado neste dispositivo.", "disclaimer": "Curso da ClayArena. As regras da FITASC são apresentadas numa paráfrase nossa, com ligações para as páginas das regras; só o texto oficial da FITASC é vinculativo. Parcours de Chasse – Sporting™ e Compak® Sporting são marcas registadas da FITASC.", "language": "Língua", "all_missions_done": "Todas as missões concluídas — é altura do exame final!", "decision": "decisão", "shot_moment": "disparo", "lead_word": "avanço", "unit_m": "m", "unit_ft": "pés", "unit_ms": "m/s", "glossary_page": "Página no glossário", "pair_report": "Double ao tiro (on report): o 2.º prato é lançado ao som do 1.º tiro", "pair_sim": "Double simultâneo: os dois pratos são lançados ao mesmo tempo", "pair_rafale": "Rafale (following pair): o 2.º prato sai da mesma máquina logo a seguir ao 1.º"}, "missions": [{"id": "sport", "icon": "flag", "title": "A modalidade em dez minutos", "intro": "Antes de traduzir um único conselho do treinador, precisa de ter a visão geral: a que se atira realmente, quem escreve as regras, como são um percurso de Parcours de Chasse – Sporting™ e um campo de Compak® Sporting, e como decorre um dia de competição. Cinco lições curtas dão-lhe o mapa; cada missão seguinte preenche os pormenores.", "lessons": [{"id": "sport-what-is-clay", "minutes": 5, "title": "Pratos, não aves: o que é esta modalidade", "body": ["O tiro aos pratos é uma modalidade em que o atirador parte pequenos discos voadores com uma espingarda. O disco chama-se prato (em inglês target ou clay); os atiradores chamam-lhe muitas vezes «bird» (ave), mas ninguém atira a animais vivos. As regras da FITASC dizem claramente que não é permitido atirar a animais vivos, e que a segurança e o respeito pelo ambiente estão em primeiro lugar.", "Cada prato é lançado por uma máquina (em inglês trap). O caminho que percorre no ar (ou ao longo do chão) é a trajetória. A arma é uma espingarda de cano liso: dispara um cartucho cheio de pequenas esferas chamadas chumbo, que se espalham numa pequena nuvem. É por isso que o atirador aponta a arma para onde o prato vai, e não para onde ele está agora.", "Este curso trata de duas disciplinas da federação internacional FITASC. O Parcours de Chasse – Sporting™ (abreviadamente Sporting™) imita a caça: as máquinas estão escondidas em campos e bosques, e os pratos voam como perdizes, patos ou faisões, ou rolam como uma lebre. O Compak® Sporting é a versão compacta: a mesma variedade de pratos, mas num único campo pequeno, com cinco postos em linha e seis máquinas.", "Também vai ouvir falar de Fosso (Trap) e de Skeet. São disciplinas diferentes, com trajetórias fixas e repetidas; o Fosso Olímpico e o Skeet Olímpico pertencem a outra federação. Não misture as suas regras com as do Sporting™ ou do Compak® Sporting.", "Um acerto vê-se de imediato: o prato parte-se ou, pelo menos, solta-se um pedaço visível. Esta clareza torna a modalidade fácil de seguir para o público e, para si, fácil de acompanhar logo desde o primeiro dia."], "key_points": ["Atira-se a pratos lançados por máquinas, nunca a animais vivos.", "A espingarda dispara uma nuvem de pequenas esferas (chumbo), por isso o atirador aponta à frente do prato.", "O Sporting™ imita a caça em terreno natural; o Compak® Sporting é a sua versão compacta num único campo.", "O Fosso (Trap) e o Skeet são outras disciplinas, com regras próprias."], "terms": ["target", "trap", "trajectory", "shotgun", "cartridge", "sporting", "compak-sporting"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Clay pigeon shooting", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch1-definition", "label": "1 · What Sporting is"}, {"book": "sporting", "id": "ch1-safety-environment", "label": "1 · Safety, environment and no live animals"}, {"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}], "coach_says": [{"en": "Watch this bird off trap B.", "meaning": "«Bird» é um prato, não uma ave verdadeira; trap B é a máquina marcada com a letra B.", "say": "Veja bem este prato da máquina B."}, {"en": "Today we walk the Sporting course, tomorrow it's Compak.", "meaning": "Duas disciplinas diferentes em dois dias diferentes.", "say": "Hoje fazemos o percurso de Sporting, amanhã é Compak."}, {"en": "Point it, don't aim it.", "meaning": "A espingarda move-se e aponta-se com os dois olhos no prato; não se faz pontaria como com uma carabina.", "say": "Aponte, não faça pontaria."}], "quiz": [{"q": "O treinador diz «Watch the next bird.» O que vai ver?", "options": ["Um pombo vivo solto de uma caixa", "Um prato lançado por uma máquina", "Um alvo de papel em forma de ave num painel", "Um drone"], "answer": 1, "why": "«Bird» é a gíria dos atiradores para o prato; as regras da FITASC proíbem atirar a animais vivos."}, {"q": "O que dispara uma espingarda?", "options": ["Uma única bala", "Um pequeno dardo, como uma seta", "Uma nuvem de pequenas esferas (chumbo)", "Uma bola cheia de tinta"], "answer": 2, "why": "O chumbo sai da boca do cano como uma pequena nuvem de esferas, por isso o atirador aponta à frente do prato em movimento."}, {"q": "Qual das afirmações sobre o Compak® Sporting é correta?", "options": ["É uma versão compacta num só campo, com postos em linha", "É a versão olímpica da disciplina de Skeet", "Só se pratica com aves de caça vivas, no campo", "Usa uma única máquina e um único posto"], "answer": 0, "why": "O Compak® Sporting leva pratos ao estilo do Sporting™ para um único campo pequeno, com cinco postos e seis máquinas."}]}, {"id": "sport-fitasc", "minutes": 5, "title": "A FITASC, as federações e a ClayArena", "body": ["A FITASC é a federação internacional do tiro aos pratos de estilo caça. Escreve e atualiza as regras do Parcours de Chasse – Sporting™ e do Compak® Sporting; as edições que seguimos têm a data de 01/01/2025. Compak® Sporting é também uma marca protegida pela FITASC, e é por isso que o nome se escreve sempre com ®.", "A modalidade está organizada como uma pirâmide. Na base estão os clubes e os campos de tiro, acima deles as federações nacionais (em Portugal, a FPTAC), e as federações nacionais são membros da FITASC. Os percursos para competições nacionais são aprovados pela federação nacional; os das competições internacionais, pela FITASC. Uma federação pode confiar uma prova a um clube, mas continua responsável pela aplicação das regras.", "No terreno, as regras são aplicadas pelos árbitros. Cada árbitro tem um certificado de uma federação nacional, e o árbitro principal precisa de um certificado internacional da FITASC. Nas provas internacionais, um júri trata dos protestos, das penalizações e dos problemas técnicos. Vai traduzir para todos eles, por isso aprenda os títulos: árbitro (referee), árbitro principal (chief referee), júri (jury).", "Existem também outras entidades. No Reino Unido e nos EUA, associações nacionais organizam as suas próprias versões da modalidade, como o English Sporting, com regras e palavras diferentes. Um treinador britânico ou americano pode usar essas palavras numa prova FITASC; as missões seguintes mostram como lidar com isso.", "A ClayArena é a plataforma por detrás deste curso. Publica calendários de competições, um glossário e um resumo em linguagem simples das regras da FITASC e, através da ClayAway, organiza viagens de treino. Lembre-se: só o texto oficial da FITASC é vinculativo; um resumo é um guia, não a regra em si."], "key_points": ["A FITASC escreve as regras do Sporting™ e do Compak® Sporting (edições de 01/01/2025).", "Clube, federação nacional, FITASC: os percursos nacionais são aprovados pela federação, os internacionais pela FITASC.", "Os árbitros têm certificados nacionais; o árbitro principal tem um certificado internacional da FITASC; o júri aprecia os protestos.", "Só o texto oficial da FITASC é vinculativo; a ClayArena oferece um resumo."], "terms": ["fitasc", "national-federation", "referee", "chief-referee", "jury"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}, {"book": "sporting", "id": "ch15-layout-approval", "label": "15 · Who approves layouts"}, {"book": "sporting", "id": "ch15-delegation", "label": "15 · Delegating to a club"}, {"book": "sporting", "id": "ch5-referee-certificate", "label": "5 · Referee certificates"}, {"book": "sporting", "id": "ch15-jury-role", "label": "15 · Duties of the jury"}, {"book": "compak", "id": "ch19-referee-qualification", "label": "19 · Referee approval and qualifications"}], "coach_says": [{"en": "That's a CPSA term — under FITASC it's a simultaneous double.", "meaning": "O treinador passa do vocabulário britânico para o nome usado pela FITASC.", "say": "Isso é um termo da CPSA — na FITASC chama-se double simultâneo."}, {"en": "Ask the chief referee, not the stand referee.", "meaning": "A pergunta é para o oficial mais graduado da competição.", "say": "Pergunte ao árbitro principal, não ao árbitro do posto."}, {"en": "The jury will decide this one.", "meaning": "O assunto ultrapassa o árbitro do posto e passa para o júri da competição.", "say": "Isto quem decide é o júri."}], "quiz": [{"q": "Quem aprova os percursos de uma competição internacional de Sporting™?", "options": ["O clube local", "A federação nacional", "O árbitro do dia", "A FITASC"], "answer": 3, "why": "Os percursos nacionais são aprovados pela federação nacional; os internacionais, pela FITASC."}, {"q": "Que certificado tem de ter o árbitro principal?", "options": ["Um certificado internacional da FITASC", "Apenas o cartão de sócio de um clube", "Uma licença nacional de treinador do seu clube", "Nenhum: qualquer atirador experiente pode sê-lo"], "answer": 0, "why": "Os árbitros de posto precisam de um certificado nacional; o árbitro principal precisa de um certificado internacional da FITASC."}, {"q": "Durante uma disputa, um cliente mostra-lhe o resumo das regras da ClayArena. Que valor tem?", "options": ["Prevalece sobre o texto oficial da FITASC", "É apenas um guia; o texto da FITASC é vinculativo", "É vinculativo, mas só no Compak® Sporting", "Substitui a decisão do árbitro no posto"], "answer": 1, "why": "Um resumo ajuda a compreender as regras, mas o árbitro e o júri aplicam o texto oficial da FITASC."}]}, {"id": "sport-sporting-layout", "minutes": 5, "title": "Um percurso de Sporting™: percursos, postos e máquinas", "body": ["No Parcours de Chasse – Sporting™ o terreno divide-se em percursos (em inglês layouts). Um percurso é um grupo de postos de tiro que, em conjunto, dão 25 pratos: 15 simples e 5 doubles. Consoante o sistema, um percurso tem três, quatro ou cinco postos, cada um com as suas máquinas.", "O posto de tiro (em inglês stand) é o sítio onde o atirador se coloca: um quadrado de 1 m ou um círculo com 1 m de diâmetro, nivelado e não escorregadio. Cuidado com a palavra «stand» em português: costuma designar o campo de tiro inteiro («stand de tiro»), por isso traduza stand como «posto de tiro» ou «posto». O resto da esquadra espera perto, o suficiente para acompanhar, mas sem nunca distrair o atirador.", "As máquinas são colocadas de acordo com o terreno, muitas vezes parcialmente escondidas por arbustos ou árvores, para que os pratos pareçam caça verdadeira: transversais, de entrada, de saída, em diagonal, altos ou baixos, a descoberto ou através das árvores. As máquinas de um posto são identificadas com as letras A, B, C, D, lidas da esquerda para a direita, vistas do posto.", "À frente de cada posto há um menu de tiro: indica as máquinas pela ordem de tiro e assinala os pratos especiais, como um prato de 90 mm, 70 mm ou 60 mm, uma batida (battue) ou um coelho. O atirador lê-o antes de entrar no posto, e o intérprete também deve lê-lo.", "As trajetórias são classificadas por dificuldade. Um prato de classe A é partido por um atirador médio em mais de 80% das vezes, um de classe B em 60 a 80%, um de classe C em 40 a 60%. Ou seja, um prato de classe C é feito para ser difícil; falhá-lo não é nenhum desastre."], "key_points": ["Um percurso dá 25 pratos: 15 simples e 5 doubles.", "Um posto é um quadrado de 1 m ou um círculo de 1 m; traduza stand como «posto de tiro», não como «stand».", "As máquinas têm as letras A, B, C, D, da esquerda para a direita, vistas do posto.", "O menu de tiro mostra a ordem das máquinas e os pratos especiais.", "Classes de dificuldade: A mais de 80%, B 60–80%, C 40–60%."], "terms": ["layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "difficulty-class"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}], "coach_says": [{"en": "Layout three is the hard one today — lots of minis in the trees.", "meaning": "No terceiro percurso há muitos pratos pequenos a voar através das árvores.", "say": "O percurso três é o difícil hoje — muitos minis no meio das árvores."}, {"en": "On this stand, read the menu before you step in.", "meaning": "Verifique primeiro a ordem das máquinas e os pratos especiais.", "say": "Neste posto, leia o menu antes de entrar."}, {"en": "Stand two is a class C target, don't worry about it.", "meaning": "O prato está classificado como difícil; é normal falhá-lo.", "say": "O posto dois é um prato de classe C, não se preocupe com ele."}], "quiz": [{"q": "Quantos pratos dá um percurso de Sporting™?", "options": ["10", "20", "25", "50"], "answer": 2, "why": "Todos os tipos de percurso dão 25 pratos: 15 simples e 5 doubles."}, {"q": "O treinador diz «Go to stand two.» Como traduz «stand»?", "options": ["«stand» (o campo de tiro)", "«posto de tiro»", "«bancada»", "«armeiro» (suporte de armas)"], "answer": 1, "why": "No Sporting™, o stand é a posição de tiro de 1 m; em português, «stand» designa normalmente o campo de tiro inteiro."}, {"q": "Como se identificam as máquinas de um posto de Sporting™?", "options": ["Por números de 1 a 6, contados a partir da direita", "Por cores pintadas em cada máquina", "Pelas letras A, B, C, D, da esquerda para a direita", "Pelo nome da pessoa que as aciona"], "answer": 2, "why": "As letras A, B, C, D leem-se da esquerda para a direita, vistas do posto, e são usadas no menu e na folha de marcação."}]}, {"id": "sport-compak-layout", "minutes": 5, "title": "Um campo de Compak® Sporting: cinco postos, seis máquinas", "body": ["O Compak® Sporting cabe num único campo. À frente dos atiradores há um retângulo obrigatório, com 35 a 40 m de largura e 25 m de profundidade, marcado por quatro estacas com bandeiras nos cantos. Sem vento, todos os pratos têm de o sobrevoar em algum momento.", "Cinco postos de tiro, cada um um quadrado de 1 m, estão em linha, com 2 a 5 m entre os seus centros. São numerados de 1 a 5 da esquerda para a direita. Cada posto tem um limitador de ângulo de tiro (Firing Angle Limiter, L.A.T.), uma estrutura de tubos que impede a arma de rodar demasiado para os lados ou para cima e impede o atirador de avançar.", "Seis máquinas, de A a F da esquerda para a direita, têm cada uma um painel com a sua letra. Podem estar à frente, dos lados, atrás dos atiradores ou numa torre; uma máquina atrás da linha tem de estar pelo menos 4 m acima dela. Todos os campos de Compak têm três pratos obrigatórios: um transversal da esquerda para a direita, um transversal da direita para a esquerda e um prato de saída.", "Uma série tem 25 pratos, cinco em cada posto. Quando atira uma esquadra de seis, cinco atiradores ficam nos postos e o sexto espera atrás do posto 1. Cada atirador atira, à vez, os cinco pratos do menu do seu posto, começando pelo posto 1. Quando o posto 5 termina, esse atirador vai esperar atrás do posto 1, todos os outros avançam um posto para a direita e o atirador que estava à espera entra no posto 1.", "Algumas provas fazem o Compak® Sporting em linha: cada atirador começa no posto 1 e termina no posto 5. Pergunte ao organizador qual o sistema usado, porque o procedimento é diferente."], "key_points": ["Um retângulo de 35–40 m × 25 m que todos os pratos têm de atravessar.", "Cinco postos de 1 m em linha, a 2–5 m uns dos outros, cada um com um limitador de ângulo de tiro.", "Seis máquinas com as letras A a F, da esquerda para a direita; uma máquina atrás da linha fica numa torre com pelo menos 4 m de altura.", "25 pratos por série, cinco por posto; a esquadra roda um posto para a direita.", "O Compak® Sporting pode atirar-se por esquadras ou em linha."], "terms": ["fly-over-rectangle", "firing-angle-limiter", "shooting-stand", "trap", "tower", "rotation", "waiting-position", "line"], "sources": [{"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Everybody move one to the right. Number five, to the waiting position.", "meaning": "A esquadra roda; o atirador do posto 5 vai para trás do posto 1.", "say": "Todos um posto para a direita. O número cinco, para a posição de espera."}, {"en": "Trap E is the tower — it comes over your head.", "meaning": "O prato da máquina E é lançado de uma torre alta e passa por cima da cabeça.", "say": "A máquina E é a da torre — o prato passa-lhe por cima da cabeça."}, {"en": "Mind the frame — don't swing past the post.", "meaning": "Respeite o limitador de ângulo de tiro; não rode a arma para lá dele.", "say": "Atenção à estrutura — não passe com a arma para lá do tubo."}], "quiz": [{"q": "Quantas máquinas e quantos postos tem um campo de Compak® Sporting?", "options": ["4 máquinas, 3 postos", "6 máquinas, 5 postos", "5 máquinas, 6 postos", "8 máquinas, 8 postos"], "answer": 1, "why": "Máquinas de A a F e postos de 1 a 5."}, {"q": "Numa esquadra de seis, onde está o sexto atirador enquanto os outros atiram?", "options": ["Na sede do clube", "Ao lado do árbitro, no posto 5", "Atrás da máquina F", "À espera atrás do posto 1"], "answer": 3, "why": "O atirador em espera fica atrás do posto 1 e entra nele depois de cada rotação."}, {"q": "Para que serve o limitador de ângulo de tiro?", "options": ["Limita o movimento da arma e impede o atirador de avançar", "Mede a velocidade de cada prato lançado", "Guarda os cartuchos para toda a série", "Lança os pratos quando o atirador os pede"], "answer": 0, "why": "É uma estrutura de segurança em cada posto que limita o movimento lateral e vertical da arma."}]}, {"id": "sport-competition-day", "minutes": 5, "title": "Um dia de competição do princípio ao fim", "body": ["O dia começa com o secretariado: o atirador confirma a inscrição, recebe um dorsal (número de competidor) e prende-o na parte de cima das costas, bem visível. Depois todos verificam as listas das esquadras e os horários de tiro. Cumprir o horário é responsabilidade do próprio atirador.", "Uma esquadra (em inglês squad) é um grupo de até seis atiradores, sorteados, que atiram juntos. Na ClayAway, a palavra squad designa também um subgrupo de uma viagem, por isso deixe claro de qual está a falar. No Parcours de Chasse – Sporting™ a esquadra atira primeiro todos os pratos simples de um posto e depois os doubles, e a ordem de tiro roda de posto para posto. O primeiro atirador da esquadra vê a mostra dos pratos antes de alguém atirar.", "Uma série tem 25 pratos: um percurso no Sporting™, um campo no Compak® Sporting. Uma competição internacional tem 200 pratos, ou seja, oito séries ao longo de vários dias. O árbitro marca cada prato na folha de marcação, normalmente X para um acerto e O para uma falha. No Sporting™ os atiradores verificam o resultado ao sair de um posto; no Compak® Sporting assinam a folha no fim da série.", "Chegar atrasado sai caro. No Sporting™ o árbitro chama o nome três vezes no espaço de um minuto; o atirador que perde a sua vez leva zeros nos pratos que não atirou. No Compak® Sporting, o atirador que chega depois de o primeiro atirador da esquadra ter pedido o prato leva 25 zeros nessa série.", "Se houver empate nos três primeiros lugares, faz-se um desempate (shoot-off, barrage): 25 pratos e depois morte súbita. Os empates nos lugares abaixo resolvem-se pela ordem inversa (countback), comparando primeiro a última série. O dia termina com o quadro de resultados e a entrega de prémios."], "key_points": ["Secretariado, dorsal nas costas, listas das esquadras e horários.", "Uma esquadra tem até seis atiradores sorteados; no Sporting™, primeiro os simples, depois os doubles, com ordem rotativa.", "Uma série tem 25 pratos; as provas internacionais têm 200 pratos.", "O atraso custa zeros; no Compak® Sporting, 25 zeros na série.", "Empates nos três primeiros lugares: desempate de 25 e depois morte súbita; empates abaixo: ordem inversa (countback)."], "terms": ["entry", "competitor-number", "squad", "round", "rotation", "score-sheet", "shoot-off", "countback", "prize-giving"], "sources": [{"title": "Let's Go Shooting — NSCA beginner's guide to sporting clays", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}], "coach_says": [{"en": "You're in squad twelve, starting on layout five at nine-thirty.", "meaning": "Número da esquadra, percurso de partida e hora de início.", "say": "Está na esquadra doze, começa no percurso cinco às nove e meia."}, {"en": "Check your card before you leave the stand.", "meaning": "Confirme agora que o árbitro registou corretamente o seu resultado; mais tarde já é tarde demais.", "say": "Verifique a sua folha antes de sair do posto."}, {"en": "Twenty-two in the first round is fine — seven more to go.", "meaning": "22 em 25 na primeira série; numa prova de 200 pratos faltam sete séries.", "say": "Vinte e dois na primeira série está bem — faltam mais sete."}, {"en": "Stay close — if it's a tie, you shoot within fifteen minutes of the call.", "meaning": "Um atirador que possa ir a desempate tem de estar pronto pouco depois de ser chamado.", "say": "Fique por perto — se houver empate, atira até quinze minutos depois da chamada."}], "quiz": [{"q": "Quantos pratos tem uma competição internacional da FITASC?", "options": ["50", "100", "150", "200"], "answer": 3, "why": "200 pratos, em séries de 25."}, {"q": "No Compak® Sporting por esquadras, um atirador chega depois de o primeiro atirador ter pedido o primeiro prato. O que acontece?", "options": ["Nada, junta-se aos outros", "Leva 25 zeros nessa série", "Atira a série sozinho mais tarde, sem penalização", "Perde um prato"], "answer": 1, "why": "No Compak® Sporting por esquadras, quem chega depois do primeiro pedido de prato leva 25 zeros; por motivo válido, é possível recorrer ao júri."}, {"q": "Dois atiradores empatam no 5.º lugar. Como se desempatam?", "options": ["Com um desempate de 25 pratos", "Por sorteio depois da prova", "Pela ordem inversa, a partir da última série", "Pela idade, o mais novo primeiro"], "answer": 2, "why": "Os desempates (shoot-off) são só para os três primeiros; abaixo disso, a ordem inversa compara a 8.ª série, depois a 7.ª e assim por diante."}]}]}, {"id": "gear", "icon": "tool", "title": "Arma e equipamento", "intro": "Os treinadores falam da arma o dia inteiro: «raise the comb» (subir a crista), «check your selector» (verificar o seletor), «change chokes» (trocar os chokes), «nines in the bottom» (nove em baixo). Esta missão dá-lhe as palavras para a arma, as suas peças, os chokes, os cartuchos e o equipamento de proteção, juntamente com as poucas regras de equipamento que qualquer intérprete tem de conhecer.", "lessons": [{"id": "gear-gun-types", "minutes": 5, "title": "Tipos de espingarda e o que as regras permitem", "body": ["Todas as armas que vai ver no posto de tiro são espingardas de cano liso. Em quase todos os postos de competição trata-se de uma sobreposta (over-and-under, O/U): dois canos, um por cima do outro, que se abre «quebrando» a arma pela charneira. Cada cano pode ter o seu próprio choke, o que é importante nos doubles.", "Uma paralela (side-by-side, canos justapostos) tem dois canos lado a lado. É a arma clássica de caça e é permitida, mas raramente se vê em competição. Não traduza over-and-under simplesmente como «espingarda de dois canos»: essa expressão abrange os dois tipos.", "Uma semi-automática (muitas vezes chamada apenas «automática») tem um só cano e recarrega-se sozinha depois de cada tiro, atirando o invólucro vazio para o lado. A FITASC permite-a, com condições: no máximo dois cartuchos na arma, a culatra aberta sempre que é transportada e, no Compak® Sporting, um dispositivo que impeça os invólucros ejetados de atingir o vizinho.", "As espingardas de bomba (pump-action), recarregadas deslizando o fuste com a mão, não são permitidas no Parcours de Chasse – Sporting™ nem no Compak® Sporting. Os regulamentos limitam-se a enunciar a proibição sem dar qualquer razão, por isso não invente uma quando um cliente perguntar; diga apenas que é a regra. O Compak® Sporting proíbe também os drillings, armas que combinam canos de espingarda e de carabina.", "Há mais dois limites nas duas disciplinas: o calibre não pode ser superior a 12 (portanto, o calibre 20 é aceite) e os canos têm de ter pelo menos 66 cm de comprimento. São proibidas as bandoleiras, as câmaras montadas na arma e qualquer dispositivo artificial de pontaria."], "key_points": ["A maioria dos atiradores usa uma sobreposta (over-and-under).", "As semi-automáticas são permitidas: no máximo dois cartuchos, culatra aberta durante o transporte, coletor de invólucros no Compak® Sporting.", "As espingardas de bomba são proibidas nas duas disciplinas; as regras não dão a razão.", "Calibre não superior a 12, canos com pelo menos 66 cm, sem bandoleiras nem dispositivos de pontaria."], "terms": ["shotgun", "over-and-under", "side-by-side", "semi-automatic", "pump-action", "gauge", "barrel-length", "shell-catcher"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-semi-auto", "label": "18 · Semi-automatics: shell catcher and two cartridges"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}], "coach_says": [{"en": "Bring your over-and-under and a spare set of chokes.", "meaning": "A arma de competição de dois canos, mais tubos de choke de reserva.", "say": "Traga a sua sobreposta e um jogo de chokes de reserva."}, {"en": "With a semi-auto, keep the bolt open until you're on the stand.", "meaning": "Regra de segurança: uma semi-automática transporta-se com a culatra aberta.", "say": "Com a automática, mantenha a culatra aberta até estar no posto."}, {"en": "No pumps on this ground.", "meaning": "As espingardas de bomba não são aceites.", "say": "Neste campo não se admitem espingardas de bomba."}], "quiz": [{"q": "Que arma NÃO é permitida no Sporting™ e no Compak® Sporting da FITASC?", "options": ["Uma sobreposta de calibre 20", "Uma paralela", "Uma espingarda de bomba", "Uma semi-automática com dois cartuchos"], "answer": 2, "why": "As espingardas de bomba são proibidas; as outras são permitidas se cumprirem os limites de calibre e de canos."}, {"q": "Quantos cartuchos pode ter uma semi-automática?", "options": ["Um", "Dois", "Três", "Tantos quantos couberem no carregador"], "answer": 1, "why": "Os dois regulamentos limitam a semi-automática a dois cartuchos."}, {"q": "Um cliente pergunta porque são proibidas as espingardas de bomba. Qual é a resposta honesta?", "options": ["As regras enunciam a proibição sem a explicar", "O regulamento diz que são demasiado lentas para os doubles", "O regulamento diz que são menos seguras", "Na verdade são permitidas no Compak® Sporting"], "answer": 0, "why": "Os regulamentos não dão qualquer razão; como intérprete, transmita a regra e não invente explicações."}]}, {"id": "gear-gun-parts", "minutes": 5, "title": "As peças da arma, do ombro à boca do cano", "body": ["Os treinadores nomeiam constantemente as peças da arma, por isso aprenda-as de trás para a frente. A coronha (stock) apoia-se no ombro. A sua aresta superior, onde assenta a face, é a crista (comb); «raise the comb» ou «drop the comb» (subir ou baixar a crista) tem a ver com a adaptação da coronha. A parte estreita agarrada pela mão do gatilho é o punho (grip), e a almofada de borracha na extremidade é a chapa de coice (recoil pad).", "A parte central metálica da arma é a báscula (receiver ou action). Em cima fica a alavanca de abertura (top lever): empurre-a para o lado e a arma abre. Atrás dela está a patilha de segurança (safety catch), muitas vezes combinada com o seletor de canos (barrel selector, «selector»), que decide qual dos canos dispara primeiro. Por baixo está o gatilho (trigger), dentro do guarda-mato.", "Um gatilho de libertação (release trigger) dispara quando é solto, e não quando é premido. Uma arma assim tem de ter, como aviso, um autocolante com um «R» grande sobre fundo fluorescente no lado exterior da coronha.", "Por baixo dos canos, a outra mão segura o fuste (fore-end). Os canos (barrels) têm atrás as câmaras para os cartuchos e à frente as bocas (muzzles), onde se enroscam os chokes. Por cima corre a fita (rib), com um ponto de mira (bead) na ponta. O ponto de mira é uma referência, não uma mira: «look at the target, not the bead» (olhe para o prato, não para o ponto de mira).", "Dois falsos amigos: rib não é «costela», e «break the gun» quer dizer abrir a arma, não parti-la. E uma regra de segurança ligada às peças: depois de uma falha de percussão ou de qualquer outra falha da arma ou do cartucho, o atirador não pode abrir a arma nem tocar na patilha de segurança até o árbitro a ter examinado."], "key_points": ["Coronha, crista, punho, chapa de coice; báscula com alavanca de abertura, segurança e seletor; gatilho.", "Fuste, canos com câmaras e bocas, fita com ponto de mira.", "Um gatilho de libertação exige um autocolante com «R» na coronha.", "Rib ≠ «costela»; break the gun = abrir a arma.", "Depois de uma falha de percussão: não abrir a arma nem tocar na segurança antes de o árbitro verificar."], "terms": ["stock", "comb", "grip", "recoil-pad", "receiver", "top-lever", "safety-catch", "barrel-selector", "trigger", "release-trigger", "fore-end", "barrel", "chamber", "muzzle", "rib", "bead"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-release-trigger-marking", "label": "7 · Release trigger: mandatory 'R' sticker"}, {"book": "compak", "id": "ch18-release-trigger-marking", "label": "18 · Release trigger: the 'R' sticker"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}], "coach_says": [{"en": "You're seeing too much rib — your head is up.", "meaning": "O olho está demasiado alto em relação à fita, normalmente porque a cabeça se levanta da crista.", "say": "Está a ver fita a mais — está a levantar a cabeça."}, {"en": "Check your selector — you fired the top barrel first.", "meaning": "O seletor de canos está posto ao contrário.", "say": "Verifique o seletor — disparou primeiro o cano de cima."}, {"en": "Break your gun and show me it's clear.", "meaning": "Abra a arma e mostre as câmaras vazias.", "say": "Abra a arma e mostre-me que está descarregada."}, {"en": "Forget the bead — look at the target.", "meaning": "Concentre-se no prato, não na ponta do cano.", "say": "Esqueça o ponto de mira — olhe para o prato."}], "quiz": [{"q": "O treinador diz «Raise the comb». De que peça está a falar?", "options": ["Da parte de cima da coronha, onde assenta a face", "Do pequeno ponto de mira na ponta da fita", "Do guarda-mato à volta do gatilho", "Do tubo de choke na boca do cano"], "answer": 0, "why": "A crista é a parte de cima da coronha; subi-la levanta o olho acima da fita."}, {"q": "O que tem de ter uma arma com gatilho de libertação?", "options": ["Um cano pintado de vermelho para avisar os outros", "Um autocolante com um «R» grande na coronha", "Uma segunda patilha de segurança, separada", "Nada: não é exigida qualquer marcação"], "answer": 1, "why": "Os dois regulamentos exigem o autocolante de aviso com «R», sobre fundo fluorescente, no lado exterior da coronha."}, {"q": "Como traduz «Break your gun»?", "options": ["«Parta a arma»", "«Desmonte a arma peça a peça»", "«Abra a arma»", "«Limpe os canos da arma»"], "answer": 2, "why": "Num campo de tiro, «break» significa abrir a arma pela charneira, para que não possa disparar."}]}, {"id": "gear-chokes", "minutes": 5, "title": "Chokes: para que servem e como falam deles os treinadores", "body": ["Um choke (choque, estrangulamento) é um ligeiro estreitamento do cano junto à boca. Controla a rapidez com que o chumbo se espalha. Mais estrangulamento mantém o chumbo junto durante mais tempo, dando uma chumbada mais apertada para pratos distantes; menos estrangulamento espalha-o mais cedo, dando uma chumbada mais larga e mais tolerante para pratos próximos.", "A maioria das armas de competição tem chokes intermutáveis: tubos curtos que se enroscam na boca do cano com uma chave de chokes. As armas mais antigas podem ter chokes fixos, maquinados no próprio cano. Os tubos de marcas diferentes muitas vezes não são compatíveis, e os fabricantes avisam que nunca se deve disparar uma arma de chokes intermutáveis sem os tubos.", "Os nomes vêm do inglês, do mais aberto para o mais apertado: cylinder, skeet, improved cylinder, light modified, modified, improved modified, full. Na Europa é comum dizê-los em frações: um quarto (1/4 de choke, improved cylinder), meio (1/2 choke, modified), três quartos (3/4 de choke, improved modified) e full (full choke). Muitas armas italianas marcam os chokes com estrelas, e aí a regra é ao contrário: mais estrelas significa um choke mais aberto.", "Os treinadores dizem coisas como «quarter and half» (um quarto e meio), «open up the bottom barrel» (abrir o cano de baixo), «go tighter in the top» (apertar mais no cano de cima) ou «change chokes for this stand» (trocar os chokes para este posto). Mantenha os nomes exatamente como o treinador os diz; não os converta em milímetros, que variam de fabricante para fabricante.", "As regras diferem entre as disciplinas. No Parcours de Chasse – Sporting™ os chokes podem ser trocados entre postos ou entre os simples e os doubles, desde que isso não cause atraso, mas nunca depois de o atirador ter entrado no posto. No Compak® Sporting, a arma, os canos e os chokes não podem ser trocados de todo durante uma série, só entre séries, exceto em caso de avaria."], "key_points": ["O choke estreita a boca do cano: mais apertado para pratos distantes, mais aberto para pratos próximos.", "Os tubos intermutáveis enroscam-se com uma chave de chokes; os fabricantes avisam que nunca se deve disparar sem eles.", "Frações: um quarto = improved cylinder, meio = modified, três quartos = improved modified, full.", "Mantenha os nomes dos chokes tal como são ditos; não converta em milímetros.", "Sporting™: trocar entre postos, nunca no posto; Compak®: nenhuma troca durante uma série."], "terms": ["choke", "multichoke", "fixed-choke", "choke-key", "cylinder", "skeet-choke", "improved-cylinder", "modified", "improved-modified", "full-choke", "pattern"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Beretta — Choke tubes identification", "url": "https://estore.beretta.com/en-gb/utility/choke-tubes-identification"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}], "coach_says": [{"en": "What chokes are you using? — Quarter and half.", "meaning": "Improved cylinder num cano, modified no outro.", "say": "Que chokes está a usar? — Um quarto e meio."}, {"en": "Put quarter in the bottom and half in the top — the second bird is longer.", "meaning": "Choke mais aberto para o primeiro prato, mais próximo; mais apertado para o segundo, mais distante.", "say": "Ponha um quarto no cano de baixo e meio no de cima — o segundo prato está mais longe."}, {"en": "Open up — these are all close.", "meaning": "Monte chokes mais abertos, porque os pratos estão perto.", "say": "Abra os chokes — estes estão todos perto."}, {"en": "Check your tubes are tight before the round.", "meaning": "Confirme que os tubos de choke não se desapertaram.", "say": "Verifique se os chokes estão bem apertados antes da série."}], "quiz": [{"q": "Que choke dá a chumbada mais larga?", "options": ["Full", "Improved modified", "Modified", "Cylinder"], "answer": 3, "why": "O cylinder (cilíndrico) não tem estrangulamento, por isso o chumbo espalha-se mais cedo."}, {"q": "No Sporting™, um atirador que já está no posto quer trocar um choke. É permitido?", "options": ["Sim, desde que não cause atraso", "Não, depois de estar no posto já não", "Sim, mas só antes dos doubles", "Só com autorização do júri"], "answer": 1, "why": "As trocas são permitidas entre postos ou entre simples e doubles, sem atraso, mas nunca depois de o atirador ter entrado no posto."}, {"q": "Numa arma italiana, um choke com cinco estrelas é…", "options": ["o mais aberto", "o mais apertado", "um choke partido", "um cano de carabina"], "answer": 0, "why": "Com a marcação em estrelas, mais estrelas significa um choke mais aberto."}]}, {"id": "gear-cartridges", "minutes": 5, "title": "Cartuchos: calibre, número do chumbo e limites", "body": ["Um cartucho (cartridge) contém tudo o que é preciso para um tiro: o invólucro (hull) com uma base metálica, o fulminante (primer), a pólvora (powder), a bucha (wad) e o chumbo (shot). Os atiradores também dizem shell. «Empties» são os cartuchos vazios, já disparados.", "O calibre (gauge) conta-se à maneira antiga: quanto menor o número, mais largo o cano, por isso o calibre 12 é mais largo do que o 20. A FITASC permite armas até ao calibre 12, e a maioria dos atiradores usa o 12. Nunca traduza «12 gauge» como «12 mm».", "O número do chumbo também funciona ao contrário: quanto maior o número, mais pequena a esfera, por isso o n.º 9 é mais fino do que o n.º 7,5. O mesmo número pode corresponder a tamanhos ligeiramente diferentes no Reino Unido, na Europa continental e nos EUA, por isso diga o número tal como foi dado e confirme os milímetros na caixa. «Nines» (nove) e «seven-and-a-halfs» (sete e meio) são palavras comuns dos treinadores.", "As regras do Parcours de Chasse – Sporting™ e do Compak® Sporting são iguais: no máximo 28 g de chumbo, com uma tolerância de +2%; esferas redondas de 2,0 a 2,5 mm (±0,1 mm). São proibidos os cartuchos recarregados, os dispersantes, a mistura de números de chumbo, a pólvora negra e os traçadores. No Sporting™ o árbitro pode recolher dois cartuchos para verificação, um de cada bolso do colete; no Compak® Sporting, os tiros disparados com cartuchos não conformes antes de uma inspeção contam como zero.", "Alguns campos acrescentam as suas próprias regras ambientais para os treinos, por exemplo só buchas de feltro ou só chumbo de aço: verifique as regras do campo antes da viagem. Os invólucros vazios vão para o recipiente do posto, e os atiradores com semi-automáticas apanham os seus invólucros ejetados quando saem."], "key_points": ["Cartucho = invólucro, fulminante, pólvora, bucha, chumbo.", "Calibre: número menor, cano mais largo; o máximo da FITASC é o calibre 12.", "Número do chumbo: número maior, esfera mais pequena; a numeração varia de país para país, confirme os milímetros.", "Limites: 28 g de chumbo (+2%), esferas de 2,0–2,5 mm; sem recargas, mistura de chumbo, pólvora negra nem traçadores.", "Os vazios vão para o recipiente; quem usa semi-automática apanha os seus invólucros."], "terms": ["cartridge", "hull", "primer", "powder", "wad", "shot-size", "load-weight", "gauge", "lead-shot", "steel-shot", "empties"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}, {"book": "compak", "id": "ch18-cartridge-bans", "label": "18 · Prohibited ammunition"}, {"book": "sporting", "id": "ch7-cartridge-check", "label": "7 · Cartridge checks by the referee"}, {"book": "compak", "id": "ch23-noncompliant-equipment", "label": "23 · Shots with non-compliant guns or ammunition"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "compak", "id": "ch18-empty-cases", "label": "18 · Disposing of empty cases"}], "coach_says": [{"en": "Nines for the close stuff, seven-and-a-halfs for the long crossers.", "meaning": "Chumbo mais fino n.º 9 para os pratos próximos, n.º 7,5, maior, para os transversais distantes.", "say": "Nove para os pratos perto, sete e meio para os transversais compridos."}, {"en": "Maximum twenty-eight grams on this shoot.", "meaning": "O limite de carga da competição, como nas regras da FITASC.", "say": "Nesta prova, no máximo vinte e oito gramas."}, {"en": "Empties in the bin, please, not on the grass.", "meaning": "Ponha os invólucros disparados no recipiente.", "say": "Os vazios no recipiente, por favor, não na relva."}, {"en": "Steel only on this ground.", "meaning": "Neste campo não são permitidos cartuchos com chumbo (é uma regra local, não da FITASC).", "say": "Neste campo, só chumbo de aço."}], "quiz": [{"q": "Qual é o chumbo mais fino?", "options": ["N.º 7", "N.º 7,5", "N.º 8", "N.º 9"], "answer": 3, "why": "Quanto maior o número do chumbo, mais pequena a esfera."}, {"q": "Qual é a carga máxima de chumbo segundo as regras da FITASC?", "options": ["24 g, sem tolerância", "28 g, com uma tolerância de +2%", "32 g, só para pratos distantes", "Sem limite, qualquer carga é permitida"], "answer": 1, "why": "As duas disciplinas permitem no máximo 28 g de chumbo, +2%."}, {"q": "Um cliente diz que a sua arma é «12 gauge». O que significa?", "options": ["O calibre do cano: mais largo do que o calibre 20", "O cano tem 12 milímetros de diâmetro", "Cabem doze cartuchos no carregador", "Os canos têm 12 polegadas de comprimento"], "answer": 0, "why": "O calibre é uma unidade antiga: quanto menor o número, mais largo o cano. Não são milímetros."}]}, {"id": "gear-protection-clothes", "minutes": 5, "title": "Proteção, colete e vestuário", "body": ["As proteções auditivas são obrigatórias para todos os que estão num percurso ou perto dele: atiradores, árbitros, pessoal e espectadores, e isso inclui o intérprete. Servem tanto os tampões auditivos (earplugs) como os abafadores (ear muffs); os abafadores eletrónicos amplificam as vozes e cortam o estampido, o que o ajuda a ouvir o treinador e o árbitro. Um atirador que chegue ao posto sem proteção é considerado ausente.", "Os óculos de proteção (safety glasses) também são obrigatórios, para atiradores, árbitros e pessoal e, no Parcours de Chasse – Sporting™, para quem estiver perto de um posto. As lentes existem em várias cores (amarelo, laranja, roxo, fumado) para ajudar a ver os pratos com luzes diferentes.", "O colete de tiro (shooting vest) leva os cartuchos em dois bolsos à frente e tem uma almofada no ombro. Para o Sporting™, tem uma linha horizontal contrastante 25 cm abaixo do eixo dos ombros: antes de pedir o prato, a parte de cima da coronha tem de ficar abaixo dela, e o árbitro verifica-o. O Compak® Sporting não tem essa linha, porque a posição da arma no momento do pedido é livre.", "As regras de vestuário são iguais nas duas disciplinas: nada de calções curtos (só calções compridos que terminem no máximo 5 cm acima do joelho), camisolas com pelo menos manga curta, nada de colete sobre o tronco nu e nada de sandálias, por razões de segurança. O dorsal usa-se nas costas, bem visível. Uma infração dá primeiro uma advertência e depois outras penalizações.", "Muitos atiradores usam também um boné com pala contra o sol e a chuva, luvas, e levam uma bolsa de cartuchos com a munição do dia. Isto é costume, não regra."], "key_points": ["As proteções auditivas são obrigatórias para todos os que estão perto de um percurso, intérpretes incluídos.", "Os óculos de proteção são obrigatórios; sem proteção, o atirador é considerado ausente.", "Colete de Sporting™: linha contrastante 25 cm abaixo do eixo dos ombros; o Compak® não tem.", "Vestuário: calções no máximo 5 cm acima do joelho, mangas, sem tronco nu por baixo do colete, sem sandálias.", "Dorsal nas costas, bem visível."], "terms": ["hearing-protection", "earplugs", "electronic-ear-muffs", "safety-glasses", "shooting-vest", "jacket-line", "dress-code", "competitor-number", "cartridge-bag"], "sources": [], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}], "coach_says": [{"en": "Ears and eyes on before you walk up.", "meaning": "Ponha as proteções auditivas e os óculos antes de se aproximar do posto.", "say": "Proteções e óculos postos antes de se aproximar."}, {"en": "Butt under the tape until you see the target.", "meaning": "Regra da arma em baixo no Sporting™: a coronha fica abaixo da linha do colete até o prato aparecer.", "say": "Coronha abaixo da fita até ver o prato."}, {"en": "No marker needed here — it's Compak.", "meaning": "O Compak® não exige a linha no colete.", "say": "Aqui não é preciso marca — é Compak."}], "quiz": [{"q": "Está a trabalhar como intérprete perto do posto. Tem de usar proteções auditivas?", "options": ["Não, só os atiradores que estão no posto", "Só nas finais e nos desempates", "Sim, todos os que estão num percurso ou perto dele", "Só se o árbitro lho pedir"], "answer": 2, "why": "As proteções auditivas são obrigatórias para atiradores, árbitros, pessoal e espectadores."}, {"q": "Onde fica a linha do colete no Sporting™?", "options": ["25 cm abaixo do eixo dos ombros", "Na cintura, à altura do cinto", "Na manga do braço que atira", "No Sporting™ não existe"], "answer": 0, "why": "A linha contrastante fica 25 cm abaixo do eixo dos ombros, paralela a ele; a coronha tem de ficar abaixo dela antes de o prato aparecer."}, {"q": "Que calçado é proibido nas duas disciplinas?", "options": ["Sapatilhas de trilho", "Sandálias", "Botas", "Sapatilhas"], "answer": 1, "why": "As sandálias são proibidas por razões de segurança."}]}]}, {"id": "targets", "icon": "target", "title": "Pratos", "intro": "Um treinador que diz «it's a midi off the tower, then a rabbit on report» (é um midi da torre e depois um coelho ao tiro) parte do princípio de que consegue imaginar a cena. Esta missão ensina os tipos de prato, como a cor e a luz mudam o que o atirador vê, como as máquinas lançam os pratos, como ler um menu de tiro e a única questão de pontuação que decide tudo: acerto ou falha.", "lessons": [{"id": "targets-types", "minutes": 5, "title": "Tipos de prato: normal, midi, mini, batida, coelho, flash, ZZ", "body": ["A lista da FITASC para o Parcours de Chasse – Sporting™ indica sete tipos de prato: normal (standard), midi, super mini, batida (battue), coelho (rabbit), flash e ZZ. O Compak® Sporting admite qualquer prato normal ou especial, e a sua lista menciona também o rocket. Cada tipo voa de maneira diferente.", "O prato normal, o mais comum, é uma cúpula com cerca de 108–110 mm de diâmetro. O midi tem 90 mm: mantém bem a velocidade e parece mais distante do que está. O mini tem 60 mm: sai da máquina depressa e abranda rapidamente, por isso os atiradores tendem a dar-lhe avanço a mais. A lista do Sporting™ chama ao prato pequeno «super mini», e a regra do menu indica os tamanhos de 70 mm e de 60 mm; os nomes não são usados de forma coerente, por isso guie-se sempre pelos milímetros escritos no menu.", "A batida (battue) é um prato plano e fino de 110 mm. Voa de cutelo, quase invisível, depois vira-se para mostrar a face e cai depressa. O coelho (rabbit) é um prato de 110 mm com um rebordo grosso e resistente, lançado a rolar de lado pelo chão; ressalta e pode saltar sobre os altos do terreno. Em português diz-se simplesmente «coelho».", "Um prato flash está cheio de pó colorido que deixa uma nuvem viva quando é atingido; conta como qualquer outro prato. Um prato ZZ, também chamado hélice, é uma hélice de plástico com uma tampa branca ao centro, que voa de forma irregular. O rocket é um prato especial que só aparece na lista do Compak® Sporting; não damos especificações sobre ele.", "No Sporting™, um prato de cor, tamanho ou tipo errado é NULO (No Bird) e repete-se."], "key_points": ["Lista do Sporting™: normal, midi, super mini, batida, coelho, flash, ZZ; o Compak® admite qualquer tipo, incluindo o rocket.", "Normal cerca de 108–110 mm, midi 90 mm, mini 60 mm; o menu pode também indicar 70 mm — guie-se pelos milímetros.", "Batida: plana, de cutelo, vira e cai; coelho: rebordo grosso, rola e salta.", "O flash deixa uma nuvem de pó; o ZZ é um prato em hélice.", "Sporting™: cor, tamanho ou tipo errado = NULO."], "terms": ["standard-target", "midi", "mini", "super-mini", "battue", "rabbit", "flash-target", "zz-target", "rocket-target", "no-bird"], "sources": [{"title": "Shooting UK — Clay pigeon sizes: knowing what they are will help you improve your score", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}, {"title": "Let's Go Shooting — Types of clay targets", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/types-of-clay-targets/"}, {"title": "GUNS Magazine — Helice", "url": "https://gunsmagazine.com/discover/helice/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}], "coach_says": [{"en": "The midi looks far but it isn't — don't give it too much.", "meaning": "Um prato de 90 mm parece mais distante do que está, por isso precisa de menos avanço do que o atirador pensa.", "say": "O midi parece longe, mas não está — não lhe dê avanço a mais."}, {"en": "The battue will turn and drop at the end — take it when it shows its belly.", "meaning": "Atire à batida quando ela virar a face plana para si.", "say": "A batida vai virar e cair no fim — atire quando ela mostrar a barriga."}, {"en": "The mini is dying fast — shoot it early.", "meaning": "O prato pequeno perde velocidade depressa; não espere.", "say": "O mini está a morrer depressa — atire-lhe cedo."}, {"en": "The rabbit will hop on that bump — stay under it.", "meaning": "Mantenha as bocas dos canos baixas no prato que rola, para que, se saltar, encontre na mesma o chumbo.", "say": "O coelho vai saltar naquele alto — fique por baixo dele."}], "quiz": [{"q": "Que prato rola pelo chão?", "options": ["Midi", "Batida", "Coelho", "Flash"], "answer": 2, "why": "O coelho tem um rebordo grosso e é lançado de lado, a rolar pelo chão."}, {"q": "O menu diz «70 mm». O treinador chama-lhe mini. O que deve traduzir?", "options": ["Corrigir para 60 mm, já que um mini tem 60 mm", "Manter a palavra do treinador e os 70 mm do menu", "Chamar-lhe midi, já que tem mais de 60 mm", "Pedir ao treinador que diga «super mini»"], "answer": 1, "why": "As regras indicam os tamanhos de 70 mm e de 60 mm e o nome «super mini»; confie nos milímetros do menu e não corrija o treinador."}, {"q": "Num posto de Sporting™, uma máquina lança um midi em vez do prato normal indicado no menu. O que acontece?", "options": ["NULO, o prato repete-se", "Conta como acerto", "O atirador perde o prato", "A série é anulada"], "answer": 0, "why": "No Sporting™, um prato de cor, tamanho ou tipo errado é NULO e repete-se."}]}, {"id": "targets-colours-visibility", "minutes": 5, "title": "Cores, luz e visibilidade", "body": ["Os dois regulamentos pedem o mesmo: a cor do prato tem de se destacar claramente do fundo. Os pratos de duas cores não são recomendados. Ou seja, a cor é uma escolha de quem monta o percurso, feita para cada trajetória, e não um tipo de prato à parte.", "Vai ouvir falar de pratos pretos, laranja, brancos, amarelos e cor-de-rosa. Muitos montadores de percursos usam pratos pretos contra o céu e laranja contra as árvores e a relva. Um prato «blazed» tem a cúpula pintada de laranja vivo. Atenção: quando o treinador diz «the orange one» (o laranja), está a falar de uma cor, não de um tamanho. Um midi preto e um prato normal laranja podem sair do mesmo posto.", "Se for lançado um prato da cor errada, o árbitro declara NULO e o prato repete-se. No Compak® Sporting as regras acrescentam que o mau tempo nunca é motivo para um NULO: um prato partido conta e um prato falhado é perdido, sejam quais forem as condições. No Parcours de Chasse – Sporting™ o árbitro pode interromper o tiro durante uma tempestade ou um aguaceiro curtos e violentos.", "A luz muda tudo. Os treinadores falam de contraluz (o sol por trás do prato), de luz baça nos dias cinzentos, de sombras debaixo das árvores e do fundo atrás do prato: céu, linha de árvores ou chão. Um prato pode «desaparecer» contra árvores escuras e «saltar à vista» contra o céu. É por isso que os atiradores mudam a cor das lentes ao longo do dia.", "Quando traduzir, mantenha as palavras sobre cor e luz exatas e curtas: «está a sair das árvores escuras», «perde-o no sol». Explicam porque é que o atirador falhou, por isso são importantes."], "key_points": ["A cor do prato tem de se destacar do fundo; os pratos de duas cores não são recomendados.", "Cor não é tipo: «the orange one» é uma cor, não um tamanho.", "Cor errada = NULO.", "Compak®: o mau tempo nunca justifica um NULO; no Sporting™ o árbitro pode interromper durante uma tempestade curta.", "Contraluz, luz baça, fundo: traduza as palavras sobre a luz com exatidão."], "terms": ["target", "no-bird", "blazed-target", "background"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch20-bad-weather", "label": "20 · No NO BIRD for bad weather"}, {"book": "sporting", "id": "ch5-weather-interruption", "label": "5 · Interrupting shooting for bad weather"}], "coach_says": [{"en": "The black one is the midi, the orange one is the standard — don't mix them up.", "meaning": "Dois pratos do posto diferem na cor e no tamanho.", "say": "O preto é o midi, o laranja é o normal — não os confunda."}, {"en": "You lose it against the trees — pick it up later, in the sky.", "meaning": "O prato vê-se mal à frente das árvores; comece a olhar onde ele já tem o céu por trás.", "say": "Perde-o contra as árvores — apanhe-o mais tarde, no céu."}, {"en": "Flat light today — put the yellow lens in.", "meaning": "Luz cinzenta, sem contraste; uma lente amarela ajuda o contraste.", "say": "Hoje a luz está baça — ponha a lente amarela."}], "quiz": [{"q": "O que exigem as regras quanto à cor do prato?", "options": ["Tem de ser sempre laranja", "Tem de se destacar claramente do fundo", "Tem de ter duas cores", "Qualquer cor: as regras nada dizem"], "answer": 1, "why": "A exigência é a visibilidade contra o fundo; os pratos de duas cores não são recomendados."}, {"q": "No Compak® Sporting começa a chover com força e um atirador falha. Pode pedir um NULO por causa do tempo?", "options": ["Sim, o tempo justifica-o sempre", "Só no primeiro prato de um double", "Só se o júri concordar", "Não, o tempo nunca justifica um NULO"], "answer": 3, "why": "As regras do Compak® Sporting dizem que o tempo nunca é motivo para um NULO."}, {"q": "O treinador diz «Watch the orange one.» O que está a descrever?", "options": ["A cor de um prato", "Um prato de 90 mm", "Um coelho", "Um prato partido"], "answer": 0, "why": "A cor é escolhida pela visibilidade e nada diz sobre o tamanho ou o tipo."}]}, {"id": "targets-traps", "minutes": 5, "title": "Máquinas, lançamento e o operador", "body": ["Uma máquina (trap) é o aparelho que lança os pratos. As máquinas podem ser manuais ou automáticas (as regras do Compak® Sporting mencionam também as semi-automáticas). No Parcours de Chasse – Sporting™ as máquinas de um posto têm as letras A, B, C, D, da esquerda para a direita, vistas do posto; no Compak® Sporting as seis máquinas vão de A a F, cada uma com um painel com a letra. Mantenha as letras latinas quando traduzir: o menu usa-as.", "O atirador pede o prato com uma voz de comando: as regras indicam «pull» ou «ready», embora na prática as palavras usadas pelos atiradores variem. No Sporting™ o árbitro transmite a ordem ao operador da máquina (trapper, em português também «pulleur», a pessoa que aciona o lançamento) com um sinal sonoro, e o prato tem de sair no prazo de três segundos. Não traduza a voz de comando em si: é uma ordem para a máquina, não uma frase.", "No Compak® Sporting os pratos podem ser lançados à mão, por telecomando ou por um phono-pull (sonopull) ativado pela voz. Com lançamento manual, o prato sai 0 a 3 segundos depois do pedido; o phono-pull tem um atraso fixo de 0,5 segundos. O Compak® Sporting internacional em linha usa apenas phono-pull com arbitragem eletrónica.", "O lançamento por voz tem um microfone no posto. A sua própria voz pode acioná-lo. Num posto assim, nunca fale em voz alta enquanto o atirador está pronto: sussurre entre pratos ou afaste-se.", "Os erros da máquina são NULOS: um prato lançado mais de três segundos depois do pedido, um prato da máquina errada, um prato lançado sem pedido, dois pratos de máquinas do mesmo posto no Sporting™, ou um prato lançado por engano por uma máquina do mesmo campo de Compak."], "key_points": ["Máquinas: A–D por posto de Sporting™, A–F num campo de Compak®; mantenha as letras latinas.", "A voz de comando («pull», «ready») lança o prato; não a traduza.", "Sporting™: o árbitro dá o sinal ao operador; o prato sai em 3 segundos.", "Compak®: manual 0–3 s, telecomando ou phono-pull com atraso fixo de 0,5 s.", "Pratos atrasados, da máquina errada ou sem pedido são NULOS; um microfone pode ouvi-lo."], "terms": ["trap", "trapper", "call", "sonopull", "manual-release", "tower", "no-bird"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch16-terms", "label": "16 · Other basic terms"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Trap B is throwing lower than in the showing — tell the referee.", "meaning": "A trajetória da máquina mudou; o atirador deve comunicá-lo antes de atirar.", "say": "A máquina B está a lançar mais baixo do que na mostra — diga ao árbitro."}, {"en": "It's voice release here — don't chat on the stand.", "meaning": "Um microfone lança os pratos; falar pode fazer sair um.", "say": "Aqui o lançamento é por voz — nada de conversa no posto."}, {"en": "The trapper was late on that one — that's a no bird.", "meaning": "O prato saiu mais de três segundos depois do pedido.", "say": "O operador atrasou-se nesse — é nulo."}], "quiz": [{"q": "No Sporting™, quanto tempo pode o prato demorar a sair depois do sinal do árbitro?", "options": ["Até 1 segundo", "Até 3 segundos", "Até 10 segundos", "Qualquer tempo"], "answer": 1, "why": "Um prato lançado mais de três segundos depois é NULO."}, {"q": "Qual é o atraso fixo de um phono-pull de Compak®?", "options": ["0 segundos", "3 segundos", "0,5 segundos", "É definido por cada atirador"], "answer": 2, "why": "O phono-pull tem de aplicar um atraso fixo e inalterável de 0,5 segundos."}, {"q": "Está num posto com lançamento por voz e o atirador está pronto. O que faz?", "options": ["Traduz em voz alta para que ele o ouça", "Pede ao operador que espere um momento", "Repete por ele a voz de comando", "Fica em silêncio; só sussurra entre pratos"], "answer": 3, "why": "A sua voz pode acionar o microfone e lançar um prato que ninguém pediu."}]}, {"id": "targets-menu", "minutes": 5, "title": "Ler o menu de tiro", "body": ["O menu de tiro (menu) é o painel no posto que diz ao atirador o que aí vem. Os atiradores dizem mesmo «menu», por isso mantenha a palavra.", "No Parcours de Chasse – Sporting™ o menu indica as máquinas pela ordem de tiro e tem de assinalar os pratos especiais: 90 mm, 70 mm, 60 mm, batida ou coelho. Os árbitros verificam antecipadamente se as máquinas correspondem ao menu. Um percurso dá 15 simples e 5 doubles, e os doubles só podem usar pratos já apresentados como simples no mesmo posto. A esquadra atira primeiro os simples e depois os doubles.", "Cada double é indicado com o seu tipo: ao tiro (on report: o segundo prato sai ao som do primeiro tiro), simultâneo (os dois ao mesmo tempo) ou rafale (dois da mesma máquina, um a seguir ao outro; só no Sporting™). Os menus têm aspeto diferente de campo para campo, por isso leia as palavras, não apenas as letras. Exemplo para um posto com três máquinas: simples A, B, C; doubles A + B simultâneo e C + C rafale (num posto assim não são permitidos dois doubles ao tiro).", "No Compak® Sporting há um menu em cada um dos cinco postos. Cada posto tem cinco pratos: cinco simples, três simples e um double, ou um simples e dois doubles. O tipo de double é o mesmo nos cinco postos de um campo de Compak, e o primeiro prato de cada double é o último prato do posto anterior. A FITASC disponibiliza 40 menus prontos para competições.", "Antes de o seu atirador entrar no posto, leia-lhe o menu em voz alta na língua dele, letra a letra: «A, depois F, depois o double C e E ao tiro.»"], "key_points": ["Mantenha a palavra «menu».", "Menu de Sporting™: máquinas por ordem, mais os pratos especiais (90, 70, 60 mm, batida, coelho).", "15 simples + 5 doubles; os doubles usam pratos já mostrados como simples; primeiro os simples.", "Doubles: ao tiro, simultâneo, rafale (só no Sporting™).", "Compak®: cinco pratos por posto, o mesmo tipo de double em todos os postos, cada double começa com o último prato do posto anterior."], "terms": ["target-menu", "single-target", "double", "double-on-report", "simultaneous-double", "rafale-double"], "sources": [{"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch2-doubles-three-traps", "label": "2 · Doubles at a position with 3 machines"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-annex3-tables", "label": "17 · The 40 pre-established trajectory setting tables"}], "coach_says": [{"en": "Read the menu: on station three you have A, then F, then the pair C and E on report.", "meaning": "A ordem dos pratos no posto 3, terminando com um double ao tiro.", "say": "Leia o menu: no posto três tem A, depois F, depois o double C e E ao tiro."}, {"en": "Same traps, new menu — don't shoot from memory.", "meaning": "A ordem mudou desde a última série.", "say": "Mesmas máquinas, menu novo — não atire de memória."}, {"en": "Three singles, then a simo pair.", "meaning": "«Simo» é a abreviatura de double simultâneo.", "say": "Três simples e depois um simultâneo."}], "quiz": [{"q": "Que pratos especiais tem de indicar um menu de Sporting™?", "options": ["Só as cores dos pratos", "90 mm, 70 mm, 60 mm, batida ou coelho", "Só coelhos e batidas", "Nenhum; o árbitro anuncia-os"], "answer": 1, "why": "O menu tem de indicar as máquinas por ordem e os tipos de prato especiais."}, {"q": "No Compak® Sporting, com que prato começa cada double?", "options": ["Sempre com a máquina A", "Com um prato nunca visto antes", "Com o último prato atirado no posto anterior", "Com qualquer prato à escolha do atirador"], "answer": 2, "why": "Os doubles encadeiam-se entre postos: cada um começa com o último prato do posto anterior."}, {"q": "Que tipo de double só existe no Sporting™?", "options": ["Rafale", "Ao tiro", "Simultâneo", "Nenhum"], "answer": 0, "why": "Os doubles do Compak® são ao tiro ou simultâneos; o rafale é um double do Sporting™."}]}, {"id": "targets-hit-or-lost", "minutes": 5, "title": "Acerto ou falha: o pedaço visível e a armadilha do «fumo»", "body": ["Um prato conta como «one» (acerto, BOM) quando foi lançado corretamente, o atirador disparou de acordo com as regras e se soltou pelo menos um pedaço visível, ou o prato foi destruído total ou parcialmente. Os pratos flash seguem a mesma regra. Um prato é «zero» (falha, ZERO) quando não se solta nenhum pedaço visível e há apenas pó ou fumo.", "Assim, a regra depende de uma única imagem: um pedaço visível. Uma pequena lasca que salta conta como acerto. Uma nuvem de pó com o prato a continuar a voar inteiro é falha. Na folha de marcação, o acerto marca-se normalmente com X e a falha com O.", "Só o árbitro decide. Os membros da esquadra não podem dar opiniões, e ninguém pode apanhar um prato para o verificar. No Compak® Sporting o árbitro anuncia cada zero em voz alta ou com um sinal sonoro. No Parcours de Chasse – Sporting™ o atirador tem de partir os pratos onde o árbitro os possa ver. Ao pedir o prato seguinte, o atirador aceita a decisão sobre o anterior, por isso qualquer objeção tem de ser feita de imediato.", "Agora, a armadilha para os intérpretes. Os treinadores elogiam um acerto perfeito com «smoked it», «inked it» ou «powdered it»: o prato transformou-se numa nuvem negra. É o melhor acerto possível, não um zero. Mas nas regras, «only dust or smoke» (apenas pó ou fumo) significa falha. «Dusted it» é arriscado: normalmente quer dizer que só saiu pó, ou seja, prato perdido, mas há quem o use como elogio. Se não tiver a certeza, pergunte, porque os dois sentidos são opostos.", "E ainda: «dead» significa acerto (BOM, não «morto») e «lost» significa falha (ZERO, não «perdido» no sentido de extraviado)."], "key_points": ["BOM (one) = soltou-se pelo menos um pedaço visível, ou o prato foi destruído total ou parcialmente.", "ZERO = nenhum pedaço visível, apenas pó ou fumo.", "Só o árbitro decide; não se apanham pratos; pedir o prato seguinte é aceitar a decisão.", "Gíria de treinador «smoked it» = acerto perfeito; texto da regra «only smoke» = falha.", "«Dead» = acerto, «lost» = falha; pergunte se «dusted» não for claro."], "terms": ["one", "zero", "visible-piece", "referee", "score-sheet", "smoked-it", "chip"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "Smoked it! That's the picture.", "meaning": "Um acerto perfeito: o prato desfez-se em pó; o atirador deve memorizar essa imagem.", "say": "Pulverizou-o! É essa a imagem."}, {"en": "Dead — only a chip, but it counts.", "meaning": "Soltou-se um pequeno pedaço visível, por isso é acerto.", "say": "Bom — só uma lasca, mas conta."}, {"en": "Lost — you were just behind it.", "meaning": "Uma falha; o chumbo passou atrás do prato.", "say": "Zero — ficou mesmo atrás dele."}, {"en": "Don't argue with me later — say it now, before you call.", "meaning": "Uma objeção tem de ser feita de imediato; pedir o prato seguinte é aceitar a decisão.", "say": "Não venha discutir comigo depois — diga agora, antes de pedir o prato."}], "quiz": [{"q": "O prato continua a voar inteiro, mas aparece uma nuvem de pó. Qual é a pontuação?", "options": ["Zero (falha)", "Um (acerto)", "NULO", "Meio ponto"], "answer": 0, "why": "Apenas pó ou fumo, sem pedaço visível, é falha."}, {"q": "O treinador grita «Smoked it!» Como traduz o sentido?", "options": ["Só fez fumo, por isso o prato é perdido", "Os canos estão a sobreaquecer", "Um acerto perfeito: o prato desfez-se em pó", "A máquina está a arder"], "answer": 2, "why": "Na gíria dos treinadores, «smoked it» é um elogio a um prato totalmente desfeito; o texto da regra «only smoke» significa o contrário."}, {"q": "Um membro da esquadra diz que o último prato foi atingido. Quem decide?", "options": ["Uma votação da esquadra", "O treinador", "O intérprete", "Só o árbitro"], "answer": 3, "why": "As decisões sobre os pratos cabem ao árbitro; os membros da esquadra não podem intervir."}]}]}, {"id": "flight", "icon": "trajectory", "title": "Como voam os pratos (mostras)", "intro": "Os treinadores dão nome a cada prato pela forma como voa: crosser, incomer, teal, looper, rabbit, report pair. Em seis lições curtas vai aprender o que significa cada nome, o que o atirador tem de fazer com cada prato e que palavras é fácil traduzir mal.", "lessons": [{"id": "flight-crosser", "minutes": 5, "title": "O transversal: um prato que passa de lado", "body": ["Um transversal (crosser) passa à frente do atirador, mais ou menos em ângulo reto com a linha de visão: da esquerda para a direita (escrito E→D, em inglês L→R) ou da direita para a esquerda (D→E, R→L). Num percurso de Parcours de Chasse – Sporting™ as regras pedem uma mistura de pratos transversais, em diagonal, de entrada e de saída. No Compak® Sporting, um transversal da esquerda para a direita e um da direita para a esquerda são duas das três trajetórias obrigatórias, por isso todos os campos de Compak os têm.", "Um transversal mostra toda a sua velocidade lateral, por isso precisa do maior avanço (a distância que se dá à frente do prato) de todas as mostras, e quanto mais longe estiver, mais avanço precisa. Um «long crosser» é um transversal distante, não um que voa durante muito tempo.", "Leia a linha e a velocidade: voa plano, sobe ou já está a descer no ponto de tiro? Mostra a face (a cúpula ou a barriga) ou só o cutelo? Está a abrandar? Um transversal a abrandar precisa de menos avanço do que um a toda a velocidade.", "Plano típico: pés virados para o ponto de tiro, olhos a apanhar o prato cedo, depois pull-away ou avanço mantido, com a arma ainda em movimento no momento do disparo. Um veredicto muito comum do treinador sobre um transversal é «behind» (atrás): avanço insuficiente, ou uma arma que parou.", "As direções dão-se do ponto de vista do atirador. Se estiver de frente para o atirador, o «da esquerda para a direita» dele é o seu da direita para a esquerda, por isso nunca troque as palavras."], "key_points": ["Um transversal passa a cerca de 90° da linha de visão: E→D ou D→E.", "É o que precisa de mais avanço; mais distância significa mais avanço.", "«Long crosser» = transversal distante, não demorado.", "O Compak® Sporting tem sempre um transversal E→D e um D→E.", "A esquerda e a direita são sempre do ponto de vista do atirador."], "terms": ["crosser", "lead", "trajectory", "target-line", "break-point", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["crosser-rl"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}], "coach_says": [{"en": "Long crosser, right to left — trust the lead and keep the gun moving.", "meaning": "O prato está longe e voa da direita para a esquerda do atirador; dê-lhe o avanço planeado e não pare o movimento.", "say": "Transversal comprido, da direita para a esquerda — confie no avanço e não pare a arma."}, {"en": "You're behind it — give it more.", "meaning": "O chumbo passou atrás do prato: é preciso mais avanço.", "say": "Está atrás dele — dê-lhe mais."}, {"en": "It's dropping at your break point — stay under the line.", "meaning": "No sítio onde o atirador o parte, o transversal já está a cair, por isso a arma tem de passar ligeiramente abaixo da trajetória.", "say": "No seu ponto de tiro ele já está a cair — fique por baixo da linha."}, {"en": "Pick it up early, it's quick off the trap.", "meaning": "Procure o prato mais perto da máquina do que é habitual, porque sai da máquina depressa.", "say": "Apanhe-o cedo, ele sai rápido da máquina."}], "quiz": [{"q": "Que mostra precisa normalmente de mais avanço?", "options": ["Um prato que se afasta em linha reta", "Um prato de entrada que vem direito ao atirador", "Um transversal à mesma distância", "Um coelho a rolar em linha reta para longe"], "answer": 2, "why": "Um transversal mostra toda a sua velocidade lateral, por isso a arma tem de ir mais à frente; os pratos em linha reta precisam de pouco avanço lateral."}, {"q": "O treinador diz «long crosser». O que significa «long»?", "options": ["O prato está longe", "O prato voa durante muito tempo", "O prato é comprido e oval", "O atirador deve esperar muito tempo"], "answer": 0, "why": "Na linguagem dos treinadores, «long» descreve a distância. Um long crosser é um transversal distante, que precisa de mais avanço."}, {"q": "O que é verdade sobre os transversais no Compak® Sporting?", "options": ["Os transversais não são permitidos no Compak", "Só são permitidos transversais da direita para a esquerda", "Os transversais só podem ser lançados como coelhos", "Um transversal E→D e um D→E são obrigatórios"], "answer": 3, "why": "As regras do Compak® Sporting tornam obrigatórias três trajetórias: um transversal E→D, um transversal D→E e um prato de saída."}]}, {"id": "flight-incomer-going-away", "minutes": 5, "title": "De entrada, de saída, de batida e por cima", "body": ["Um prato de entrada (incomer) vem na direção do atirador, muitas vezes de uma máquina distante ou de uma torre, e normalmente vai descendo à medida que se aproxima. Pode parecer abrandar e ficar suspenso, o que tenta o atirador a fazer pontaria. Normalmente atira-se-lhe à frente, antes de chegar por cima, e os canos podem tapar o prato («blot out») no momento do disparo. Isso é intencional, não é um erro.", "Um prato de saída (going-away) parte de perto ou de trás do atirador e afasta-se. Precisa de pouco avanço lateral, mas fica pequeno depressa e muitas vezes sobe ou desce, por isso o avanço é sobretudo vertical e o tempo conta: não espere. No Compak® Sporting é obrigatório um prato de saída sobre o lado BC; pode vir de uma fossa à frente ou de uma torre atrás dos postos, pelo menos 4 m acima deles.", "Um prato de batida (driven) é um prato de entrada que passa por cima da cabeça do atirador, como um faisão empurrado pelos batedores. Apanhe-o cedo, acompanhe-o, suba por trás atravessando-o, dispare quando os canos o taparem e continue o movimento. Atenção: o francês «en battue» (italiano «in battuta») e o português «de batida» designam a caça de batida, e não o prato batida (battue).", "Um prato por cima vindo de trás (overhead from behind) passa por cima das costas do atirador e afasta-se. Vê-se tarde, por isso o atirador olha cedo para trás à procura dele, monta a arma com ele, dispara quando a boca do cano toca a frente do prato e acompanha.", "«Incoming» (de entrada) e «going away» (de saída) descrevem sempre o prato em relação ao atirador."], "key_points": ["De entrada: vem na direção do atirador, normalmente a descer; atire-lhe à frente.", "De saída: pouco avanço lateral, sobretudo vertical; atire sem demora.", "De batida: um prato de entrada que passa por cima da cabeça; atravesse-o vindo de trás e tape-o.", "Por cima vindo de trás: olhe cedo para trás, monte a arma com ele, acompanhe.", "O Compak® Sporting inclui sempre um prato de saída."], "terms": ["incomer", "going-away", "driven-target", "overhead", "tower", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "ShotKam — Master incomers", "url": "https://shotkam.com/blogs/blog-collections/master-incomers"}, {"title": "Sporting Gun — How to shoot going-away targets", "url": "https://sporting-gun.com/shooting/how-to-shoot-going-away-targets/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "flight", "preset": "incomer", "also": ["going-away", "overhead"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}], "coach_says": [{"en": "Take it out in front, before it gets on top of you.", "meaning": "Parta o prato de entrada enquanto ainda está à frente, não quando já está por cima.", "say": "Atire-lhe à frente, antes que ele lhe chegue por cima."}, {"en": "Blot it out and keep swinging.", "meaning": "Deixe os canos taparem o prato no momento do disparo e não pare a arma.", "say": "Tape-o e continue o movimento."}, {"en": "Don't wait on the going-away — it's getting smaller.", "meaning": "Atire ao prato de saída sem demora, porque se está a afastar rapidamente.", "say": "Não espere no de saída — está a ficar pequeno."}, {"en": "It comes from behind you — look back for it early.", "meaning": "É um prato por cima vindo de trás; vire os olhos para ele antes de pedir.", "say": "Vem de trás de si — olhe cedo para trás à procura dele."}], "quiz": [{"q": "O treinador diz: «Blot it out.» O que deve fazer o atirador?", "options": ["Limpar as lentes dos óculos de proteção", "Deixar os canos taparem o prato no momento do disparo", "Esperar até o prato desaparecer de vista", "Atirar só aos pedaços que caem"], "answer": 1, "why": "Nos pratos de entrada, de batida e ascendentes, a arma tapa muitas vezes o prato no momento do disparo; o treinador pede exatamente isso."}, {"q": "Porque não se deve deixar um prato de saída durante muito tempo?", "options": ["Afasta-se e fica pequeno rapidamente", "As regras só permitem três segundos", "Transforma-se sempre num transversal", "O árbitro declara NULO depois do ponto mais alto"], "answer": 0, "why": "Um prato de saída ganha distância depressa, por isso quanto mais esperar, mais difícil fica. Os três segundos são o tempo de lançamento, não um limite para atirar."}, {"q": "O que distingue um prato de batida de um prato de entrada comum?", "options": ["É sempre um coelho", "Vem de trás do atirador", "Passa por cima da cabeça do atirador", "Só é lançado no Compak® Sporting"], "answer": 2, "why": "De batida (driven) é um prato de entrada que passa por cima da cabeça, como a caça de batida. Um prato que vem de trás é um prato por cima vindo de trás."}]}, {"id": "flight-quartering", "minutes": 5, "title": "Pratos em diagonal: de saída e de entrada", "body": ["Um prato em diagonal (quartering) voa em ângulo: em parte transversal, em parte de saída ou de entrada. O prato de saída em diagonal (quartering away) afasta-se do atirador em ângulo, por exemplo para a frente e para a direita. O prato de entrada em diagonal (quartering towards, também «quartering in») vem na direção do atirador em ângulo e passa para um dos lados ou cai à frente. O ângulo anda muitas vezes pelos 45°, mas é possível qualquer coisa entre um prato reto e um transversal puro.", "O avanço depende do ângulo: mais do que para um prato de saída em linha reta, menos do que para um transversal puro. Um ângulo fechado precisa de pouco avanço; um quase transversal, de quase tanto como um transversal.", "O prato de saída em diagonal fica pequeno e lento depressa, por isso atire-lhe sem demora. O pull-away é adequado, porque a arma se mantém na linha do prato. O prato de entrada em diagonal fica maior e parece lento, o que tenta o atirador a esperar; pode então passar demasiado perto ou desaparecer de vista ao cair.", "A mesma máquina dá mostras diferentes a partir de postos diferentes: de um posto o prato é transversal, do seguinte é em diagonal. É por isso que os pratos têm de ser lidos a partir do posto exato que o atirador vai usar.", "Em português diga «de saída em diagonal» e «de entrada em diagonal» (ou «saída oblíqua / entrada oblíqua»). Uma palavra decalcada de «quarter» («quarto») não diz nada a um atirador."], "key_points": ["Em diagonal = voa em ângulo, entre o prato reto e o transversal.", "De saída em diagonal afasta-se em ângulo; de entrada em diagonal aproxima-se em ângulo.", "O avanço cresce com o ângulo: menos do que num transversal, mais do que num prato reto.", "A mesma máquina parece diferente de cada posto: leia-a a partir do seu posto.", "Em português: «de saída em diagonal / de entrada em diagonal»."], "terms": ["quartering-away", "quartering-towards", "crosser", "going-away", "lead", "pull-away"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "flight", "preset": "quartering-away", "also": ["quartering-towards"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "The first one's quartering away to the left — take it quickly before it gets small.", "meaning": "O primeiro prato afasta-se em ângulo para a esquerda do atirador; parta-o cedo.", "say": "O primeiro sai em diagonal para a esquerda — atire depressa, antes que fique pequeno."}, {"en": "Quartering in from the right — don't let it get too close.", "meaning": "O prato vem na direção do atirador em ângulo, pela direita; não espere por ele.", "say": "Entra em diagonal pela direita — não o deixe chegar demasiado perto."}, {"en": "Less lead than you think — it's only a slight angle.", "meaning": "O prato é quase reto, por isso só precisa de um pequeno avanço.", "say": "Menos avanço do que pensa — o ângulo é pequeno."}], "quiz": [{"q": "Um prato vem na direção do atirador em ângulo e passa para o lado. Como se chama?", "options": ["De saída", "De entrada em diagonal", "Teal", "Rafale"], "answer": 1, "why": "De entrada em diagonal (quartering towards ou quartering in) é um prato em ângulo que se aproxima; de saída em diagonal (quartering away) é o prato em ângulo que se afasta."}, {"q": "Como se compara o avanço num prato em diagonal com o de um transversal puro à mesma distância e velocidade?", "options": ["É igual ao do transversal", "É sempre zero", "É maior do que o do transversal", "É menor, consoante o ângulo"], "answer": 3, "why": "Só a parte lateral do movimento exige avanço lateral, por isso quanto mais fechado o ângulo, menor o avanço."}, {"q": "Porque se deve ler um prato a partir do posto exato de onde vai atirar?", "options": ["A mesma máquina pode dar um transversal de um posto e um prato em diagonal de outro", "As regras proíbem ver a partir de outro sítio", "Os pratos mudam de cor de um posto para outro", "Só o árbitro pode estar noutro sítio"], "answer": 0, "why": "O ângulo entre o atirador e a linha do prato muda com a posição, por isso a mostra também muda."}]}, {"id": "flight-teal-chandelle-looper", "minutes": 6, "title": "Teal, chandelle, looper e pratos descendentes", "body": ["Estas mostras têm mais a ver com a altura e a curva do que com o ângulo. Os seus nomes são palavras de quem monta os percursos, não termos dos regulamentos: as regras enumeram tipos de prato, e as regras do Compak® Sporting pedem trajetórias variadas, como ascendentes, descendentes e em balão.", "Um teal (springing ou rising teal, do nome de um pequeno pato; em português prato vertical ou ascendente vertical) é lançado quase na vertical, abranda, fica parado no topo e volta a cair. Atira-se-lhe na subida, subindo com a arma por baixo e atravessando-o, ou no ponto mais alto, enquanto está parado. Ir «espetar» o prato no topo, parando para fazer pontaria, é o erro clássico. Alguns montadores usam «springing» para um prato que sobe em ângulo e não na vertical, como uma ave a levantar.", "Uma chandelle (em francês, «vela») sobe a pique numa ligeira curva, faz um arco e cai quase na vertical. É mais fácil na subida; na curva, o avanço vai para o lado e para baixo.", "Um looper descreve um grande arco no céu, como um arco-íris, muitas vezes uma batida lançada de uma máquina inclinada: sobe, vira a face e cai. A arma segue a curva, à frente e por baixo.", "Um prato descendente (dropping) é qualquer prato na parte descendente do seu voo. O avanço é em parte vertical: por baixo e à frente, com a arma em movimento.", "Atenção: os nomes variam de país para país. Muitos francófonos usam «chandelle» para um prato que sobe quase na vertical, a que um treinador inglês chama teal, e os atiradores portugueses também usam «chandelle», muitas vezes para o prato em arco (looper). Sempre que ouvir chandelle, candle ou «vela», pergunte: sobe a direito ou faz um arco?"], "key_points": ["Teal: sobe quase na vertical, para, cai; atire-lhe na subida ou no ponto mais alto.", "Chandelle: subida a pique em curva, faz um arco, cai quase na vertical.", "Looper: grande arco tipo arco-íris, muitas vezes uma batida que vira e cai.", "Descendente: avanço por baixo e à frente, nunca pare a arma.", "Os nomes variam: os francófonos dizem muitas vezes «chandelle» para um teal; em português «chandelle» também é ambíguo, por isso esclareça."], "terms": ["teal", "springing-target", "chandelle", "looper", "dropping-target", "battue"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "Shotgun Life — How to shoot a chandelle target", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}, {"title": "ShotgunWorld — Target terminology (forum)", "url": "https://www.shotgunworld.com/threads/target-terminology.477902/"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}], "sim": {"type": "flight", "preset": "teal", "also": ["chandelle", "looper", "dropping"]}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}], "coach_says": [{"en": "Take the teal on the way up — keep the barrels moving above it.", "meaning": "Parta o teal a subir, antes do ponto mais alto; a arma continua a subir para lá dele.", "say": "Atire ao teal na subida — mantenha os canos a mexer por cima dele."}, {"en": "Don't poke at it on the top.", "meaning": "Não pare para fazer pontaria ao prato enquanto ele está parado no topo.", "say": "Não o vá espetar lá em cima."}, {"en": "The looper's turning over — underneath and in front.", "meaning": "O prato está a passar o topo do arco e a começar a cair; o avanço vai para baixo e para a frente dele.", "say": "O looper está a virar — por baixo e à frente."}, {"en": "Second bird's dropping — go under it and keep the gun moving.", "meaning": "O segundo prato do double está a cair; atire por baixo dele com a arma em movimento.", "say": "O segundo está a descer — vá por baixo e não pare a arma."}], "quiz": [{"q": "Que prato é lançado quase na vertical, fica parado no topo e volta a cair?", "options": ["Looper", "De saída em diagonal", "Coelho", "Teal"], "answer": 3, "why": "É o teal (springing ou rising teal). O looper descreve um grande arco no céu."}, {"q": "Para onde vai normalmente o avanço num prato descendente?", "options": ["Para cima e para trás", "Por baixo e à frente", "Diretamente ao prato", "Só para o lado, nunca para baixo"], "answer": 1, "why": "Um prato a cair desloca-se para baixo e também para a frente, por isso parte do avanço é vertical: por baixo e à frente."}, {"q": "Um treinador francófono diz «chandelle». Qual é a atitude mais segura?", "options": ["Confirmar: sobe a direito ou faz um arco por cima?", "Traduzir sempre como o looper inglês", "Traduzir sempre como o teal inglês", "Ignorar, porque não é um termo do regulamento"], "answer": 0, "why": "Os francófonos referem-se muitas vezes a um prato quase vertical (um teal inglês), enquanto a chandelle de um montador inglês sobe em curva e faz um arco; uma pergunta rápida evita um plano errado."}]}, {"id": "flight-rabbit", "minutes": 5, "title": "O coelho: rola, salta e dispara", "body": ["Um coelho (rabbit) é um prato de 110 mm com um rebordo grosso e resistente, lançado de lado para rolar pelo chão como uma lebre a correr. É um prato especial, por isso no Parcours de Chasse – Sporting™ tem de constar do menu de tiro do posto.", "Os treinadores descrevem como ele corre: um coelho que rola (rolling) corre de forma regular; um coelho que salta (hopping, bouncing) pula nos altos e nas pedras; um coelho que dispara (bolting) sai de repente do mato e corre depressa. Os coelhos podem ir de lado, na direção do atirador ou afastar-se dele.", "O coelho é pesado e abranda depressa, por isso os atiradores dão-lhe muitas vezes avanço a mais. Os treinadores pedem para manter a boca do cano baixa e atirar ao rebordo inferior da frente, para que um salto súbito encontre na mesma o chumbo. Muitas vezes só se vê numa curta abertura entre arbustos, por isso o ponto de tiro tem de ser planeado com exatidão.", "Regras: todos os pratos, coelhos incluídos, se atiram com a arma no ombro; disparar à anca não é permitido em nenhuma das disciplinas. Um caso especial: se o primeiro tiro falhar e o coelho depois se partir sozinho, por exemplo numa pedra, antes do segundo tiro, é NULO. Na repetição só conta um prato partido com o segundo tiro.", "«Fur and feather» (pelo e pena) é gíria do English Sporting para um double de um coelho («fur») e um prato aéreo («feather»). Em português diz-se simplesmente «coelho»."], "key_points": ["Coelho: 110 mm, rebordo grosso, rola de lado pelo chão.", "Rola, salta, dispara (rolling, hopping/bouncing, bolting): descrevem como corre.", "Abranda depressa: não lhe dê avanço a mais; mantenha a boca do cano baixa.", "Atira-se sempre com a arma no ombro; um coelho que se parte sozinho depois de um primeiro tiro falhado é NULO.", "«Fur and feather» = double de coelho + prato aéreo."], "terms": ["rabbit", "bolting-rabbit", "fur-and-feather", "target-menu", "no-bird", "break-point"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Gun Tests — Rabbit target clay shooting", "url": "https://www.gun-tests.com/recreational/rabbit-target-clay-shooting/"}, {"title": "Shooting UK — Clay pigeon sizes", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}], "sim": {"type": "flight", "preset": "rabbit"}, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch6-nobird-target-single-rabbit", "label": "6 · Target No Bird on a single and on a rabbit"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}], "coach_says": [{"en": "It hops on that bump — stay under it and keep moving.", "meaning": "O coelho salta num sítio conhecido; mantenha a arma baixa e em movimento.", "say": "Ele salta naquele alto — fique por baixo e não pare."}, {"en": "Shoot its feet.", "meaning": "Ponha o chumbo no rebordo inferior do coelho, não por cima dele.", "say": "Atire-lhe aos pés."}, {"en": "It slows down a lot — less lead than you think.", "meaning": "O coelho perde velocidade depressa, por isso precisa de menos avanço.", "say": "Ele abranda muito — menos avanço do que pensa."}, {"en": "Fur and feather: rabbit first, before it reaches the bushes.", "meaning": "No double de coelho e prato aéreo, atire primeiro ao coelho, porque ele desaparece no mato.", "say": "Pelo e pena: primeiro o coelho, antes de ele chegar aos arbustos."}], "quiz": [{"q": "O primeiro tiro falha um coelho, que depois se parte numa pedra antes do segundo tiro. O que acontece?", "options": ["Conta como acerto, porque se partiu", "Conta zero pela primeira falha", "NULO: repete-se e só conta um prato partido com o segundo tiro", "O atirador passa simplesmente ao prato seguinte"], "answer": 2, "why": "Os dois regulamentos tratam isto como NULO; na repetição o atirador tem de falhar deliberadamente com o primeiro tiro."}, {"q": "Porque avisam os treinadores contra o avanço excessivo num coelho?", "options": ["As regras limitam o avanço", "É pesado e abranda depressa", "Voa sempre para cima", "É mais pequeno do que um mini"], "answer": 1, "why": "O coelho tem um rebordo grosso e rola pelo chão, perdendo velocidade depressa, por isso o avanço habitual de um transversal põe o chumbo à frente."}, {"q": "O que significa «fur and feather»?", "options": ["Um double de um coelho e um prato aéreo", "Um código de vestuário de caça", "Um prato com penas coladas", "Um double de dois coelhos"], "answer": 0, "why": "Na gíria do English Sporting, «fur» é o coelho e «feather» é o prato que voa."}]}, {"id": "flight-pairs", "minutes": 6, "title": "Simples e doubles: ao tiro, rafale, simultâneo", "body": ["Um prato simples (single) é um prato de uma máquina. Nas duas disciplinas podem disparar-se dois tiros a ele, por isso uma falha pode ser salva com o segundo cano. Um double (pair) são dois pratos atirados como uma só unidade, depois de um único pedido.", "Double ao tiro (report pair, double on report): o pedido lança o primeiro prato, e o tiro a esse prato lança o segundo. No Parcours de Chasse – Sporting™ o segundo sai 0 a 3 segundos depois desse tiro. A ordem é fixa. «Report» significa o som do tiro, não um relatório escrito.", "Double sucessivo (following pair), a que a FITASC chama rafale: dois pratos da mesma máquina na mesma linha, o segundo tão depressa quanto a máquina recarrega; qualquer um pode ser atirado primeiro. Só existe no Sporting™: um double de Compak® Sporting é ao tiro ou simultâneo.", "Double simultâneo («simo»; no English Sporting «true pair»): os dois pratos saem no mesmo instante, de uma ou de duas máquinas (no Compak® Sporting sempre de duas máquinas diferentes), e podem ser atirados por qualquer ordem.", "Cartuchos: no Sporting™ há dois para o double e podem ser ambos disparados ao mesmo prato; se um só tiro partir os dois, contam os dois. No Compak® Sporting só é permitido um cartucho por prato, e dois tiros a um mesmo prato dão zero-zero; um só tiro que parta os dois pratos também não conta simplesmente como dois (a missão de Compak® explica-o).", "Num posto de Sporting™ a esquadra atira primeiro os simples e depois os doubles. Os doubles simultâneos e rafale são mostrados antes do tiro; os doubles ao tiro não."], "key_points": ["Simples: um prato, dois tiros permitidos.", "Double ao tiro: o tiro ao primeiro lança o segundo; ordem fixa.", "Rafale (double sucessivo): mesma máquina, mesma linha, só no Sporting™.", "Simultâneo (true pair): os dois ao mesmo tempo, por qualquer ordem.", "Sporting™: ambos os cartuchos podem ir para um só prato; Compak® Sporting: um por prato."], "terms": ["single-target", "double", "double-on-report", "rafale-double", "simultaneous-double", "true-pair", "target-presentation"], "sources": [{"title": "CPSA — English Sporting (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["teal"], "pairs": ["report", "simultaneous", "rafale"]}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}], "coach_says": [{"en": "It's on report — finish the first one properly, the second waits for your shot.", "meaning": "O segundo prato só sai quando o atirador dispara ao primeiro, por isso não há pressa com o primeiro.", "say": "É ao tiro — acabe bem o primeiro, o segundo espera pelo seu tiro."}, {"en": "Simo: take the rabbit first, the teal will wait for you.", "meaning": "No double simultâneo, atire primeiro ao coelho, porque o teal fica mais tempo no ar.", "say": "Simultâneo: primeiro o coelho, o teal espera por si."}, {"en": "Rafale — after the first, come straight back to the trap for the second.", "meaning": "Os dois pratos vêm da mesma máquina; depois do primeiro tiro, volte com os olhos e a arma para a máquina para apanhar o segundo.", "say": "Rafale — depois do primeiro, volte logo à máquina para o segundo."}, {"en": "True pair from the tower, five of them.", "meaning": "Cinco doubles simultâneos lançados da torre (vocabulário do English Sporting).", "say": "Doubles simultâneos da torre, cinco."}], "quiz": [{"q": "Num double ao tiro, o que lança o segundo prato?", "options": ["Um segundo pedido", "O sinal do árbitro", "O tiro ao primeiro prato", "Um temporizador de exatamente 5 segundos"], "answer": 2, "why": "«On report» significa ao som do tiro: disparar ao primeiro prato lança o segundo."}, {"q": "Um atirador dispara os dois cartuchos ao primeiro prato de um double simultâneo no Compak® Sporting. Resultado?", "options": ["Permitido, como no Sporting™", "Zero-zero", "NULO e repetição", "Só o segundo prato conta zero"], "answer": 1, "why": "O Compak® Sporting permite um cartucho por prato de um double; disparar deliberadamente os dois ao mesmo prato dá zero-zero. No Sporting™ seria permitido."}, {"q": "Um treinador britânico diz «true pair». Como o traduz?", "options": ["Um double correto e justo", "Um par de aves verdadeiras", "Um rafale", "Um double simultâneo"], "answer": 3, "why": "«True pair» é o nome do English Sporting para o double simultâneo; «true» não tem nada a ver com correção."}]}]}, {"id": "basics", "icon": "stance", "title": "Fundamentos do tiro", "intro": "Antes de qualquer conversa sobre o avanço, o treinador trata do básico: pés, pôr a arma à cara, olhos, um plano de três pontos e uma arma que nunca para. Estas cinco lições dão-lhe as palavras do treinador para cada passo e as regras que limitam o que o atirador pode fazer.", "lessons": [{"id": "basics-stance", "minutes": 5, "title": "Posição dos pés: pés virados para o ponto de tiro", "body": ["A posição (stance) é a forma como o atirador se coloca antes do tiro. O espaço é pequeno: no Parcours de Chasse – Sporting™ o posto é um quadrado ou um círculo de 1 m, e os dois pés têm de estar dentro dele antes do pedido do prato. No Compak® Sporting cada posto é um quadrado de 1 m com um limitador de ângulo de tiro, uma estrutura que impede o atirador de avançar e limita o movimento da arma.", "A base habitual: pés mais ou menos à largura dos ombros; num destro, o pé esquerdo ligeiramente à frente (um canhoto faz o inverso); joelhos soltos, não bloqueados; peso ligeiramente para a frente, cerca de 60 por cento no pé da frente. Os treinadores dizem «nose over toes» (nariz por cima dos dedos dos pés).", "A instrução-chave: apontar o pé da frente para o ponto de tiro (break point), o sítio onde o atirador planeia partir o prato. O corpo fica então confortável, «desenrolado», exatamente onde acontece o tiro. O atirador roda para trás a partir da anca até ao ponto de espera da arma e desenrola-se para o tiro. Se os pés estiverem virados para a máquina, avisam os treinadores, o corpo fica sem rotação, e a arma para ou a cabeça levanta-se.", "O corpo roda a partir da anca, não dos braços. Os pés podem ficar colocados de forma ligeiramente diferente para cada prato.", "Traduza «front foot» e «back foot» como pé da frente e pé de trás, não como esquerdo e direito: o seu atirador pode ser canhoto."], "key_points": ["Sporting™: os dois pés dentro do posto de 1 m antes do pedido.", "Compak® Sporting: posto de 1 m com limitador de ângulo de tiro.", "Pés à largura dos ombros, joelhos soltos, peso ligeiramente para a frente.", "O pé da frente aponta para o ponto de tiro; rodar para trás a partir da anca até ao ponto de espera.", "Traduza pé da frente / pé de trás, não esquerdo / direito."], "terms": ["stance", "shooting-stand", "break-point", "hold-point", "firing-angle-limiter"], "sources": [{"title": "NSSA-NSCA — Stance and foot position (blog)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "Shotgun Life — Best foot position for clays shooting", "url": "https://www.shotgunlife.com/briefs/best-foot-position-for-clays-shooting.html"}, {"title": "Positive Shooting — Stance", "url": "http://www.positiveshooting.com/StanceMain.html"}], "sim": {"type": "flight", "preset": "crosser-lr", "focus": "stance"}, "rule_refs": [{"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}], "coach_says": [{"en": "Point your front foot at the break point.", "meaning": "Vire a ponta do pé da frente para o sítio onde o prato vai ser partido.", "say": "Aponte o pé da frente para o ponto de tiro."}, {"en": "Set your feet for the break, then wind back to the hold.", "meaning": "Primeiro coloque os pés para o ponto de tiro, depois rode o tronco para trás até ao ponto de espera da arma.", "say": "Ponha os pés para o tiro e depois rode para trás até ao ponto de espera."}, {"en": "Weight forward, soft knees.", "meaning": "Incline-se ligeiramente para o pé da frente e não bloqueie os joelhos.", "say": "Peso à frente, joelhos soltos."}, {"en": "Turn from the hips, not the arms.", "meaning": "Roda o tronco inteiro; os braços não movem a arma sozinhos.", "say": "Rode a partir da anca, não dos braços."}], "quiz": [{"q": "Para onde quer normalmente o treinador que aponte o pé da frente?", "options": ["Para a máquina", "Para o ponto de visão", "Para o árbitro", "Para o ponto de tiro"], "answer": 3, "why": "Pés virados para o ponto de tiro deixam o corpo confortável onde o tiro acontece; pés virados para a máquina deixam o corpo sem rotação."}, {"q": "O que exigem as regras do Parcours de Chasse – Sporting™ quanto aos pés antes do pedido?", "options": ["Os dois pés dentro do posto", "O pé da frente sobre a linha do posto", "Pés juntos", "Nenhuma exigência"], "answer": 0, "why": "A regra da posição de partida exige os dois pés dentro do posto de tiro de 1 m antes de o atirador pedir o prato."}, {"q": "Um atirador canhoto. O treinador diz «Open your front foot». Que pé é?", "options": ["Sempre o esquerdo, seja qual for a mão", "O direito: é o pé da frente de um canhoto", "O pé de trás, mais perto da máquina", "Os dois pés juntos"], "answer": 1, "why": "Num canhoto, o pé da frente é o direito. Traduzir «front foot» como «pé da frente» evita o erro."}]}, {"id": "basics-mount", "minutes": 6, "title": "Posição de partida e pôr a arma à cara", "body": ["No Parcours de Chasse – Sporting™ parte-se de arma em baixo. Antes de pedir o prato, o talão da coronha toca no corpo e a parte superior traseira da coronha fica abaixo de uma linha no colete, 25 cm abaixo do eixo dos ombros, numa cor contrastante. O atirador mantém esta posição até o prato ser lançado e estar visível. Pôr a arma à cara mais cedo vale uma advertência verbal com cartão amarelo; se se repetir no mesmo percurso, vem o cartão vermelho e o prato conta zero.", "No Compak® Sporting a posição da arma no momento do pedido é livre, por isso a arma pode já estar no ombro. Nas duas disciplinas todos os pratos se atiram com a arma no ombro, e no Sporting™ a posição da arma é livre entre os dois pratos de um double.", "Pôr a arma à cara (gun mount) é levar a arma à face e ao ombro. Os treinadores ensinam «muzzles first» (primeiro as bocas dos canos): a mão da frente põe as bocas dos canos em movimento ao longo da linha do prato, a coronha sobe até à face e assenta na concavidade do ombro quando a arma apanha a linha. «Move, mount, shoot» (mover, montar, disparar) é um único movimento fluido. A arma vem à cara, não a cara à arma; a face fica na crista, porque o olho é a mira traseira.", "Um treinador britânico pode dizer «gun up» ou «pre-mount this one» (este com a arma já à cara). Isso é ilegal numa competição de Sporting™ da FITASC, normal no Compak® Sporting, e apenas um exercício no treino. Pôr a arma à cara e movê-la ao longo de uma linha imaginária antes de pedir o prato (simulacro de tiro, mock shooting) é proibido no Sporting™: primeiro uma advertência, depois um zero."], "key_points": ["Sporting™: coronha abaixo da linha do colete (25 cm abaixo do eixo dos ombros) até o prato estar visível.", "Arma à cara antes do tempo: cartão amarelo, depois cartão vermelho e prato perdido no mesmo percurso.", "Compak® Sporting: posição da arma livre no pedido; atira-se sempre com a arma no ombro.", "Primeiro as bocas dos canos, arma à cara, face na crista: mover, montar, disparar.", "«Pre-mount» é um exercício de treino, nunca numa competição de Sporting™ da FITASC."], "terms": ["ready-position", "jacket-line", "gun-mount", "move-mount-shoot", "comb", "yellow-card", "mock-shooting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-lr", "focus": "mount"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Gun to your face, not your face to the gun.", "meaning": "Suba a coronha até à face; não baixe a cabeça ao encontro da arma.", "say": "A arma vem à cara, não a cara à arma."}, {"en": "Muzzles first — move, mount, shoot.", "meaning": "Ponha os canos em movimento com o prato, monte a arma durante o movimento e dispare quando ela estiver bem assente.", "say": "Primeiro os canos — mover, montar, disparar."}, {"en": "Your mount's late and too fast — start it with the front hand.", "meaning": "A arma sobe tarde demais e aos solavancos; a mão da frente deve conduzir o movimento mais cedo.", "say": "Está a montar tarde e depressa demais — comece com a mão da frente."}, {"en": "Low gun on this one, like in competition.", "meaning": "Comece com a coronha abaixo da linha do colete, como exigem as regras de Sporting™ da FITASC.", "say": "Neste, arma em baixo, como em competição."}], "quiz": [{"q": "No Parcours de Chasse – Sporting™, até quando tem a coronha de ficar abaixo da linha do colete?", "options": ["Até o atirador pedir o prato", "Até o árbitro fazer sinal com a cabeça", "Até o prato ter saído e estar visível", "Até ser disparado o primeiro tiro"], "answer": 2, "why": "A posição de partida mantém-se até o prato ter sido lançado e estar à vista; só então se pode pôr a arma à cara."}, {"q": "No Compak® Sporting, pode um atirador pedir o prato com a arma já no ombro?", "options": ["Não: vale um cartão amarelo", "Só nos coelhos e noutros pratos baixos", "Só entre os dois pratos de um double", "Sim: a posição da arma no pedido é livre"], "answer": 3, "why": "O Compak® Sporting não tem regra de arma em baixo: a arma pode estar à cara ou não no momento do pedido, mas todos os pratos se atiram com a arma no ombro."}, {"q": "Porque insistem os treinadores em que a face fique na crista?", "options": ["O olho é a mira traseira, por isso tem de ficar sempre no mesmo sítio", "Para reduzir o ruído que chega ao ouvido", "Porque as regras das duas disciplinas o exigem", "Para esconder a cara do árbitro"], "answer": 0, "why": "Uma espingarda não tem mira traseira: o olho por cima da fita é a mira, por isso uma face levantada atira o chumbo para cima."}]}, {"id": "basics-eyes", "minutes": 5, "title": "Olhos: dominância, os dois olhos abertos, foco firme", "body": ["A maioria das pessoas tem um olho dominante (olho diretor) em que o cérebro confia mais, normalmente do mesmo lado da mão dominante. O olho dominante tem de ser o que olha ao longo da fita. Dominância cruzada significa que o olho dominante está do lado oposto ao ombro de tiro; visão central significa que nenhum dos olhos domina claramente. Em ambos os casos a arma aponta para onde o atirador não espera, muitas vezes para um dos lados.", "Um teste simples: com os dois olhos abertos, enquadre um objeto distante num pequeno triângulo feito com as mãos e depois feche um olho de cada vez; o olho que mantém o objeto dentro do triângulo é o dominante. O treinador também se pode pôr à frente do atirador e olhar através do triângulo.", "Soluções escolhidas pelo treinador: fechar ou semicerrar o outro olho ao pôr a arma à cara; um pequeno ponto nos óculos de proteção; aprender a atirar do outro ombro; ou, mais raramente, uma coronha cruzada (cross-over). Prefere-se, sempre que possível, atirar com os dois olhos abertos, porque dois olhos avaliam melhor a velocidade, o ângulo e a distância.", "Foco: um foco suave e largo enquanto se espera no ponto de visão, depois um foco firme no próprio prato, de preferência na sua aresta da frente. Olhar para trás, para o cano ou para o ponto de mira, para verificar o avanço, faz parar a arma.", "Os óculos de proteção são obrigatórios para os atiradores nas duas disciplinas, por isso o ponto vai neles."], "key_points": ["O olho dominante tem de olhar ao longo da fita.", "A dominância cruzada e a visão central fazem a arma apontar ao lado do prato.", "Teste com um triângulo feito com as mãos; o treinador escolhe a solução.", "Foco suave no ponto de visão, foco firme na aresta da frente; nunca olhe para trás, para o ponto de mira.", "Os óculos de proteção são obrigatórios nas duas disciplinas."], "terms": ["eye-dominance", "master-eye", "cross-dominance", "central-vision", "soft-focus", "hard-focus", "leading-edge", "safety-glasses"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "Paragon School — Eye dominance testing", "url": "https://www.paragonschool.com/blog-post/eye-dominance-testing-and-issues-in-sporting-clays-skeet-and-trap-go-slowly-please"}, {"title": "Shotgun Life — How to shoot a chandelle target (focus on the leading edge)", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}], "sim": {"type": "flight", "preset": "going-away", "focus": "eyes"}, "rule_refs": [{"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}], "coach_says": [{"en": "Close your left eye as the gun comes up.", "meaning": "Feche o olho esquerdo durante a montagem da arma, não antes, para que seja o olho direito a controlar a arma.", "say": "Feche o olho esquerdo quando a arma sobe."}, {"en": "Eyes on the clay, not the barrel.", "meaning": "Continue a olhar para o prato; verificar o cano faz parar a arma.", "say": "Olhos no prato, não no cano."}, {"en": "Look at the leading edge.", "meaning": "Concentre-se na aresta da frente do prato em movimento, não no meio dele.", "say": "Olhe para a frente do prato."}, {"en": "Don't look at the trap — look out to your pick-up point.", "meaning": "Espere com os olhos um pouco mais à frente na linha, onde o prato se vê nítido pela primeira vez.", "say": "Não olhe para a máquina — olhe para o seu ponto de visão."}], "quiz": [{"q": "Um atirador destro tem o olho esquerdo dominante. Como se chama isto?", "options": ["Visão central", "Foco firme", "Dominância cruzada", "Aresta da frente"], "answer": 2, "why": "Dominância cruzada é ter o olho dominante do lado oposto ao ombro de tiro."}, {"q": "Porque é um erro olhar para trás, para o ponto de mira, para verificar o avanço?", "options": ["É proibido pelas regras", "Faz parar a arma e o chumbo vai para trás", "O ponto de mira reflete o sol", "Faz o prato mudar de cor"], "answer": 1, "why": "Quando o foco passa para a arma, o movimento para e o prato fica na visão periférica, por isso o chumbo passa atrás."}, {"q": "Onde se põe normalmente o ponto contra a dominância?", "options": ["Nos óculos de proteção, à frente do olho a bloquear", "No ponto de mira, na ponta da fita", "Na fita, a meio do comprimento", "Na linha do colete, abaixo do ombro"], "answer": 0, "why": "Os óculos de proteção são obrigatórios de qualquer forma, por isso um pequeno ponto na lente à frente do olho não dominante é a solução mais simples."}]}, {"id": "basics-three-points", "minutes": 5, "title": "Ponto de visão, ponto de espera e ponto de tiro: planear um posto", "body": ["Antes de cada prato o atirador define três pontos. O ponto de visão (pick-up point) é onde os olhos veem o prato com nitidez pela primeira vez, um pouco afastado da máquina e não à saída dela, onde o prato é apenas um borrão. O ponto de espera da arma (hold point) é onde as bocas dos canos esperam no momento do pedido, normalmente sobre a linha do prato ou um pouco abaixo dela, entre o ponto de visão e o ponto de tiro. O ponto de tiro (break point) é onde o atirador planeia partir o prato.", "Ordem do planeamento: escolher primeiro o ponto de tiro, colocar os pés em função dele, rodar para trás até ao ponto de espera e depois pôr os olhos no ponto de visão. No Parcours de Chasse – Sporting™ a coronha está em baixo até o prato aparecer, por isso aí o ponto de espera significa para onde apontam as bocas dos canos enquanto a arma está em baixo.", "Erros típicos: um ponto de tiro demasiado longe significa um movimento rápido e descontrolado, ou um prato que já está a cair; demasiado perto significa movimento a menos e um tiro «espetado». Um ponto de espera demasiado perto da máquina obriga a arma a correr atrás do prato; demasiado longe, o prato ultrapassa a arma.", "Os pratos leem-se durante a mostra. No Sporting™ todas as trajetórias são mostradas ao primeiro atirador e, a pedido, o árbitro repete a mostra, até dois pratos por cada prato do menu; no Compak® Sporting por esquadras, os simples são mostrados uma vez de manhã, à primeira esquadra. O prato tem de ser partido onde o árbitro o possa ver, dentro do limite da zona de tiro.", "«Where are you taking it?» (onde lhe vai atirar?) pergunta pelo ponto de tiro; «kill point» é um sinónimo neutro."], "key_points": ["Ponto de visão = olhos; ponto de espera = bocas dos canos; ponto de tiro = onde o prato é partido.", "Planeie a partir do ponto de tiro para trás: pés, ponto de espera, olhos.", "O ponto de espera fica normalmente entre o ponto de visão e o ponto de tiro, sobre a linha ou um pouco abaixo.", "Leia os pratos durante a mostra; parta-os onde o árbitro possa ver.", "«Where are you taking it?» = onde é o seu ponto de tiro?"], "terms": ["pick-up-point", "hold-point", "break-point", "target-presentation", "shooting-limit", "target-line"], "sources": [{"title": "Shotgun Life — The proper hold point for sporting clays", "url": "https://www.shotgunlife.com/briefs/what-is-the-proper-hold-point-for-shooting-sporting-clays.html"}, {"title": "Clay Target Instruction — Hold point", "url": "https://claytargetinstruction.com/articles/hold-point/"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "flight", "preset": "quartering-away", "focus": "points"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}], "coach_says": [{"en": "Where are you taking it?", "meaning": "O treinador pergunta onde o atirador planeia partir o prato.", "say": "Onde é que lhe vai atirar?"}, {"en": "Move your hold point halfway back to the trap.", "meaning": "Mantenha as bocas dos canos mais perto da máquina, a metade da distância atual.", "say": "Traga o ponto de espera para metade do caminho até à máquina."}, {"en": "Look further out — pick it up where it's sharp.", "meaning": "Afaste os olhos da máquina para onde o prato se vê nítido pela primeira vez.", "say": "Olhe mais à frente — apanhe-o onde ele está nítido."}, {"en": "Hold a little lower, just under the line.", "meaning": "Mantenha as bocas dos canos ligeiramente abaixo da trajetória do prato no momento do pedido.", "say": "Espere um pouco mais baixo, mesmo por baixo da linha."}], "quiz": [{"q": "Que ponto diz respeito aos olhos e não à arma?", "options": ["Ponto de espera", "Ponto de tiro", "Ponto de visão", "Ponto de inserção"], "answer": 2, "why": "O ponto de visão é onde os olhos veem o prato com nitidez pela primeira vez; o ponto de espera é para as bocas dos canos."}, {"q": "O que acontece normalmente se o ponto de espera estiver demasiado perto da máquina?", "options": ["O prato ultrapassa a arma", "O árbitro declara NULO", "A arma tem de correr atrás do prato", "O prato abranda"], "answer": 2, "why": "Demasiado perto da máquina, o prato passa a toda a velocidade pelas bocas dos canos e o atirador tem de correr atrás dele."}, {"q": "No Parcours de Chasse – Sporting™, o atirador no posto pede para ver a mostra outra vez. Qual é o máximo por cada prato do menu?", "options": ["Dois pratos", "Nenhum: não são permitidas repetições", "Tantos quantos quiser", "Exatamente cinco"], "answer": 0, "why": "O árbitro repete a mostra a pedido, até um máximo de dois pratos por cada prato do menu."}]}, {"id": "basics-follow-through", "minutes": 5, "title": "Acompanhamento, velocidade da arma e ritmo", "body": ["Acompanhamento (follow-through) significa que a arma continua a mover-se ao longo da linha do prato depois de se carregar no gatilho, como no swing do golfe ou do ténis. Há um pequeno atraso entre a decisão de disparar e a saída do chumbo dos canos; se a arma parar no gatilho, o chumbo vai para trás. Os treinadores observam as bocas dos canos depois do tiro: se ficarem paradas ou caírem, faltou o acompanhamento.", "A velocidade da arma é a rapidez com que as bocas dos canos se movem em comparação com o prato, e define o método de avanço: à mesma velocidade do prato é o avanço mantido (maintained lead); mais rápida do que o prato é o swing-through; à mesma velocidade e depois com uma curta aceleração é o pull-away. Uma arma demasiado lenta fica para trás; uma demasiado rápida, dizem os treinadores, passa à frente, e o atirador muitas vezes acaba por pará-la.", "O andamento (tempo) é a rapidez com que todo o tiro é executado; o ritmo é a sua regularidade. Um prato rápido e próximo exige um andamento rápido, um transversal comprido e lento um andamento mais calmo, mas o ritmo mantém-se fluido. Muitos treinadores dizem que os atiradores com um só andamento para tudo perdem os pratos que exigem o contrário.", "«Stay in the gun» (ficar na arma): face na coronha e olhos no prato até ele se partir. Isso também mantém o atirador pronto para o segundo cano, porque se podem disparar dois tiros a um prato simples.", "Traduza «finish the shot» como continuar o movimento, não como parar."], "key_points": ["Acompanhamento: a arma continua a mover-se depois do gatilho; parar manda o chumbo para trás.", "A velocidade da arma define o método: igual (avanço mantido), mais rápida (swing-through), igual e depois mais rápida (pull-away).", "Andamento = velocidade de todo o tiro; ritmo = a sua regularidade.", "Ficar na arma: pronto para o segundo cano num prato simples.", "«Finish the shot» = continuar o movimento."], "terms": ["follow-through", "gun-speed", "tempo", "stopping-the-gun", "maintained-lead", "swing-through", "pull-away", "single-target"], "sources": [{"title": "Shooting UK — The overhead clay from behind (follow-through)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "focus": "follow-through"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "Follow through — the gun keeps moving after the bang.", "meaning": "Não pare o movimento no momento do tiro.", "say": "Acompanhe — a arma continua a mexer depois do tiro."}, {"en": "You stopped the gun.", "meaning": "As bocas dos canos pararam no gatilho, por isso o chumbo passou atrás.", "say": "Parou a arma."}, {"en": "Match the speed of the bird — you're racing it.", "meaning": "A arma está a mover-se muito mais depressa do que o prato; mova-se à velocidade do prato.", "say": "Acompanhe a velocidade do prato — está a fazer corrida com ele."}, {"en": "Slow the tempo down, this one gives you lots of time.", "meaning": "O prato é lento ou distante, por isso todo o movimento pode ser mais calmo.", "say": "Abrande o andamento, este dá-lhe muito tempo."}, {"en": "Stay in the gun until you see it break.", "meaning": "Mantenha a face na coronha e os olhos no prato até ele se partir.", "say": "Fique na arma até o ver partir."}], "quiz": [{"q": "O treinador diz «You stopped the gun». Para onde foi muito provavelmente o chumbo?", "options": ["À frente", "Por cima", "Exatamente no prato", "Atrás"], "answer": 3, "why": "O prato continua a mover-se e a arma parada não, por isso o chumbo passa atrás dele."}, {"q": "Que velocidade da arma descreve o avanço mantido?", "options": ["Muito mais rápida do que o prato", "A mesma do prato", "Zero: a arma espera", "Mais lenta do que o prato"], "answer": 1, "why": "No avanço mantido as bocas dos canos movem-se à velocidade do prato, mantendo a distância constante. Uma arma que espera é emboscada (ambush); mais rápida é swing-through."}, {"q": "Qual é a diferença entre andamento e ritmo?", "options": ["O andamento é a velocidade do tiro, o ritmo a sua regularidade", "São duas palavras para a mesma coisa", "O andamento é a música que toca no campo", "O ritmo é o tempo-limite entre pratos"], "answer": 0, "why": "Os treinadores mudam o andamento para cada prato mantendo um ritmo fluido, por isso traduza as duas palavras separadamente."}]}]}, {"id": "lead", "icon": "lead", "title": "Avanço e métodos de tiro", "intro": "O avanço (lead) é o assunto de que os treinadores mais falam: porque é que a arma tem de apontar à frente de um prato em movimento, as quatro maneiras de lá chegar e as estranhas unidades que usam para o descrever. Esta missão mostra cada método passo a passo e ensina-o a traduzir «four foot», «half a bird» ou «double it» sem mudar o sentido.", "lessons": [{"id": "lead-why", "minutes": 6, "title": "Porque existe o avanço: avanço real e avanço percebido", "body": ["O chumbo precisa de uma fração de segundo para chegar ao prato, e nesse tempo o prato continua a avançar. Uma arma apontada diretamente a um transversal atira, portanto, atrás dele. A arma tem de apontar à frente, para que o chumbo e o prato se encontrem. Essa distância é o avanço (lead; no inglês britânico também «forward allowance»).", "O avanço aumenta com a velocidade do prato, a sua distância e o seu ângulo. Um transversal puro é o que precisa de mais; um prato que vem direito ao atirador ou se afasta dele em linha reta quase não precisa de avanço lateral, embora os pratos que sobem e descem precisem de avanço vertical (por cima ou por baixo).", "Os números reais surpreendem. Um site sobre tiro indica cerca de 3 a 4 pés, aproximadamente um metro, de avanço real para um transversal a cerca de 21–25 jardas (por volta de 20 m). Muitos atiradores dizem que o avanço cresce mais ou menos em proporção com a distância, por isso a mesma pequena distância vista na boca do cano significa muito mais avanço real num prato distante.", "O avanço real é a distância verdadeira à frente do prato, no ar. O avanço percebido (a «lead picture» ou «sight picture», a imagem do avanço) é a distância que o atirador vê entre a boca do cano e o prato. Um metro a 20 m parece apenas alguns centímetros na boca do cano. O método muda a imagem: quem usa o avanço mantido vê a maior distância, quem usa o swing-through vê pouca ou nenhuma, porque a velocidade da arma acrescenta avanço.", "Um instrutor americano observa que um atirador destro sente muitas vezes que um transversal da esquerda para a direita precisa de mais avanço do que um da direita para a esquerda; o avanço real é o mesmo, só a perceção muda. Por isso, os «four feet» (quatro pés) de um treinador descrevem a imagem que ele vê, não uma medição."], "key_points": ["O avanço existe porque o prato se move enquanto o chumbo viaja.", "Mais velocidade, distância e ângulo significam mais avanço.", "O avanço real (no ar) é muito maior do que o avanço percebido (na boca do cano).", "O método muda a imagem: no avanço mantido vê-se mais, no swing-through menos.", "O número de um treinador é uma imagem, não uma medição."], "terms": ["lead", "perceived-lead", "crosser", "gun-speed", "maintained-lead", "swing-through"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "focus": "perceived-vs-actual"}, "rule_refs": [], "coach_says": [{"en": "Forget the real distance — what matters is your picture.", "meaning": "Não pense em metros no ar; lembre-se da distância que viu na boca do cano quando acertou.", "say": "Esqueça a distância real — o que conta é a sua imagem."}, {"en": "That's the picture — remember it.", "meaning": "O avanço estava certo nesse acerto; mantenha a mesma imagem.", "say": "É essa a imagem — memorize-a."}, {"en": "Same lead on the right-to-left, it only looks different.", "meaning": "O avanço real é igual nas duas direções; só a perceção muda.", "say": "O mesmo avanço no da direita para a esquerda, só parece diferente."}], "quiz": [{"q": "O que é o avanço percebido?", "options": ["A distância real à frente do prato, no ar", "A distância que o atirador vê entre a boca do cano e o prato", "O avanço escrito no menu de tiro", "A distância do posto à máquina"], "answer": 1, "why": "O avanço percebido é a imagem na boca do cano; o avanço real é a distância verdadeira no ar e é muito maior."}, {"q": "Que método dá normalmente o maior avanço percebido?", "options": ["Swing-through", "Pull-away", "Avanço mantido", "São todos iguais"], "answer": 2, "why": "No avanço mantido a arma move-se à velocidade do prato e a velocidade da arma não acrescenta nada, por isso o atirador tem de ver toda a distância."}, {"q": "Que prato quase não precisa de avanço lateral?", "options": ["Um prato que se afasta em linha reta", "Um transversal comprido", "Um prato de saída em diagonal a 45°", "Um transversal a 40 m"], "answer": 0, "why": "Um prato de saída em linha reta não tem movimento lateral; o avanço de que precisa é vertical."}]}, {"id": "lead-maintained", "minutes": 5, "title": "Avanço mantido: pôr-se à frente e ficar à frente", "body": ["O avanço mantido (maintained lead; nos EUA sustained lead; em português também «avanço sustentado») mantém as bocas dos canos à frente do prato desde o início até ao disparo.", "Como funciona, passo a passo, num transversal. 1) Início: as bocas dos canos esperam num ponto de espera bem à frente na linha, adiante do sítio por onde o prato vai passar; os olhos olham para trás, para o ponto de visão. 2) Inserção: quando o prato vem, a arma move-se e as bocas dos canos entram na linha à frente dele, nunca atrás; é o ponto de inserção. 3) Acompanhamento: as bocas dos canos movem-se à velocidade do prato, por isso a distância mantém-se igual. 4) Disparo: carrega-se no gatilho com a distância certa e a arma ainda em movimento. 5) A arma continua a mover-se depois do tiro.", "Pontos fortes: preciso, pouco movimento da arma, rápido entre pratos, e o avanço é fácil de ajustar. Adequa-se a pratos regulares e previsíveis: transversais compridos, pratos altos e estáveis.", "Pontos fracos: é o método mais difícil de aprender; o atirador tem de conhecer antecipadamente a velocidade e a linha do prato; e como a arma não é mais rápida do que o prato, o atirador vê a maior distância e é tentado a medi-la, abrandar e parar.", "Os treinadores dizem «insert the gun in front» (meta a arma à frente), «stay ahead of it» (fique à frente dele), «match its speed» (acompanhe a velocidade dele)."], "key_points": ["As bocas dos canos começam à frente e entram na linha à frente do prato.", "Velocidade da arma = velocidade do prato; a distância mantém-se constante.", "Gatilho com a distância certa e a arma em movimento; depois, acompanhamento.", "Melhor em pratos compridos e previsíveis.", "Principal risco: medir a distância e parar a arma."], "terms": ["maintained-lead", "insertion-point", "hold-point", "gun-speed", "follow-through", "crosser"], "sources": [{"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shotgun Sports USA — How to read sporting clays targets (insertion point)", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "muzzle_start": "ahead", "gun_speed": "equal", "trigger": "gap-held", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Get in front and stay in front.", "meaning": "Ponha as bocas dos canos à frente do prato e mantenha-as lá até depois do tiro.", "say": "Ponha-se à frente e fique à frente."}, {"en": "Your insertion point is behind the bird — put the gun in front of it.", "meaning": "As bocas dos canos entraram na linha atrás do prato; têm de entrar à frente dele.", "say": "O seu ponto de inserção está atrás do prato — meta a arma à frente dele."}, {"en": "Match its speed — don't let it catch you.", "meaning": "Mova a arma à velocidade do prato, para que a distância não diminua.", "say": "Acompanhe a velocidade dele — não o deixe apanhá-lo."}, {"en": "You're measuring it — trust the picture and pull.", "meaning": "O atirador está a abrandar para verificar a distância; dispare assim que a imagem estiver certa.", "say": "Está a medi-lo — confie na imagem e dispare."}], "quiz": [{"q": "No avanço mantido, onde entram as bocas dos canos na linha do prato?", "options": ["Atrás do prato", "Sobre o prato", "À frente do prato", "Abaixo da máquina"], "answer": 2, "why": "As bocas dos canos entram à frente do prato e ficam à frente; atrás é swing-through, sobre o prato é pull-away."}, {"q": "Qual é o erro típico de quem atira com avanço mantido?", "options": ["Começar demasiado atrás", "Medir a distância e parar a arma", "Montar a arma a partir da anca", "Atirar cedo demais, junto à máquina"], "answer": 1, "why": "A distância é grande e visível, por isso os atiradores são tentados a verificá-la; a arma abranda ou para e o chumbo vai para trás."}, {"q": "Para que prato se recomenda muitas vezes o avanço mantido?", "options": ["Um transversal comprido e previsível", "Um coelho a saltar numa abertura curta", "Um prato-surpresa vindo de trás", "Um prato ZZ"], "answer": 0, "why": "O método exige uma velocidade e uma linha conhecidas, que os transversais compridos e estáveis oferecem; os pratos irregulares ou de surpresa adequam-se a outros métodos."}]}, {"id": "lead-swing-through", "minutes": 5, "title": "Swing-through: vir por trás, atravessando o prato", "body": ["No swing-through as bocas dos canos começam atrás do prato e ultrapassam-no. Em português pode ouvir «swing», «vir por trás», «correr a mão» ou simplesmente «swing-through».", "Como funciona, passo a passo. 1) Início: as bocas dos canos entram na linha do prato atrás dele, na cauda. 2) Ultrapassagem: a arma move-se mais depressa do que o prato, ao longo da sua linha, atravessando-lhe o corpo. 3) Disparo: carrega-se no gatilho quando as bocas dos canos passam a frente do prato, logo à frente dele. Como há um pequeno atraso entre a decisão e o disparo e a arma se move mais depressa do que o prato, as bocas dos canos já estão mais à frente quando o chumbo sai: o avanço real no momento do disparo é maior do que o avanço que o atirador vê, e vê-se pouca ou nenhuma distância. 4) O movimento continua depois do tiro. A mnemónica é «butt, belly, beak, bang»: cauda, corpo, frente, disparo. No inglês britânico pode ouvir «bum» em vez de «butt»; traduza como «cauda».", "Pontos fortes: natural e rápido; bom para principiantes, para pratos próximos e rápidos, para pratos de batida e por cima, e para pratos irregulares ou de surpresa.", "Pontos fracos: uma janela muito curta para o gatilho; nos transversais compridos o atirador pode ficar sem tempo, perder a linha ou passar à frente demais; abrandar quando as bocas dos canos chegam ao prato dá uma falha atrás.", "As fontes não concordam sobre o nome «CPSA method»: algumas descrevem-no como swing-through, enquanto se diz que o ensino da CPSA hoje em dia ensina o pull-away. Se um treinador disser «CPSA method», pergunte qual dos dois quer dizer."], "key_points": ["As bocas dos canos começam atrás, na linha do prato.", "Arma mais rápida do que o prato: cauda, corpo, frente, disparo.", "Gatilho quando as bocas dos canos passam a frente; o avanço real é maior do que o avanço visto.", "Bom para pratos próximos, rápidos, de batida e de surpresa; mais difícil em transversais compridos.", "«CPSA method» é ambíguo: pergunte que método se quer dizer."], "terms": ["swing-through", "gun-speed", "perceived-lead", "driven-target", "overhead", "follow-through"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}], "sim": {"type": "lead", "method": "swing-through", "preset": "crosser-lr", "muzzle_start": "behind", "gun_speed": "faster", "trigger": "passing-front", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Come from behind, through the bird, and shoot as you see daylight.", "meaning": "Comece atrás do prato, atravesse-o e dispare quando aparecer uma abertura à frente.", "say": "Venha de trás, atravesse o prato e dispare quando vir luz à frente dele."}, {"en": "Butt, belly, beak, bang.", "meaning": "Mnemónica: cauda, corpo, frente do prato e depois disparo.", "say": "Cauda, corpo, bico, tiro."}, {"en": "You slowed down as you got to it.", "meaning": "A arma perdeu velocidade quando chegou ao prato, por isso o chumbo passou atrás.", "say": "Abrandou quando chegou a ele."}, {"en": "Brush it out and keep going.", "meaning": "Atravesse o prato como se o apagasse do céu, sem parar.", "say": "Apague-o do céu e continue."}], "quiz": [{"q": "Onde começam as bocas dos canos no swing-through?", "options": ["À frente do prato", "Na aresta da frente do prato", "Num ponto fixo, no ponto de tiro", "Atrás do prato, na sua linha"], "answer": 3, "why": "O swing-through começa atrás e ultrapassa o prato; começar à frente é avanço mantido, um ponto fixo é emboscada (ambush)."}, {"q": "Porque é que quem atira em swing-through vê pouco ou nenhum avanço?", "options": ["Os pratos são sempre mais lentos", "A velocidade da arma cria o avanço", "As regras proíbem uma distância visível", "O atirador fecha os dois olhos"], "answer": 1, "why": "A arma move-se mais depressa do que o prato, por isso, entre a decisão e o disparo, avança sozinha."}, {"q": "Um treinador diz «bum, belly, beak, bang». Como deve traduzir «bum»?", "options": ["Como «cauda»", "Com uma palavra grosseira, à letra", "Como «bum» (um som)", "Omitir completamente"], "answer": 0, "why": "Quer dizer a cauda do prato; um neutro «cauda» mantém o sentido e o ritmo da mnemónica."}]}, {"id": "lead-pull-away", "minutes": 5, "title": "Pull-away: no prato, com o prato, sair, disparar", "body": ["No pull-away (em português por vezes «sair do prato» ou «arrancar do prato») as bocas dos canos primeiro juntam-se ao prato e depois afastam-se para a frente dele. É muito ensinado no treino britânico moderno e hoje em dia é muitas vezes chamado CPSA method.", "Como funciona, passo a passo. 1) «On it» (no prato): a arma é montada sobre o prato ou sobre a sua aresta da frente; as bocas dos canos tocam-no na sua linha. 2) «With it» (com o prato): as bocas dos canos acompanham o prato por um momento à sua velocidade, ajustando a linha e o ritmo. 3) «Pull away» (sair): a arma acelera suavemente para a frente até aparecer a imagem de avanço certa. 4) «Shoot» (disparar): carrega-se no gatilho com a arma ainda a acelerar ou em movimento. 5) Acompanhamento: a arma continua depois do tiro.", "Pontos fortes: acompanhar primeiro o prato permite ao atirador avaliar a velocidade, a distância e a linha antes de se comprometer, por isso a linha é boa. Adequa-se a pratos compridos, em diagonal e ascendentes. Por causa da aceleração, o avanço percebido é menor do que no avanço mantido.", "Pontos fracos: a aceleração necessária varia de prato para prato, por isso é preciso prática para a sentir; acompanhar demasiado tempo torna-se «riding the target» (ir à boleia do prato), e parar o impulso dá uma falha atrás.", "Os treinadores dizem «touch it and go» (toque e saia), «mount on it and push out» (monte no prato e empurre para a frente) ou o compasso de quatro tempos «on it, with it, pull away, shoot». Mantenha o ritmo de quatro tempos quando traduzir: é mais importante do que as palavras exatas."], "key_points": ["As bocas dos canos começam no prato (ou na sua aresta da frente).", "Acompanhar à velocidade dele e depois acelerar para a frente.", "Gatilho com a arma ainda a avançar; depois, acompanhamento.", "Bom controlo da linha; adequa-se a pratos compridos, em diagonal e ascendentes.", "Mantenha o ritmo de quatro tempos ao traduzir."], "terms": ["pull-away", "insertion-point", "gun-speed", "perceived-lead", "quartering-away", "follow-through"], "sources": [{"title": "CPSA — How to hit series (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/how-to-hit-series-3"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "muzzle_start": "on-target", "gun_speed": "equal-then-faster", "trigger": "during-acceleration", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "On it, with it, pull away, shoot.", "meaning": "Junte-se ao prato, acompanhe-o, acelere para a frente, dispare.", "say": "No prato, com o prato, sai, dispara."}, {"en": "Touch it and go.", "meaning": "Encontre o prato com as bocas dos canos e comece imediatamente a sair para a frente.", "say": "Toque e saia."}, {"en": "You rode it too long.", "meaning": "O atirador acompanhou o prato demasiado tempo antes de sair e perdeu a linha ou o momento.", "say": "Foi à boleia dele tempo demais."}, {"en": "Mount on it and push out a bit more.", "meaning": "Monte a arma sobre o prato e depois saia um pouco mais para a frente antes de disparar.", "say": "Monte no prato e empurre um pouco mais para a frente."}], "quiz": [{"q": "No pull-away, o que acontece mesmo antes de se carregar no gatilho?", "options": ["A arma para sobre o prato", "A arma acelera para a frente do prato", "A arma desce para baixo do prato", "A arma espera no ponto de tiro"], "answer": 1, "why": "O próprio pull-away é a aceleração para a frente; o tiro é disparado com a arma ainda a avançar."}, {"q": "O treinador diz «You rode it too long». O que correu mal?", "options": ["Ficou demasiado tempo no posto antes de pedir o prato", "Pôs a arma à cara cedo demais", "Acompanhou o prato demasiado tempo antes de sair", "O operador lançou o prato atrasado"], "answer": 2, "why": "«Riding the target» é seguir o prato demasiado tempo, de modo que ele abranda, cai ou escapa, e a linha perde-se."}, {"q": "Em comparação com o avanço mantido, o avanço percebido no pull-away é normalmente…", "options": ["menor, porque a aceleração acrescenta avanço", "maior, porque a arma começa no prato", "sempre exatamente o dobro", "zero em todos os pratos"], "answer": 0, "why": "A breve aceleração leva a arma para a frente durante o atraso do disparo, por isso é preciso ver menos distância."}]}, {"id": "lead-ambush-instinctive", "minutes": 5, "title": "Emboscada e tiro instintivo", "body": ["A emboscada (ambush), ou tiro ao ponto (spot shooting; em português pode descrever-se como «esperar o prato num ponto» ou «tiro de interceção»), é o contrário de um swing. 1) As bocas dos canos são colocadas num ponto à frente do prato, na sua linha, perto do ponto de tiro. 2) Esperam com pouco ou nenhum movimento. 3) Carrega-se no gatilho quando o prato chega a esse ponto.", "Como hábito geral, típico de atiradores sem formação, não é fiável: a arma está parada e o tempo tem de ser perfeito. Mas uma emboscada deliberada é por vezes a escolha certa: um prato a que é preciso atirar muito depressa, ou um coelho que só se vê numa curta abertura entre arbustos. Um movimento parecido, nas batidas de cutelo no ponto mais alto do voo, é o «collapse»: esperar muito perto do ponto de tiro e fazer um movimento mínimo. O prato continua a ter de ser partido onde o árbitro o possa ver.", "Tiro instintivo significa nenhum avanço consciente. O atirador mantém um foco firme no prato e deixa as mãos seguirem; o movimento e a montagem da arma acontecem em conjunto, e o tiro sai quando a arma chega à cara. A escola clássica é a associada ao armeiro inglês Robert Churchill, popular na caça.", "Muitos dos melhores atiradores de Parcours de Chasse – Sporting™ misturam métodos e escolhem consoante o prato. «Which method for this one?» (que método para este?) é uma pergunta normal no treino."], "key_points": ["Emboscada: bocas dos canos paradas num ponto à frente; disparo quando o prato chega.", "Pouco fiável como hábito, útil de forma deliberada (pratos muito rápidos, aberturas curtas).", "«Collapse»: movimento mínimo perto do ponto de tiro nas batidas de cutelo.", "Instintivo: nenhum avanço consciente, foco firme, montagem e movimento em conjunto (escola de Churchill).", "Os bons atiradores escolhem o método prato a prato."], "terms": ["ambush", "instinctive-shooting", "hard-focus", "break-point", "battue", "rabbit"], "sources": [{"title": "Wikipedia — Clay pigeon shooting (methods)", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}, {"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "Shotgun Life — Wingshooting schools of England", "url": "https://www.shotgunlife.com/travel/places-to-shoot/wingshooting-schools-of-england-3.html"}], "sim": {"type": "lead", "method": "ambush", "preset": "rabbit", "muzzle_start": "at-break-point", "gun_speed": "none-or-minimal", "trigger": "target-arrives", "follow_through": false}, "rule_refs": [{"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "You're ambushing it — keep the gun moving with the target.", "meaning": "O atirador está à espera num ponto; o treinador quer aqui um método com movimento.", "say": "Está a emboscá-lo — mantenha a arma a mexer com o prato."}, {"en": "Ambush this one in the gap.", "meaning": "Espere deliberadamente na abertura e dispare quando o prato a atravessar.", "say": "Este, espere-o na abertura."}, {"en": "Don't think about the lead, just look at the bird and let the gun go to it.", "meaning": "Atire de forma instintiva: concentre-se no prato e deixe as mãos seguirem.", "say": "Não pense no avanço, olhe só para o prato e deixe a arma ir até ele."}, {"en": "Hold right on the break point and just collapse onto it.", "meaning": "Ponha as bocas dos canos quase no ponto de tiro e faça só um movimento mínimo quando a batida chegar.", "say": "Espere mesmo no ponto de tiro e deixe-se só cair sobre ele."}], "quiz": [{"q": "O que caracteriza a emboscada (tiro ao ponto)?", "options": ["A arma move-se mais depressa do que o prato", "A arma espera num ponto à frente do prato", "A arma acompanha o prato e depois acelera", "A arma começa atrás do prato, na sua linha"], "answer": 1, "why": "Emboscada significa pouco ou nenhum movimento: as bocas dos canos esperam na linha e o prato entra no tiro."}, {"q": "Quando pode uma emboscada deliberada ser uma boa escolha?", "options": ["Em todos os transversais compridos e estáveis", "Nunca: as regras proíbem-na", "Só no Compak® Sporting, nunca no Sporting™", "Num coelho que só se vê numa curta abertura"], "answer": 3, "why": "Quando o prato só se vê por pouco tempo, não há tempo para um swing, por isso esperar na abertura pode resultar. Nenhuma regra proíbe qualquer método."}, {"q": "O que é o tiro instintivo?", "options": ["Foco firme no prato, sem avanço consciente", "Atirar sem óculos de proteção", "Atirar à anca, sem pôr a arma à cara", "Esperar junto à máquina por cada prato"], "answer": 0, "why": "O tiro instintivo baseia-se na coordenação olho–mão; continua a fazer-se com a arma no ombro, como as regras exigem."}]}, {"id": "lead-how-coaches-say-it", "minutes": 6, "title": "Como os treinadores falam do avanço e como traduzi-lo", "body": ["Unidades. Os treinadores britânicos e americanos falam em pés e jardas: «give it four foot» (britânico para quatro pés), «two feet in front» (dois pés à frente). Os treinadores europeus usam metros. Um pé são cerca de 30 cm, uma jarda cerca de 0,9 m. Mas um número de avanço é a imagem do treinador, não uma medição, por isso mantenha o número e a unidade dele. Nunca converta a meio de uma instrução; se o atirador perguntar, explique por alto entre pratos. As distâncias até um prato («it's 30 yards») podem ser dadas como «cerca de 27 m».", "Larguras de prato: «half a bird» (meio prato), «a bird's width» (a largura de um prato), «a clay's length» (o comprimento de um prato). Bird quer dizer prato, nunca uma ave verdadeira: «meio prato». Larguras de cano: «a barrel's width» (a largura de um cano), «two barrels» (dois canos) referem-se à distância vista na boca do cano. Cuidado: os «two barrels» de um árbitro significam os dois canos disparados ao mesmo tempo.", "Palavras relativas: «more» (mais), «less» (menos), «a touch more» (um pouco mais), «double it» (o dobro), «half that» (metade disso), «same lead» (o mesmo avanço). Mantenha-as relativas e nunca invente um número. «Same lead» é fundamental: o atirador não deve acrescentar avanço.", "Direções: «in front» (à frente) e «behind» (atrás) referem-se ao sentido de deslocação do prato; «over» e «high» (por cima, alto), «under» e «low» (por baixo, baixo) são sinónimos. O mostrador do relógio descreve posições: 12 horas é em cima, 3 horas à direita, tal como o atirador vê. «You hit it at six» (acertou-lhe às seis) significa o rebordo de baixo; «it comes from eleven» (vem das onze) dá uma direção.", "Método: traduza o número, a unidade, a referência e a direção com exatidão, de forma curta, no ritmo do treinador. Se não for claro, pergunte-lhe com uma palavra: «Feet?» (pés?). Nas competições, o treino durante a prova é proibido."], "key_points": ["Mantenha o número e a unidade do treinador; nunca converta o avanço a meio de uma instrução.", "Bird = prato: «half a bird» = «meio prato».", "As palavras relativas continuam relativas; «same lead» tem de ser traduzido.", "Mostrador do relógio: 12 em cima, 3 à direita, tal como o atirador vê.", "Os «two barrels» de um árbitro são um disparo simultâneo dos dois canos, não um avanço."], "terms": ["lead", "perceived-lead", "clock-face", "double-discharge", "coach"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "Shooting UK — The overhead clay from behind (clock-face pick-up)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-rl", "focus": "lead-units"}, "rule_refs": [{"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Give it four foot.", "meaning": "Dê o avanço a que o treinador chama «quatro pés»; descreve a imagem dele, por isso mantenha o número e a unidade.", "say": "Dê-lhe quatro pés."}, {"en": "Half a bird more.", "meaning": "Acrescente meia largura de prato à imagem do avanço.", "say": "Mais meio prato."}, {"en": "Double it.", "meaning": "Faça a imagem do avanço duas vezes maior do que da última vez.", "say": "O dobro."}, {"en": "Same lead, just keep it moving.", "meaning": "O avanço estava certo; a falha veio de parar a arma.", "say": "O mesmo avanço, só não pare a arma."}, {"en": "You were at two o'clock — a touch low and more in front.", "meaning": "A chumbada ficou acima e à direita do prato no mostrador do relógio; atire ligeiramente mais baixo e dê um pouco mais de avanço.", "say": "Esteve às duas horas — um pouco mais baixo e mais à frente."}, {"en": "A barrel's width in front.", "meaning": "Mantenha à frente do prato uma distância da largura do cano, vista na boca do cano.", "say": "A largura de um cano à frente."}], "quiz": [{"q": "O treinador diz «Give it four foot» a um atirador que pensa em metros. O que diz?", "options": ["«Dê-lhe 1,22 metros»", "«Dê-lhe cerca de um metro»", "«Dê-lhe quatro pés»", "«Dê-lhe quatro metros»"], "answer": 2, "why": "Um número de avanço é a imagem do treinador; convertê-lo a meio de uma instrução acrescenta uma falsa precisão ou erros, e «quatro metros» muda completamente o sentido. Se o atirador perguntar, explique por alto entre pratos."}, {"q": "O que significa «half a bird»?", "options": ["Metade da largura de um prato", "Um prato partido", "Uma ave pequena a voar perto da máquina", "Metade da série"], "answer": 0, "why": "No tiro aos pratos, «bird» significa o prato, por isso o treinador pede um avanço de meia largura de prato."}, {"q": "O treinador diz «Same lead, keep it moving». Porque tem «same lead» de ser traduzido?", "options": ["É uma voz usada pelo árbitro", "Senão o atirador pode acrescentar avanço e falhar", "É um cumprimento educado entre atiradores", "Muda a ordem dos pratos"], "answer": 1, "why": "Depois de uma falha, a maioria dos atiradores acrescenta avanço por iniciativa própria; «same lead» diz-lhes que a causa foi a arma parada, não o avanço."}]}]}, {"id": "faults", "icon": "search", "title": "Erros e como os treinadores os diagnosticam", "intro": "Quando um prato é falhado, o treinador dá nome à falha em uma ou duas palavras e depois à causa. Esta missão ensina as palavras para as falhas e os erros, o que cada uma quer realmente dizer, e como passar o diagnóstico do treinador ao atirador de forma rápida e exata.", "lessons": [{"id": "faults-behind-in-front", "minutes": 5, "title": "Atrás, à frente, por cima, por baixo, lascado", "body": ["Cada falha tem uma direção. Um treinador que observa por trás do atirador diz normalmente primeiro onde foi o chumbo em relação ao prato, e só depois porquê. Transmita-o de imediato: o atirador já se está a preparar para o prato seguinte.", "Behind (atrás) significa que o chumbo passou atrás de um prato em movimento: avanço insuficiente, ou uma arma que abrandou. É a falha mais comum nos transversais. In front (à frente) é o contrário: avanço a mais, muitas vezes depois de o atirador ter corrigido em excesso. Muitos treinadores gostam de uma falha à frente: mostra que a arma continuou a mexer.", "Over (também «high», «over the top»: por cima, alto) e under («low»: por baixo, baixo) descrevem a falha vertical. Por cima é comum nos pratos descendentes, nos coelhos e nos pratos de entrada, e está muitas vezes ligada à cabeça a sair da coronha. Por baixo é típico nos pratos ascendentes que ainda estão a subir no momento do disparo.", "Chipped (lascado) significa que só se soltou um pequeno pedaço. Para o treinador é meio elogio, meia correção: o prato estava no limite da chumbada. Para o árbitro é acerto, desde que o pedaço seja visível. A armadilha é o pó: segundo as regras, um prato que só larga pó ou fumo, sem pedaço visível, é perdido. No entanto, «smoked it» na gíria dos treinadores é um acerto perfeito e centrado, e «dusted it» ouve-se nos dois sentidos, por isso pergunte quando não tiver a certeza.", "Mantenha a ordem do treinador: direção, causa, correção. Se o treinador disser «behind, you stopped» (atrás, parou), a causa é mais importante: um atirador que ouça apenas «atrás» vai acrescentar avanço, o que não cura uma arma parada."], "key_points": ["Transmita primeiro a direção: atrás, à frente, por cima, por baixo.", "Atrás = avanço insuficiente ou arma a abrandar; à frente = avanço a mais.", "Uma lasca visível é acerto para o árbitro; só pó ou fumo é perdido.", "«Smoked it» é um elogio do treinador, não o «fumo» das regras: nunca os confunda.", "Mantenha a ordem do treinador: direção, causa, correção."], "terms": ["lead", "crosser", "dropping-target", "visible-piece", "one", "zero", "miss-behind", "miss-in-front", "miss-over", "miss-under", "chip", "smoke-ball"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}], "coach_says": [{"en": "Behind, give it more.", "meaning": "O chumbo passou atrás do prato; aumente o avanço.", "say": "Atrás, dê-lhe mais."}, {"en": "Just over the top, it was already dropping.", "meaning": "O chumbo foi por cima porque o prato estava a cair; atire mais baixo e à frente.", "say": "Mesmo por cima, ele já estava a cair."}, {"en": "In front this time, good, now a touch less.", "meaning": "Avanço a mais, mas a arma estava a mexer; reduza ligeiramente o avanço.", "say": "Desta vez à frente, bem, agora um pouco menos."}, {"en": "You just chipped it, a little more in front.", "meaning": "Acertou no limite da chumbada; um pouco mais de avanço centra-o.", "say": "Só o lascou, um pouco mais à frente."}, {"en": "Smoked it! Same again.", "meaning": "Um acerto perfeito e centrado (gíria, não o «fumo» das regras); repita exatamente.", "say": "Pulverizou-o! Outra vez igual."}, {"en": "Behind, but you stopped, so don't just add lead.", "meaning": "A causa é uma arma parada; só acrescentar avanço não ajuda.", "say": "Atrás, mas parou a arma, por isso não acrescente só avanço."}], "quiz": [{"q": "O treinador grita: «Behind, you stopped!» Qual é a parte mais importante a traduzir?", "options": ["A causa: a arma parou", "Só a direção «atrás»", "Nada: o atirador viu a falha", "Um pedido para acrescentar muito mais avanço"], "answer": 0, "why": "Acrescentar avanço não cura uma arma parada; é a causa que o atirador tem de corrigir."}, {"q": "Solta-se do prato um pedaço pequeno, mas bem visível. O treinador diz «just chipped it». Como pontua o árbitro?", "options": ["Perdido, porque a maior parte do prato continuou a voar", "NULO", "Acerto (BOM)", "Acerto só se o treinador concordar"], "answer": 2, "why": "Pelo menos um pedaço visível faz do prato um acerto, tanto no Sporting™ como no Compak® Sporting; o árbitro decide sozinho."}, {"q": "Depois de um acerto o treinador grita «Smoked it!». O que quer dizer?", "options": ["Só saiu pó, por isso é perdido", "Um acerto perfeito e centrado", "Era um prato flash", "O atirador deve mudar de cartuchos"], "answer": 1, "why": "Na gíria dos treinadores, «smoked it» é um elogio a um prato desfeito em pó; nas regras, pó ou fumo sem pedaço visível é falha."}]}, {"id": "faults-head-lift-stopping", "minutes": 5, "title": "Levantar a cabeça, parar, ir à boleia, espetar", "body": ["Depois da direção, o treinador nomeia a causa. Há quatro causas que aparecem em todos os dias de treino, cada uma com a sua palavra curta. Aprenda-as aos pares: o erro e a correção.", "Levantar a cabeça (head lift): a face sai da coronha no momento do tiro ou pouco antes, muitas vezes porque o atirador quer ver o prato partir-se. O olho é a mira traseira, por isso levantá-lo muda a imagem, e o chumbo vai normalmente por cima. Correção: «head down» (cabeça em baixo), «cheek on the stock» (face na coronha), «stay in the gun» (fique na arma).", "Parar a arma (stopping the gun; em português também «parar a mão»): as bocas dos canos param no momento do tiro, normalmente porque o atirador verifica o avanço no cano. O chumbo vai para trás. Uma versão mais ligeira é o «checking»: o movimento hesita durante uma fração de segundo. Correção: «keep the gun moving» (não pare a arma), «follow through» (acompanhe), «finish the shot» (termine o tiro).", "Ir à boleia do prato (riding the target): seguir o prato tempo demais antes de disparar, de modo que ele abranda, cai ou se desvia e o atirador perde a linha. Correção: «take it earlier» (atire-lhe mais cedo), «commit to it» (decida-se). Espetar (poking; também «aiming», «measuring»: fazer pontaria, medir): apontar a espingarda devagar como uma carabina, com os olhos no ponto de mira em vez de no prato. É típico quando o ponto de tiro está demasiado perto, ou num teal no ponto mais alto. Correção: «eyes on the clay» (olhos no prato), «let the gun go» (deixe a arma ir).", "Os treinadores nomeiam muitas vezes a causa antes de o atirador ter sequer baixado a arma. Traduza-a no mesmo fôlego e com o mesmo verbo: «you stopped» (parou) não é «you missed» (falhou). Uma palavra como «aiming» é quase sempre uma crítica, por isso nunca a transforme num conselho como «faça melhor pontaria»."], "key_points": ["Levantar a cabeça: chumbo normalmente por cima; correção: cabeça em baixo, ficar na arma.", "Parar ou hesitar: chumbo atrás; correção: não parar a arma, acompanhar.", "Ir à boleia: o prato abranda ou cai; correção: atirar mais cedo, decidir-se.", "Espetar ou fazer pontaria: apontar devagar, como com uma carabina; correção: olhos no prato.", "Traduza a causa de imediato, com o próprio verbo do treinador."], "terms": ["head-lift", "stopping-the-gun", "follow-through", "break-point", "teal", "checking", "riding-the-target", "poking"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "The Field — Improve your game and clay shooting: 20 top tips", "url": "https://www.thefield.co.uk/shooting/improve-your-game-and-clay-shooting-20-top-tips-45462"}, {"title": "Clay Target Nation — 5 major shooting mistakes", "url": "https://www.claytargetnation-digital.com/articles/5-major-shooting-mistakes"}], "sim": null, "rule_refs": [], "coach_says": [{"en": "You lifted your head, that's why it went over.", "meaning": "A face saiu da coronha, por isso o chumbo passou por cima do prato.", "say": "Levantou a cabeça, foi por isso que passou por cima."}, {"en": "Keep the gun moving, you stopped on it.", "meaning": "O movimento parou no momento do tiro; continue a mexer, atravessando o prato e depois dele.", "say": "Não pare a arma, parou em cima dele."}, {"en": "You checked just before the shot, commit to it.", "meaning": "Uma breve hesitação antes de disparar; decida e dispare sem abrandar.", "say": "Hesitou mesmo antes do tiro, decida-se."}, {"en": "Stop aiming, look at the bird and let the gun go.", "meaning": "Crítica: o atirador está a apontar como com uma carabina; concentre-se no prato e mova a arma livremente.", "say": "Pare de fazer pontaria, olhe para o prato e deixe a arma ir."}, {"en": "You rode it too long, take it earlier.", "meaning": "O atirador seguiu o prato tempo demais; parta-o mais cedo.", "say": "Foi à boleia dele tempo demais, atire-lhe mais cedo."}, {"en": "Stay in the gun.", "meaning": "Mantenha a face na coronha até depois do tiro.", "say": "Fique na arma."}], "quiz": [{"q": "O treinador diz «You lifted your head». Para onde foi muito provavelmente o chumbo?", "options": ["Atrás", "Por cima", "Por baixo", "À frente"], "answer": 1, "why": "O olho é a mira traseira: quando a cabeça se levanta, o chumbo vai normalmente por cima."}, {"q": "O treinador grita «Stop aiming!». O que quer?", "options": ["Não aponte como com uma carabina: olhe para o prato e mova a arma", "Faça pontaria com mais precisão", "Cessar fogo imediatamente", "Baixe a arma"], "answer": 0, "why": "Na boca de um treinador, «aiming» é um erro (espetar); a correção são os olhos no prato e um movimento livre."}, {"q": "«You rode it too long» significa…", "options": ["O atirador disparou cedo demais", "A máquina estava demasiado lenta", "O atirador começou demasiado atrás", "O atirador seguiu o prato tempo demais antes de disparar"], "answer": 3, "why": "Ir à boleia do prato é segui-lo tempo demais, de modo que ele abranda ou cai e a linha perde-se."}]}, {"id": "faults-mount-errors", "minutes": 5, "title": "Erros ao pôr a arma à cara: tarde, cara à arma, arma inclinada", "body": ["Muitas falhas começam antes do movimento, ao pôr a arma à cara: o gesto que leva a arma à face e ao ombro. As palavras do treinador para isto são curtas e físicas.", "Montagem tardia (late mount): a arma chega ao ombro depois do momento em que o tiro devia ter saído, por isso o atirador apressa-se ou dispara antes de a face estar assente. O erro contrário é uma montagem terminada cedo demais, depois da qual a arma fica à espera, parada e pesada. Correção: «move, mount, shoot» (mover, montar, disparar), em que as bocas dos canos arrancam com o prato e a montagem termina quando sai o tiro.", "Cara à arma (face to the gun): em vez de subir a coronha até à cara, o atirador baixa a cabeça ao encontro dela. O olho acaba num sítio diferente de cada vez, e o recuo bate na face. Os treinadores dizem: «bring the gun to your face, not your face to the gun» (a arma vem à cara, não a cara à arma). Uma coronha que assenta no braço em vez de na concavidade do ombro também magoa.", "Arma inclinada (canting): a arma está inclinada para o lado no momento do tiro, e o chumbo desvia-se da linha. Vem muitas vezes com um ombro descaído. Correção: «keep the gun level» (mantenha a arma direita), «turn from the hips» (rode a partir da anca).", "Nas competições de Parcours de Chasse – Sporting™ da FITASC a arma não pode ser posta à cara antes de o prato aparecer, por isso «pre-mount this one» (este com a arma já à cara) é apenas um exercício de treino. Pôr a arma à cara cedo numa competição de Sporting™ vale uma advertência e um cartão amarelo. No Compak® Sporting a arma pode já estar no ombro no momento do pedido. Traduza o exercício como exercício e não acrescente nada da sua parte."], "key_points": ["Montagem tardia: tiro apressado; correção: mover, montar, disparar.", "Cara à arma: o olho muda de sítio e o recuo magoa; leve a arma à cara.", "Arma inclinada: o chumbo desvia-se da linha; mantenha a arma direita, rode a partir da anca.", "A arma já à cara é um exercício: não permitido antes de o prato aparecer numa competição de Sporting™, permitido no pedido no Compak® Sporting."], "terms": ["gun-mount", "ready-position", "recoil", "comb", "gun-fit", "dry-mounting", "late-mount", "canting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Bring the gun to your face, not your face to the gun.", "meaning": "Suba a coronha até à face; não baixe a cabeça até à coronha.", "say": "A arma vem à cara, não a cara à arma."}, {"en": "Move, mount, shoot, all in one.", "meaning": "Comece a mexer com o prato e termine a montagem ao disparar, num só movimento fluido.", "say": "Mover, montar, disparar, tudo num só."}, {"en": "You canted the gun, keep it level.", "meaning": "A arma estava inclinada para o lado no momento do tiro.", "say": "Inclinou a arma, mantenha-a direita."}, {"en": "Mount on the line.", "meaning": "A arma deve subir já na trajetória do prato.", "say": "Monte na linha."}, {"en": "Pre-mount this one, just for practice.", "meaning": "Exercício de treino com a arma já no ombro; não permitido numa competição de Sporting™.", "say": "Este com a arma já à cara, só para treinar."}], "quiz": [{"q": "No treino, um treinador diz a um atirador que se prepara para uma competição de Sporting™ da FITASC: «Pre-mount this one.» O que é verdade?", "options": ["É permitido em todas as competições da FITASC", "O intérprete deve recusar-se a traduzir", "É um exercício de treino; numa competição de Sporting™ a arma não pode ser posta à cara antes de o prato aparecer", "Significa pôr a arma à cara depois do tiro"], "answer": 2, "why": "O Sporting™ exige a posição de partida com arma em baixo até o prato aparecer; pôr a arma à cara antes, em competição, vale uma advertência com cartão amarelo."}, {"q": "«You canted the gun» significa…", "options": ["A arma estava inclinada para o lado no momento do tiro", "A arma foi posta à cara tarde demais", "A arma parou", "A patilha de segurança estava engatada"], "answer": 0, "why": "Canting é uma inclinação lateral da arma, que desvia o chumbo da linha."}, {"q": "Que instrução corrige a «cara à arma»?", "options": ["Carregue mais a cabeça para baixo", "Leve a arma à cara", "Feche um olho", "Segure a arma mais abaixo no braço"], "answer": 1, "why": "A coronha deve subir até à cara, para que o olho fique sempre no mesmo sítio."}]}, {"id": "faults-pairs-transition", "minutes": 5, "title": "Doubles: o segundo prato", "body": ["Num double, muitos atiradores partem o primeiro prato e falham o segundo. O treinador fala então da transição (transition), a passagem do primeiro prato para o segundo, e da recuperação (recovery), retomar o controlo da arma e da cabeça depois do primeiro tiro.", "A regra de ouro é «eyes first, then the gun» (primeiro os olhos, depois a arma). Os olhos deixam o primeiro prato partido e encontram o segundo; a arma segue. Um atirador que fica a ver o primeiro prato partir-se, ou que move a arma antes de encontrar o segundo, perde tempo. Os treinadores dizem «eyes to the second» (olhos no segundo) ou simplesmente apontam.", "Recuperação: o recuo levanta as bocas dos canos e por vezes a cabeça. «Let the gun recover, then go» (deixe a arma recuperar e depois vá) significa: face de novo assente e arma de novo na linha antes de ir ao segundo prato. Uma boa posição, com o peso à frente, torna a recuperação mais rápida.", "Planeamento: ao ler o double, o treinador decide a que prato atirar primeiro e onde o partir, para que o segundo seja fácil de apanhar. Frases típicas: «take the dropping one first» (primeiro o que está a cair), «break the first early» (parta o primeiro cedo), «stick to the plan» (cumpra o plano). Um atirador que muda a ordem no posto «went for the wrong one» (foi ao prato errado).", "Aqui as regras contam. No Parcours de Chasse – Sporting™ a posição da arma é livre entre os dois pratos de qualquer double, e o atirador tem dois cartuchos para um double, que podem ir ambos para o mesmo prato. No Compak® Sporting só é permitido um cartucho por prato num double. Não explique as penalizações por iniciativa própria: traduza o treinador e deixe as questões de regras para o árbitro."], "key_points": ["Primeiro os olhos, depois a arma.", "Recuperação: face de novo na coronha e arma na linha antes do segundo prato.", "O treinador planeia a ordem e os pontos de tiro de um double ao lê-lo.", "Sporting™: posição da arma livre entre os pratos, e ambos os cartuchos podem ir para um só prato; Compak® Sporting: um cartucho por prato."], "terms": ["double", "double-on-report", "simultaneous-double", "rafale-double", "recoil", "stance", "dropping-target", "transition", "recovery"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Eyes first to the second bird, then the gun.", "meaning": "Encontre o segundo prato com os olhos antes de mover a arma.", "say": "Primeiro os olhos no segundo prato, depois a arma."}, {"en": "Let the gun recover, then go to the second.", "meaning": "Depois do recuo, estabilize a arma e a face antes do segundo tiro.", "say": "Deixe a arma recuperar e depois vá ao segundo."}, {"en": "Take the dropping one first.", "meaning": "Atire primeiro ao prato que vai desaparecer ou cair mais cedo.", "say": "Primeiro o que está a cair."}, {"en": "Don't watch the first one break.", "meaning": "Passe imediatamente os olhos para o segundo prato.", "say": "Não fique a ver o primeiro partir."}, {"en": "You went for the wrong one first, stick to the plan.", "meaning": "O atirador mudou a ordem planeada; é uma observação técnica, não uma infração.", "say": "Foi primeiro ao prato errado, cumpra o plano."}], "quiz": [{"q": "O que significa «eyes first, then the gun» num double?", "options": ["Fechar os olhos depois do primeiro tiro", "Olhar para o cano antes do segundo tiro", "Pôr a arma à cara antes de pedir o double", "Encontrar o segundo prato com os olhos antes de levar a arma até ele"], "answer": 3, "why": "Numa boa transição, os olhos conduzem e a arma segue."}, {"q": "Num double de Compak® Sporting, o atirador falha o primeiro prato e quer disparar-lhe também o segundo cartucho. É permitido?", "options": ["Sim, como no Sporting™", "Sim, mas só num double simultâneo", "Não: num double de Compak® Sporting só é permitido um cartucho por prato", "Só com autorização do árbitro"], "answer": 2, "why": "O Compak® Sporting proíbe disparar duas vezes ao primeiro prato de um double; o Sporting™ permite os dois cartuchos ao mesmo prato."}, {"q": "Num double de Sporting™, pode o atirador baixar a arma entre o primeiro e o segundo prato?", "options": ["Sim, a posição da arma é livre entre os dois pratos", "Não, a arma tem de ficar à cara", "Só num double ao tiro", "Só se o árbitro o permitir"], "answer": 0, "why": "A posição livre aplica-se entre os pratos de qualquer double, mas não antes do primeiro."}]}, {"id": "faults-reading-the-coach", "minutes": 5, "title": "Ler o treinador: ordens curtas e sinais", "body": ["No posto, o treinador fala aos bocados: «Behind.» «Head.» «More.» «Again.» (Atrás. Cabeça. Mais. Outra vez.) Há apenas alguns segundos entre pratos, por isso a brevidade é deliberada. A sua tradução deve ser igualmente curta; uma frase longa chega depois do pedido seguinte.", "Muitos treinadores perguntam antes de dizer: «Where did it go?» (onde foi?) ou «What did you see?» (o que viu?). É uma pergunta pedagógica, não um teste ao intérprete. Traduza a pergunta, deixe o atirador responder e traduza a resposta de volta com exatidão, mesmo que pareça errada. O treinador precisa de saber o que o atirador percebeu.", "Os sinais com as mãos transmitem muito. Os mais comuns: mãos a afastarem-se ou a aproximarem-se para mais ou menos avanço, uma mão espalmada a descer para «mais baixo», um toque na face para «cabeça em baixo», um dedo a desenhar a linha do prato, um polegar para cima para «outra vez igual». Os sinais variam de treinador para treinador, por isso combine-os antes da sessão, e não traduza um gesto que o atirador já viu.", "Algumas palavras são puro ritmo e encorajamento: «commit» (decida-se), «trust it» (confie), «smooth» (suave), «good, same again» (bem, outra vez igual). Mantenha o tom. «Bad luck» (pouca sorte) depois de uma falha é gentileza, não um comentário sobre o árbitro.", "Em competição, o treino é proibido: o árbitro dá ao atirador um cartão amarelo e manda o treinador sair da zona de tiro. As regras não dizem se um intérprete pode transmitir os conselhos de um treinador durante uma competição: é uma questão em aberto para a FITASC. A prática segura: em competição, interprete apenas para o árbitro, o júri e o organizador."], "key_points": ["Os treinadores falam aos bocados; traduza com a mesma brevidade.", "«Where did it go?» é uma pergunta pedagógica: traduza a resposta do atirador com exatidão.", "Combine os sinais com as mãos antes da sessão.", "Nada de treino em competição; interprete apenas para o árbitro, o júri e o organizador."], "terms": ["coach", "referee", "jury", "yellow-card", "hand-signal"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Where did it go?", "meaning": "O treinador pergunta onde o atirador acha que o chumbo foi; uma pergunta pedagógica.", "say": "Onde é que foi?"}, {"en": "What did you see?", "meaning": "Descreva a imagem no momento do tiro.", "say": "O que é que viu?"}, {"en": "More.", "meaning": "No contexto, quase sempre «mais avanço».", "say": "Mais."}, {"en": "Good, same again.", "meaning": "Repita exatamente o que acabou de fazer.", "say": "Bem, outra vez igual."}, {"en": "Trust it, commit to it.", "meaning": "Deixe de hesitar; decida e dispare.", "say": "Confie, decida-se."}, {"en": "Bad luck.", "meaning": "Solidariedade depois de uma falha; não é uma queixa sobre o árbitro.", "say": "Pouca sorte."}], "quiz": [{"q": "O treinador pergunta ao atirador «Where did it go?». O que deve fazer o intérprete?", "options": ["Responder pelo atirador", "Traduzir a pergunta e depois a resposta do atirador com exatidão", "Explicar a falha por palavras suas", "Não dizer nada: é uma pergunta retórica"], "answer": 1, "why": "O treinador quer a perceção do próprio atirador, por isso a resposta tem de lhe chegar sem alterações."}, {"q": "Durante uma competição, o treinador do atirador pede-lhe que transmita: «Give the next one more lead.» Qual é a prática segura?", "options": ["Transmitir em voz baixa", "Transmitir só entre postos", "Não transmitir conselhos de treino em competição; interpretar apenas para o árbitro, o júri e o organizador", "Perguntar primeiro aos outros atiradores"], "answer": 2, "why": "O treino em competição é proibido, e as regras não dizem se um intérprete o pode transmitir; ficar de fora protege o atirador."}, {"q": "O que acontece segundo as regras se o árbitro considerar que um atirador está a receber instruções de treino?", "options": ["Cartão amarelo para o atirador; o treinador é mandado sair da zona de tiro", "Nada: o treino é permitido", "O prato repete-se", "Toda a esquadra é desclassificada"], "answer": 0, "why": "Os dois regulamentos dão ao atirador um cartão amarelo, com penalizações mais pesadas em caso de repetição, e afastam o treinador."}]}]}, {"id": "sporting", "icon": "flag", "title": "Regras do Parcours de Chasse – Sporting™", "intro": "O Parcours de Chasse – Sporting™ é a disciplina da FITASC que imita a caça em terreno natural. Esta missão percorre as suas regras tal como um árbitro as aplica: séries e postos, a partida com arma em baixo, simples e doubles, a mostra dos pratos, as deficiências e os limites de tempo. Tudo aqui é uma paráfrase; as referências às regras abrem o guia de regras da ClayArena.", "lessons": [{"id": "sporting-rounds-stands", "minutes": 5, "title": "Séries, postos e ordem de tiro", "body": ["Uma competição de Parcours de Chasse – Sporting™ conta-se em séries de 25 pratos. Uma prova internacional tem 200 pratos, ou seja, oito séries; cada série atira-se num percurso (um conjunto de postos de tiro) ou numa linha.", "Cada percurso dá 15 simples e 5 doubles. O número de postos e de máquinas depende do sistema: o sistema antigo usa 5 máquinas para 3 postos, enquanto as linhas do sistema novo têm 4 ou 5 postos com 3 ou 4 máquinas cada. As máquinas têm as letras A, B, C, D, da esquerda para a direita, vistas do posto. O menu de tiro à frente do posto indica-as pela ordem de tiro, juntamente com os pratos especiais: 90, 70 ou 60 mm, batida, coelho.", "O posto em si é um quadrado de 1 m ou um círculo com 1 m de diâmetro. Cada trajetória tem uma classe de dificuldade: A (um atirador médio parte mais de 80%), B (60 a 80%) ou C (40 a 60%).", "Os atiradores fazem o percurso em esquadras de até seis, formadas por sorteio. Em cada posto, todos atiram primeiro os simples e depois os doubles, e a ordem de tiro roda em cada posto e novamente para os doubles. Os outros esperam perto, sem distrair quem está a atirar.", "O árbitro, ou uma pessoa sob a sua supervisão, preenche a folha de marcação, registando cada prato por baixo da letra da sua máquina. Ao sair de cada posto, cada atirador verifica o seu resultado; um desacordo tem de ser apresentado de imediato ao árbitro, e a decisão do árbitro é definitiva."], "key_points": ["Série = 25 pratos num percurso: 15 simples + 5 doubles; prova internacional = 200 pratos.", "Máquinas A, B, C, D da esquerda para a direita, vistas do posto; o menu dá a ordem e os pratos especiais.", "Esquadras de até seis; primeiro os simples, depois os doubles; a ordem roda.", "Verifique o resultado ao sair de cada posto; o árbitro decide."], "terms": ["round", "layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "squad", "rotation", "score-sheet", "referee", "difficulty-class"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}], "coach_says": [{"en": "Singles first, then doubles.", "meaning": "A ordem normal em todos os postos.", "say": "Primeiro os simples, depois os doubles."}, {"en": "Read the menu: the traps go A, B, C.", "meaning": "O painel do menu indica as máquinas pela ordem em que vão ser atiradas.", "say": "Leia o menu: as máquinas são A, B, C."}, {"en": "Next shooter.", "meaning": "O árbitro chama a pessoa seguinte para o posto.", "say": "Próximo atirador."}, {"en": "Check your score before you leave the stand.", "meaning": "Qualquer desacordo tem de ser apresentado agora, não depois.", "say": "Verifique o seu resultado antes de sair do posto."}], "quiz": [{"q": "Quantos pratos dá um percurso de Sporting™ e como se dividem?", "options": ["20: 10 simples e 5 doubles", "25: todos simples", "25: 15 simples e 5 doubles", "50: 25 simples e 25 doubles"], "answer": 2, "why": "Todos os tipos de percurso dão 15 simples mais 5 doubles, ou seja, 25 pratos."}, {"q": "Por que ordem atira uma esquadra num posto?", "options": ["Primeiro os doubles, depois os simples", "Todos atiram primeiro os simples e depois os doubles, e a ordem roda", "Cada atirador atira o percurso todo de uma vez", "Os atiradores escolhem livremente"], "answer": 1, "why": "Primeiro vêm os simples, depois os doubles, de forma rotativa, salvo decisão em contrário do júri."}, {"q": "Ao sair do posto, um atirador vê que um acerto foi marcado como falha. O que deve fazer?", "options": ["Esperar pelo fim da série e recorrer ao júri", "Corrigir ele próprio a folha", "Pedir à esquadra que vote", "Dizê-lo de imediato ao árbitro; o árbitro decide"], "answer": 3, "why": "Os resultados verificam-se ao sair de cada posto; só o árbitro decide, e depois não há recurso."}]}, {"id": "sporting-gun-position", "minutes": 5, "title": "A partida com arma em baixo", "body": ["A regra mais visível do Parcours de Chasse – Sporting™ é a partida com arma em baixo. Antes de pedir o prato, o atirador está com os dois pés dentro do posto, o talão da coronha a tocar no corpo e o ponto superior traseiro da coronha abaixo de uma linha no colete. Esta posição de partida mantém-se até o prato ter sido lançado e estar à vista.", "A linha é marcada no colete ou no casaco 25 cm abaixo do eixo dos ombros, paralela a ele, numa cor que contraste com o colete, para que o árbitro a possa ver. A regra abrange todos os tipos de coronha, incluindo as de crista ajustável.", "A arma só pode subir quando o prato aparece. Todos os pratos, coelhos incluídos, se atiram com a arma no ombro; não é permitido disparar à anca. Entre o primeiro e o segundo prato de qualquer double, a posição da arma é livre, mas antes do primeiro prato aplica-se a posição de partida.", "Penalizações: na primeira vez que um atirador pede o prato numa posição incorreta ou põe a arma à cara antes de o prato aparecer, o árbitro dá uma advertência verbal com cartão amarelo. Qualquer nova infração no mesmo percurso dá cartão vermelho, e o prato conta zero num simples, zero e NULO num double ao tiro, zero e zero num double simultâneo ou rafale.", "Pôr a arma à cara e movê-la ao longo da linha imaginada antes de pedir o prato (simulacro de tiro) também é proibido: primeiro uma advertência, depois um zero. Se um treinador fizer exercícios de partida com a arma à cara antes de uma prova da FITASC, traduza também a palavra «exercício»."], "key_points": ["Antes do pedido: os dois pés no posto, coronha a tocar no corpo, parte de cima da coronha abaixo da linha do colete.", "A linha do colete fica 25 cm abaixo do eixo dos ombros, numa cor contrastante.", "Pôr a arma à cara só quando o prato aparece; atirar sempre com a arma no ombro; posição livre entre os pratos de um double.", "Primeira infração: advertência + cartão amarelo; a seguinte no mesmo percurso: cartão vermelho e o prato pontuado."], "terms": ["ready-position", "gun-mount", "shooting-stand", "shooting-vest", "adjustable-comb", "mock-shooting", "yellow-card", "red-card", "jacket-line"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}], "coach_says": [{"en": "Gun down, please.", "meaning": "Árbitro: ponha a coronha abaixo da linha do colete antes de pedir o prato.", "say": "Arma em baixo, por favor."}, {"en": "Your stock was above the line. This is a warning.", "meaning": "Primeira infração de posição da arma: advertência verbal com cartão amarelo.", "say": "A sua coronha estava acima da linha. Isto é uma advertência."}, {"en": "Don't mount before the target appears.", "meaning": "A arma só pode subir quando o prato estiver visível.", "say": "Não ponha a arma à cara antes de o prato aparecer."}, {"en": "Red card, zero.", "meaning": "Uma reincidência no mesmo percurso; o prato simples é perdido.", "say": "Cartão vermelho, zero."}], "quiz": [{"q": "Primeiro posto. Um atirador pede o prato com a arma já no ombro. É a sua primeira infração neste percurso. Qual é a decisão do árbitro?", "options": ["O prato conta zero", "Uma advertência verbal com cartão amarelo", "NULO e mais nada", "Expulsão"], "answer": 1, "why": "A primeira infração de posição da arma é uma advertência verbal acompanhada de cartão amarelo."}, {"q": "Mesmo percurso, dois postos depois: o mesmo atirador pede um simples com a coronha acima da linha do colete. Decisão?", "options": ["Outro cartão amarelo", "NULO", "Cartão vermelho, e o prato repete-se", "Cartão vermelho, e o simples conta zero"], "answer": 3, "why": "Depois da advertência, uma nova infração no mesmo percurso é cartão vermelho: zero num simples."}, {"q": "Double ao tiro. Depois de partir o primeiro prato, o atirador baixa ligeiramente a arma antes do segundo. Decisão?", "options": ["Permitido: a posição da arma é livre entre os dois pratos", "Cartão amarelo", "Zero no segundo prato", "NULO"], "answer": 0, "why": "A posição livre aplica-se entre os pratos de qualquer double; a posição de partida só é exigida antes do primeiro."}]}, {"id": "sporting-singles-doubles", "minutes": 5, "title": "Simples e doubles", "body": ["Um simples é um prato de uma máquina. No Parcours de Chasse – Sporting™ o atirador pode disparar-lhe dois cartuchos, por isso uma falha com o primeiro cano ainda pode ser salva com o segundo. Cada simples tem de deixar tempo para dois tiros.", "Um double são dois pratos, e o atirador só tem dois cartuchos para ele; ambos podem ir para o mesmo prato. Há três tipos. Ao tiro: o segundo prato sai 0 a 3 segundos depois do tiro ao primeiro, lançado por esse tiro. Simultâneo: os dois saem no mesmo instante, de uma ou de duas máquinas. Rafale: dois pratos da mesma máquina na mesma linha, o segundo tão depressa quanto a máquina recarrega. Nos doubles simultâneos e rafale os pratos podem ser atirados por qualquer ordem. Os doubles só usam pratos já apresentados como simples no mesmo posto.", "Decisões que o árbitro tem muitas vezes de tomar: se um só tiro partir os dois pratos de qualquer double, contam os dois, BOM e BOM. Se o atirador não disparar a um double rafale ou simultâneo sem motivo válido, é zero e zero.", "Num double ao tiro, um primeiro prato irregular significa que o double se repete; se o primeiro prato ou os seus pedaços partirem o segundo antes do segundo tiro, ou se o segundo for irregular, o double repete-se e mantém-se o primeiro resultado. Nos doubles simultâneos e rafale, um prato irregular significa repetição sem registo de resultado.", "Dica: transmita o resultado de um double como um par, pela ordem do árbitro."], "key_points": ["Simples: dois cartuchos permitidos.", "Double: dois cartuchos no total, ambos podem ir para um só prato; tipos: ao tiro, simultâneo, rafale.", "Um só tiro parte os dois pratos: BOM e BOM.", "Não disparar a um double simultâneo ou rafale sem motivo: zero e zero."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "trap", "trajectory", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch2-trajectories-ethics", "label": "2 · Hunting ethics and shooting distances"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-target-doubles", "label": "6 · Target No Bird in doubles"}], "coach_says": [{"en": "Report pair: the second comes on your shot.", "meaning": "Treinador: o segundo prato é lançado pelo tiro ao primeiro.", "say": "Double ao tiro: o segundo sai com o seu tiro."}, {"en": "On the rafale, take either one first.", "meaning": "No double rafale a ordem é livre.", "say": "No rafale, atire primeiro a qualquer um."}, {"en": "One and one.", "meaning": "Árbitro: os dois pratos do double são acertos.", "say": "Bom e bom."}, {"en": "No Bird, repeat the double.", "meaning": "Prato irregular; o double é lançado outra vez.", "say": "Nulo, repete o double."}], "quiz": [{"q": "Double simultâneo. Um só tiro parte os dois pratos. Qual é a decisão do árbitro?", "options": ["BOM e BOM", "BOM e NULO", "NULO, o double repete-se", "BOM e zero"], "answer": 0, "why": "No Sporting™, dois pratos partidos com um só tiro em qualquer double contam BOM e BOM (no Compak® Sporting é diferente)."}, {"q": "Double ao tiro. O atirador parte o primeiro prato, e um pedaço dele desfaz o segundo antes do segundo tiro. Decisão?", "options": ["BOM e BOM", "O double repete-se e mantém-se o primeiro resultado", "Zero no segundo prato", "BOM e zero"], "answer": 1, "why": "Quando o primeiro prato ou os seus pedaços partem o segundo antes do segundo tiro, o double repete-se e o primeiro resultado mantém-se."}, {"q": "Double rafale. Os dois pratos voam corretamente, mas o atirador baixa a arma e não dispara a nenhum, sem dar motivo válido. Decisão?", "options": ["NULO", "Zero e NULO", "Só um cartão amarelo", "Zero e zero"], "answer": 3, "why": "Um prato correto a que não se dispara sem motivo válido é perdido; num double rafale ou simultâneo isso significa zero e zero."}]}, {"id": "sporting-viewing", "minutes": 5, "title": "A mostra dos pratos", "body": ["Antes de uma esquadra atirar num posto, o árbitro manda mostrar os pratos. A mostra serve para ler os pratos: linha, velocidade, distância e o que o prato faz. Todas as trajetórias são mostradas ao primeiro atirador da esquadra, que tem de estar pronto no posto.", "O atirador que está no posto pode pedir ao árbitro que repita a mostra, até dois pratos por cada prato da sequência do menu.", "Os doubles ao tiro não são mostrados, porque o segundo prato só sai ao som do tiro. Os doubles simultâneos e rafale são mostrados ao primeiro atirador de cada esquadra e, a pedido, repetidos até dois doubles mostrados.", "Durante a mostra as armas estão abertas e descarregadas, como em todas as interrupções, e só voltam a ser fechadas quando o árbitro o permitir. Disparar ou fazer simulacro de tiro durante a mostra é proibido e penalizado como uma infração de posição da arma: primeiro uma advertência, depois um cartão vermelho.", "Se uma máquina avariar ou o tiro parar durante mais de dez minutos, o árbitro volta a mostrar os pratos desse posto. Antes da prova, ninguém pode treinar nos percursos da competição.", "No treino, a mostra é o momento preferido do treinador: «watch where it turns» (veja onde ele vira). Em competição, a mostra faz parte da prova, por isso a proibição de treino aplica-se também aqui: fique calado, a não ser que o árbitro ou o atirador precisem de uma tradução de procedimento."], "key_points": ["Todas as trajetórias são mostradas ao primeiro atirador, pronto no posto.", "Repetições a pedido: até duas por cada prato do menu.", "Os doubles ao tiro nunca são mostrados; os simultâneos e rafale são.", "Armas abertas durante a mostra; nada de disparos nem de simulacro de tiro.", "Interrupção de mais de 10 minutos: os pratos voltam a ser mostrados."], "terms": ["target-presentation", "target-menu", "double-on-report", "simultaneous-double", "rafale-double", "mock-shooting", "practice", "red-card"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch16-long-interruption", "label": "16 · Interruption over 10 minutes"}, {"book": "sporting", "id": "ch15-no-practice", "label": "15 · No practice on competition layouts"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}], "coach_says": [{"en": "Show me the targets, please.", "meaning": "Atirador para o árbitro: comece a mostra.", "say": "Mostre-me os pratos, por favor."}, {"en": "Again, please, B only.", "meaning": "Pedido para repetir um prato do menu.", "say": "Outra vez, por favor, só o B."}, {"en": "Guns open during the show.", "meaning": "Árbitro: abram e descarreguem as armas até ele permitir fechá-las.", "say": "Armas abertas durante a mostra."}, {"en": "Watch where it turns.", "meaning": "Treinador no treino: repare no ponto em que o prato muda de direção ou de forma.", "say": "Veja onde ele vira."}], "quiz": [{"q": "Que doubles NÃO são mostrados na mostra?", "options": ["Simultâneos", "Rafale", "Ao tiro", "Nenhum: são todos mostrados"], "answer": 2, "why": "O segundo prato de um double ao tiro só sai com o tiro, por isso estes doubles não são mostrados."}, {"q": "Quantas repetições de um prato pode pedir o atirador que está no posto?", "options": ["Nenhuma", "Até duas por cada prato do menu", "Tantas quantas precisar", "Uma por posto"], "answer": 1, "why": "A pedido, o árbitro repete a mostra, até dois pratos por cada prato da sequência do menu."}, {"q": "Durante a mostra, um atirador fecha a arma e move-a ao longo da linha de um prato. O que se aplica?", "options": ["É proibido: aplicam-se as penalizações de posição da arma, uma advertência e depois um cartão vermelho", "Nada: a mostra é livre", "O prato volta a ser mostrado", "Só o treinador é advertido"], "answer": 0, "why": "As armas ficam abertas durante a mostra, e disparar ou simular disparos é penalizado segundo as regras da advertência e do cartão vermelho."}]}, {"id": "sporting-malfunctions", "minutes": 5, "title": "Deficiências da arma e do cartucho", "body": ["Uma deficiência (malfunction) é uma falha da arma ou do cartucho: uma falha de percussão, um segundo cano que não dispara, ou os dois canos a dispararem ao mesmo tempo (double discharge). No Parcours de Chasse – Sporting™ os incidentes contam-se por série de 25 pratos.", "Primeiro, o que o atirador tem de fazer: ficar no lugar, com a arma apontada para a zona de tiro, sem a abrir nem tocar na patilha de segurança até o árbitro a ter examinado. Abrir a arma ou tocar na segurança antes disso significa que o prato ou os pratos contam zero.", "O primeiro incidente numa série é NULO com advertência, e o prato repete-se. A partir do segundo incidente na mesma série, o prato deixa de se repetir e conta zero.", "Pormenores de um primeiro incidente: se o primeiro tiro falhar, um simples ou qualquer double repete-se, mas se o atirador ainda disparar o segundo tiro, esse resultado mantém-se. Se o segundo tiro falhar num simples, o prato repete-se e então só pode ser partido com o segundo tiro; um prato partido com o primeiro tiro conta zero. Num double ao tiro mantém-se o primeiro resultado e o double repete-se. Um disparo simultâneo dos dois canos num simples, ou no primeiro prato de qualquer double, é NULO sem nada registado.", "Se a arma for reparada antes de a esquadra terminar o posto, o atirador pode atirar em último lugar, com autorização do árbitro; caso contrário, pode continuar de imediato com outra arma, ou terminar noutra esquadra com a aprovação do júri. A arma, o choke ou os canos não podem ser trocados depois de ele estar no posto."], "key_points": ["Depois de uma falha: ficar no lugar, arma apontada para a zona de tiro, não a abrir nem tocar na segurança.", "Primeiro incidente numa série: NULO + advertência, o prato repete-se.", "Segundo incidente na mesma série: zero, sem repetição.", "Falha do segundo tiro num simples: na repetição só conta um prato partido com o segundo tiro."], "terms": ["malfunction", "double-discharge", "no-bird", "zero", "safety-catch", "round", "choke", "barrel"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}, {"book": "sporting", "id": "ch6-malfunction-first-shot", "label": "6 · Malfunction on the first shot"}, {"book": "sporting", "id": "ch6-malfunction-second-shot", "label": "6 · Malfunction on the second shot"}, {"book": "sporting", "id": "ch6-second-malfunction", "label": "6 · Second malfunction in the same round"}, {"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch7-double-discharge", "label": "7 · Double discharge due to a gun fault"}, {"book": "sporting", "id": "ch7-malfunction-procedure", "label": "7 · What happens after a gun malfunction"}, {"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}], "coach_says": [{"en": "Stay there, don't open the gun.", "meaning": "Árbitro: espere pela inspeção; abrir antes custa o prato.", "say": "Fique aí, não abra a arma."}, {"en": "Let me see the gun.", "meaning": "O árbitro examina a arma ou o cartucho.", "say": "Deixe-me ver a arma."}, {"en": "Malfunction. No Bird, first warning.", "meaning": "Primeiro incidente na série: o prato repete-se.", "say": "Deficiência. Nulo, primeira advertência."}, {"en": "Second malfunction this round. Zero.", "meaning": "Desta vez não há repetição; o prato é perdido.", "say": "Segunda deficiência nesta série. Zero."}], "quiz": [{"q": "Primeiro problema com a arma na série: num simples, o primeiro cartucho falha. O atirador espera pelo árbitro, com a arma apontada para a zona de tiro. Decisão?", "options": ["Zero", "NULO com advertência; o prato repete-se", "BOM", "Cartão amarelo e zero"], "answer": 1, "why": "O primeiro incidente de arma ou de munição numa série é NULO com advertência, e o simples repete-se."}, {"q": "O cartucho falha e o atirador, irritado, abre a arma para ver o fulminante antes de o árbitro chegar. Decisão?", "options": ["NULO", "O prato repete-se depois de uma advertência", "Zero", "Cartão vermelho, e o prato repete-se"], "answer": 2, "why": "Abrir a arma ou tocar na segurança antes da verificação do árbitro significa que o prato conta zero."}, {"q": "Simples, primeiro incidente: o primeiro tiro falha e o segundo cartucho não dispara, por isso o prato repete-se. Na repetição o atirador parte-o com o primeiro tiro. Decisão?", "options": ["BOM", "NULO outra vez", "BOM, com advertência", "Zero: nesta repetição só conta um prato partido com o segundo tiro"], "answer": 3, "why": "Depois de uma falha do segundo tiro, o simples repetido só pode ser partido com o segundo tiro, por isso o primeiro tiro tem de ser uma falha deliberada."}]}, {"id": "sporting-time-and-lateness", "minutes": 5, "title": "Limites de tempo e atrasos", "body": ["O Parcours de Chasse – Sporting™ tem um ritmo apertado, e várias regras protegem-no. Quando o atirador diz «pull» ou «ready», o árbitro transmite o pedido ao operador da máquina por um sinal sonoro, e o prato tem de sair no prazo de três segundos; um prato mais tardio é NULO.", "Entre simples, ou entre doubles, o atirador tem no máximo 15 segundos. Na primeira vez que este tempo é excedido, o árbitro dá uma advertência; depois disso aplicam-se as penalizações do cartão vermelho. Depois de uma decisão final sobre um protesto, o atirador tem de retomar o tiro em 15 segundos, caso contrário conta como recusa em obedecer; o empatar deliberado é tratado da mesma forma.", "Atrasos: quando falta um atirador, o árbitro chama o nome e o número três vezes no espaço de um minuto. Chegar antes da sua vez nos simples do primeiro posto não custa nada. Depois disso, cada prato não atirado é zero; juntar-se num posto posterior significa que todos os pratos dos postos anteriores são zero. Um percurso com postos falhados nunca pode voltar a ser atirado noutra esquadra.", "Um atirador atrasado por motivos alheios à sua vontade não deve voltar a juntar-se à esquadra nessa série, mas recorrer por escrito ao júri. Se o júri aceitar, a série atira-se noutra esquadra; se não, 25 zeros por cada percurso não atirado.", "Entrar no posto sem proteções auditivas ou óculos de proteção conta como ausência. Para um desempate não previsto, os atiradores têm de estar prontos até 15 minutos depois de serem chamados.", "Para si: nunca atrase a esquadra com uma tradução longa. Curto agora, pormenores depois do posto."], "key_points": ["O prato sai até 3 segundos depois do sinal do árbitro; caso contrário, NULO.", "Máximo de 15 segundos entre simples ou doubles: advertência, depois cartão vermelho.", "Retomar em 15 segundos depois de uma decisão final, ou é recusa em obedecer.", "Atraso: nome e número chamados três vezes num minuto; os pratos não atirados são zero."], "terms": ["call", "trapper", "no-bird", "firing-time", "red-card", "jury", "hearing-protection", "safety-glasses", "shoot-off"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch10-deliberate-delay", "label": "10 · Deliberate delay or unfair behaviour"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch16-late-excuse", "label": "16 · Lateness beyond the shooter's control"}, {"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}], "coach_says": [{"en": "Shooter number twenty-three!", "meaning": "O árbitro chama um atirador que falta (três vezes no espaço de um minuto).", "say": "Atirador número vinte e três!"}, {"en": "Watch your time.", "meaning": "Lembrete do limite de 15 segundos entre pratos.", "say": "Atenção ao tempo."}, {"en": "Over fifteen seconds. This is a warning.", "meaning": "Primeira vez acima do limite: advertência; na próxima, penalização.", "say": "Mais de quinze segundos. Isto é uma advertência."}, {"en": "Glasses on, or you can't shoot.", "meaning": "Sem proteção dos olhos, o atirador é considerado ausente.", "say": "Óculos postos, ou não pode atirar."}], "quiz": [{"q": "O atirador pede o prato, o árbitro transmite o sinal, mas o prato sai cerca de cinco segundos depois. O atirador dispara e falha. Decisão?", "options": ["Zero", "NULO", "BOM", "Uma advertência para o atirador"], "answer": 1, "why": "Um prato lançado mais de três segundos depois do sinal do árbitro é NULO."}, {"q": "Um atirador chega quando a sua esquadra ainda está a atirar os simples do posto 1, antes de chegar a sua vez. O que acontece?", "options": ["Junta-se sem penalização", "25 zeros", "Zero em todos os simples do posto 1", "Tem de atirar com outra esquadra"], "answer": 0, "why": "Chegar antes de perder a sua vez nos simples do primeiro posto não tem penalização."}, {"q": "Entre dois simples, um atirador demora cerca de 25 segundos, pela primeira vez hoje. Decisão?", "options": ["Zero no prato seguinte", "Cartão vermelho", "Nenhuma consequência", "Uma advertência do árbitro"], "answer": 3, "why": "O limite é de 15 segundos; na primeira vez que é excedido, o árbitro adverte, e só depois vêm as penalizações."}]}]}, {"id": "compak", "icon": "grid", "title": "Regras do Compak® Sporting", "intro": "O Compak® Sporting concentra a variedade do Parcours de Chasse – Sporting™ num campo pequeno: cinco postos em linha, seis máquinas e um retângulo fixo que os pratos têm de sobrevoar. Muitas regras parecem iguais, mas a posição da arma, os limites de tempo, os doubles e as penalizações são diferentes. Um intérprete que confunda as duas disciplinas dá ao atirador informação errada.", "lessons": [{"id": "compak-layout-rotation", "minutes": 5, "title": "Campo, menu e rotação", "body": ["Um campo de Compak® Sporting é compacto por definição. Os pratos têm de sobrevoar um retângulo marcado, com 35 a 40 m de largura e 25 m de profundidade, com uma bandeira ou marca em cada canto. Virados para ele estão cinco postos de tiro, cada um um quadrado de 1 m, numa linha 4 a 8 m atrás do lado da frente; o posto 3 fica ao centro.", "Há seis máquinas, com as letras A a F da esquerda para a direita, cada uma com um painel. Todos os campos de Compak® têm de incluir um transversal da esquerda para a direita, um transversal da direita para a esquerda e um prato de saída; as outras trajetórias são à escolha do organizador. Cada posto tem um limitador de ângulo de tiro, uma estrutura que impede a arma de rodar demasiado e mantém o atirador dentro do posto.", "Uma série tem 25 pratos, cinco em cada posto: cinco simples, três simples e um double, ou um simples e dois doubles. Num mesmo campo de Compak® o tipo de double é igual em todos os postos. O menu, a ordem dos pratos, está afixado em cada posto, e o primeiro prato de cada double é o último prato atirado no posto anterior.", "Rotação numa esquadra de até seis: começa sempre o posto 1, e o sexto atirador espera atrás dele. Quando o atirador do posto 5 termina, vai esperar atrás do posto 1, todos avançam um posto para a direita e o atirador que estava à espera entra no posto 1. Muda-se de posto com a arma aberta e descarregada, sem perturbar quem ainda está a atirar.", "O Compak® em linha funciona de outra maneira: cada atirador de um grupo vai do posto 1 ao posto 5."], "key_points": ["Retângulo de 35–40 m × 25 m; cinco postos de 1 m; seis máquinas A–F.", "Obrigatórios: transversal da esquerda para a direita, transversal da direita para a esquerda, prato de saída.", "Série = 25 pratos, 5 por posto; um único tipo de double por campo de Compak®.", "Cada double começa com o último prato do posto anterior.", "Depois do posto 5: esperar atrás do posto 1; todos avançam um posto para a direita."], "terms": ["trap", "target-menu", "round", "squad", "rotation", "crosser", "going-away", "shooting-stand", "double", "fly-over-rectangle", "firing-angle-limiter", "waiting-position"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch3-free-trajectories", "label": "3 · Free trajectories"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-squads-groups", "label": "17 · Size of squads and groups"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Move one station to the right.", "meaning": "Rotação depois de o atirador do posto 5 ter terminado.", "say": "Avancem um posto para a direita."}, {"en": "Gun open when you change stations.", "meaning": "Entre postos a arma está aberta e descarregada.", "say": "Arma aberta quando mudar de posto."}, {"en": "Your double starts with the last target of the previous station.", "meaning": "A regra do encadeamento do menu de Compak®.", "say": "O seu double começa com o último prato do posto anterior."}, {"en": "You're waiting behind one.", "meaning": "O sexto atirador fica atrás do posto 1.", "say": "Está à espera atrás do um."}], "quiz": [{"q": "Quantas máquinas e quantos postos tem um campo de Compak® Sporting?", "options": ["4 máquinas, 3 postos", "6 máquinas, 5 postos", "5 máquinas, 5 postos", "8 máquinas, 6 postos"], "answer": 1, "why": "Um campo de Compak® usa seis máquinas, de A a F, e cinco postos de tiro."}, {"q": "O atirador do posto 5 terminou o seu menu. Para onde vai?", "options": ["Para o posto 1", "Fica no posto 5", "Para trás do posto 1, à espera", "Para junto do árbitro, assinar a folha"], "answer": 2, "why": "Passa a ser o atirador em espera atrás do posto 1, enquanto todos os outros avançam um posto para a direita."}, {"q": "Num campo de Compak®, o primeiro prato de cada double é…", "options": ["qualquer prato à escolha do atirador", "sempre a máquina A", "um prato mostrado só a pedido", "o último prato atirado no posto anterior"], "answer": 3, "why": "O menu encadeia os postos: cada double começa com o prato que terminou o posto anterior."}]}, {"id": "compak-gun-and-call", "minutes": 5, "title": "Posição da arma, pedido do prato e tempo", "body": ["É aqui que o Compak® Sporting mais se distingue do Parcours de Chasse – Sporting™. No momento do pedido a posição da arma é livre: a arma pode já estar no ombro, ou não. Não há partida com arma em baixo nem linha no colete. Todos os pratos continuam a atirar-se com a arma no ombro.", "Lançamento: as máquinas são acionadas à mão, por telecomando ou por um phono-pull ativado pela voz. Com lançamento manual, o prato tem de sair 0 a 3 segundos depois do pedido; o phono-pull tem um atraso fixo de 0,5 segundos. As provas internacionais em linha usam apenas phono-pull. Um prato lançado mais de 3 segundos depois do pedido, ou um prato que o atirador não pediu, é NULO.", "Tempo: o atirador tem no máximo 10 segundos para pedir o prato depois de o prato do posto anterior ter sido atirado, menos do que os 15 segundos do Sporting™. Na primeira vez, o árbitro anota uma advertência na folha de marcação; se voltar a acontecer na mesma série, é cartão vermelho e os pratos são pontuados: simples zero, double ao tiro zero e NULO, double simultâneo zero e zero.", "Mostra: no tiro por esquadras, os pratos são mostrados uma vez de manhã, à primeira esquadra. O atirador do posto 1 pede cada simples, de A a F; depois o árbitro mostra os doubles simultâneos e diz «start» ou «competition» (início da competição). Depois de uma interrupção de mais de 10 minutos, os seis simples voltam a ser mostrados.", "Carregar: só no seu próprio posto, com a arma aberta e apontada para a zona de tiro, dentro do limitador de ângulo; feche-a só quando for a sua vez."], "key_points": ["A posição da arma no pedido é livre; os tiros são sempre com a arma no ombro.", "Lançamento manual 0–3 s depois do pedido; phono-pull fixo de 0,5 s; mais de 3 s = NULO.", "Máximo de 10 segundos para pedir o prato: advertência anotada, depois pratos pontuados com zero.", "Os pratos são mostrados uma vez de manhã à primeira esquadra; outra vez depois de uma pausa de mais de 10 minutos."], "terms": ["ready-position", "call", "sonopull", "no-bird", "firing-time", "score-sheet", "target-presentation", "loading"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}], "coach_says": [{"en": "Start! / Competition!", "meaning": "Árbitro: a mostra terminou e começa o tiro a contar.", "say": "Início! / Competição!"}, {"en": "Gun up or down, your choice here.", "meaning": "Treinador: no Compak® a posição da arma no pedido é livre.", "say": "Arma em cima ou em baixo, aqui é à sua escolha."}, {"en": "Ten seconds, call your target.", "meaning": "Lembrete do limite de 10 segundos para pedir o prato.", "say": "Dez segundos, peça o seu prato."}, {"en": "Warning: time.", "meaning": "Primeira vez acima dos 10 segundos; fica anotado na folha de marcação.", "say": "Advertência: tempo."}], "quiz": [{"q": "No Compak® Sporting, um atirador pede o prato com a arma já no ombro. Qual é a decisão do árbitro?", "options": ["Cartão amarelo", "Permitido: a posição da arma no pedido é livre", "Zero", "Permitido só nos doubles"], "answer": 1, "why": "O Compak® Sporting não tem partida com arma em baixo nem linha no colete; só o próprio tiro tem de ser disparado com a arma no ombro."}, {"q": "Lançamento manual. O prato sai cerca de quatro segundos depois do pedido e o atirador falha. Decisão?", "options": ["Zero", "BOM", "Só uma advertência ao operador, o zero mantém-se", "NULO"], "answer": 3, "why": "Um prato lançado mais de 3 segundos depois do pedido é NULO e é lançado outra vez."}, {"q": "Pela segunda vez na mesma série, um atirador demora mais de 10 segundos a pedir o prato. É um simples. Decisão?", "options": ["Zero", "Só mais uma advertência", "NULO", "Expulsão"], "answer": 0, "why": "Depois da primeira advertência, uma repetição na mesma série é penalizada segundo a tabela: um simples conta zero."}]}, {"id": "compak-singles-doubles", "minutes": 5, "title": "Simples e doubles no Compak®", "body": ["O Compak® Sporting usa as mesmas palavras que o Parcours de Chasse – Sporting™, mas os seus doubles seguem regras diferentes. Um intérprete que transporte as regras do Sporting™ vai dar respostas erradas.", "Simples: cada simples tem de permitir dois tiros a partir de cada um dos cinco postos, por isso o segundo cano é uma segunda oportunidade legítima.", "O regulamento do Compak® define dois tipos de double: ao tiro (o pedido lança o primeiro prato, o tiro lança o segundo; uma ou duas máquinas) e simultâneo (dois pratos num só pedido, sempre de duas máquinas diferentes, atirados por qualquer ordem). Não há rafale.", "A diferença principal: num double de Compak® só pode ser disparado um cartucho a cada prato. Disparar os dois tiros ao primeiro prato é proibido, e o guia rápido dos árbitros pontua um disparo duplo deliberado a um mesmo prato com zero e zero. No Sporting™ ambos os cartuchos podem ir para um só prato.", "Dois pratos com um só tiro: num double ao tiro mantém-se o primeiro resultado, o segundo é NULO, e o double atira-se outra vez. Num double simultâneo é NULO sem nada pontuado e o double repete-se; o mesmo na segunda vez; à terceira vez é zero e zero. No Sporting™ o mesmo tiro conta simplesmente BOM e BOM.", "Pratos irregulares: se o primeiro prato de um double ao tiro, ou qualquer dos pratos de um double simultâneo, for irregular, é lançado um novo double. Se o segundo prato de um double ao tiro for irregular ou for partido pelo primeiro, mantém-se o primeiro resultado e o double repete-se."], "key_points": ["Só dois tipos de double: ao tiro e simultâneo; não há rafale.", "Um cartucho por prato num double; os dois a um só prato = zero e zero (guia rápido).", "Double ao tiro, dois pratos com um só tiro: mantém-se o primeiro resultado, o segundo é NULO, o double repete-se.", "Simultâneo, dois pratos com um só tiro: NULO duas vezes, zero e zero à terceira."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch3-two-with-one-report", "label": "3 · Double on report: both targets broken with one shot"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}, {"book": "compak", "id": "ch20-target-no-bird-actions", "label": "20 · What happens after a target NO BIRD"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}], "coach_says": [{"en": "One shot per bird on the pairs here.", "meaning": "Treinador: no Compak® cada prato de um double só leva um cartucho.", "say": "Aqui, nos doubles, um tiro por prato."}, {"en": "Both with one shot. No Bird, shoot the double again.", "meaning": "Árbitro num double simultâneo: nada pontuado, repetir.", "say": "Os dois com um só tiro. Nulo, atire o double outra vez."}, {"en": "Choose your order on the show.", "meaning": "Treinador: decida a que prato simultâneo atirar primeiro enquanto vê a mostra.", "say": "Escolha a ordem durante a mostra."}, {"en": "Zero, zero.", "meaning": "Árbitro: nenhum dos pratos do double conta.", "say": "Zero, zero."}], "quiz": [{"q": "Double simultâneo no Compak®. Um só tiro parte os dois pratos; é a primeira vez que isso acontece. Decisão?", "options": ["BOM e BOM", "NULO, nada pontuado, o double repete-se", "BOM e NULO", "Zero e zero"], "answer": 1, "why": "No Compak®, um double simultâneo partido com um só tiro é NULO na primeira e na segunda vez, e zero e zero à terceira."}, {"q": "Double ao tiro no Compak®. Um só tiro parte os dois pratos. Decisão?", "options": ["BOM e BOM", "Zero e zero", "Mantém-se o primeiro resultado, o segundo é NULO, e o double repete-se", "NULO, nada pontuado"], "answer": 2, "why": "Num double ao tiro regista-se o resultado do primeiro prato e o double atira-se outra vez para pontuar o segundo."}, {"q": "Num double de Compak®, um atirador falha o primeiro prato e dispara-lhe deliberadamente também o segundo cartucho. Como pontua isto o guia rápido dos árbitros?", "options": ["Zero e zero", "É permitido, como no Sporting™", "O double repete-se", "Só conta o segundo tiro"], "answer": 0, "why": "Num double de Compak® só é permitido um cartucho por prato; um disparo duplo deliberado a um mesmo prato é zero e zero."}]}, {"id": "compak-malfunctions", "minutes": 5, "title": "Deficiências no Compak®", "body": ["No Compak® Sporting, tal como no Parcours de Chasse – Sporting™, as falhas da arma e do cartucho contam-se por série de 25 pratos: o primeiro incidente dá NULO e cartão amarelo; num segundo incidente do mesmo tipo, os pratos a que não se disparou contam zero, com cartão vermelho.", "O que o atirador tem de fazer: ficar no lugar, com a arma apontada para a zona de tiro, sem a abrir nem tocar na patilha de segurança até o árbitro a ter inspecionado. Abri-la antes custa o prato ou os pratos: zero.", "Primeiro incidente, quando os dois canos disparam ao mesmo tempo ou o primeiro cartucho falha: um simples é lançado outra vez, um double ao tiro ou um double simultâneo é lançado outra vez, e nada é pontuado da tentativa falhada. Quando falha o segundo cartucho: num simples o prato é lançado outra vez, mas só o segundo tiro pode pontuar, por isso o primeiro tem de ser uma falha deliberada; num double ao tiro mantém-se o primeiro resultado e o double repete-se para o segundo; num double simultâneo, um novo double.", "Depois de uma deficiência, o atirador tem dois minutos para reparar ou substituir a arma. Excecionalmente, pode pedir emprestada a arma de um atirador que não seja da sua esquadra, com o acordo do dono e do árbitro. Sem uma arma a funcionar, os pratos restantes são zero. Fora disso, não se pode trocar de arma, choke ou canos durante uma série.", "A mesma lógica aplica-se a um coelho falhado com o primeiro tiro que se parte antes do segundo: NULO, e na repetição só conta o segundo tiro."], "key_points": ["Primeiro incidente numa série: NULO + cartão amarelo; segundo do mesmo tipo: zero + cartão vermelho.", "Não abrir a arma nem tocar na segurança antes da inspeção do árbitro.", "Falha do segundo cartucho num simples: na repetição só conta o segundo tiro.", "Dois minutos para reparar ou substituir; empréstimo só de fora da sua esquadra, com o consentimento do dono e do árbitro."], "terms": ["malfunction", "double-discharge", "safety-catch", "no-bird", "zero", "yellow-card", "red-card", "rabbit", "choke"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch20-gun-failure-principle", "label": "20 · Gun or cartridge failures: first and second incident"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-malfunction", "label": "21 · Malfunction: inspection, 2 minutes, replacement gun"}, {"book": "compak", "id": "ch20-gun-failure-first-shot", "label": "20 · Both barrels fire together or the first cartridge fails"}, {"book": "compak", "id": "ch20-gun-failure-second-shot", "label": "20 · The second cartridge fails"}, {"book": "compak", "id": "ch12-borrowing", "label": "12 · Borrowing a gun after a breakdown"}, {"book": "compak", "id": "ch13-shared-gun", "label": "13 · No sharing a gun within a group"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}], "coach_says": [{"en": "Don't move, keep the gun closed.", "meaning": "Árbitro: espere pela inspeção depois de uma falha.", "say": "Não se mexa, mantenha a arma fechada."}, {"en": "First malfunction. Yellow card, No Bird.", "meaning": "Primeiro incidente deste tipo na série; o prato é lançado outra vez.", "say": "Primeira deficiência. Cartão amarelo, nulo."}, {"en": "You have two minutes.", "meaning": "Tempo para reparar ou substituir a arma.", "say": "Tem dois minutos."}, {"en": "Only the second shot counts on this one.", "meaning": "Repetição depois de uma falha do segundo cartucho: falhe de propósito com o primeiro tiro.", "say": "Neste, só conta o segundo tiro."}], "quiz": [{"q": "Primeiro incidente da série no Compak®: o primeiro cartucho falha num simples. O atirador espera corretamente. Decisão?", "options": ["NULO com cartão amarelo; é lançado um novo prato", "Zero", "Cartão vermelho e zero", "BOM"], "answer": 0, "why": "O primeiro incidente de arma ou de cartucho numa série é NULO com uma primeira advertência, assinalada com cartão amarelo."}, {"q": "A arma de um atirador avaria. Ele quer pedir emprestada a arma de um colega de esquadra. É permitido?", "options": ["Sim, com o consentimento do dono", "Sim, se o árbitro concordar", "Sim, sem condições", "Não: quem empresta tem de ser de fora da sua esquadra, e o dono e o árbitro têm ambos de concordar"], "answer": 3, "why": "O Compak® proíbe partilhar uma arma dentro de um grupo; o empréstimo excecional só pode vir de fora dele, com os dois acordos."}, {"q": "Segunda falha da arma do mesmo tipo nesta série, num simples a que o atirador não conseguiu disparar. Decisão?", "options": ["NULO outra vez", "NULO e uma advertência", "Zero, com cartão vermelho", "O prato volta a ser mostrado"], "answer": 2, "why": "A partir do segundo incidente do mesmo tipo, os pratos a que não se disparou contam zero."}]}, {"id": "compak-dress-and-conduct", "minutes": 5, "title": "Vestuário e conduta", "body": ["As provas de Compak® Sporting são públicas, por isso o vestuário tem de ser adequado e prático. Os calções curtos são proibidos, mas as bermudas que terminem no máximo 5 cm acima do joelho são aceites. As camisolas precisam de ter pelo menos manga curta e chegar ao pescoço; uma T-shirt serve, mas não o tronco nu por baixo do colete. As sandálias são proibidas no treino e em competição. O dorsal usa-se nas costas, bem visível; uma primeira infração dá uma advertência, depois sanções.", "As proteções auditivas e oculares são obrigatórias. Chegar ao posto sem elas conta como ausência: não se atira.", "Pontualidade: apresente-se ao árbitro a tempo. No tiro por esquadras, chegar depois de o primeiro atirador da esquadra ter pedido o primeiro prato custa 25 zeros nessa série; o recurso vai para o júri, por escrito, no mesmo dia.", "Conduta: o treino durante a competição é proibido; o atirador leva cartão amarelo e o treinador é afastado da zona de tiro. Contestar uma decisão definitiva depois de o tiro ter recomeçado, ou criticar abertamente uma decisão como atirador ou espectador, é uma tentativa de influenciar o árbitro e pode levar à exclusão. No fim de cada série, o atirador assina a folha de marcação; recusar-se a assinar significa perder o direito de reclamar.", "Perto do posto, o intérprete faz parte do público: use proteções, fique calado durante o pedido do prato, nunca comente uma decisão. Saber se pode transmitir as palavras de um treinador em competição é uma questão em aberto para a FITASC; a prática segura é interpretar apenas para o árbitro, o júri e o organizador."], "key_points": ["Nada de calções curtos, nada de tronco nu por baixo do colete, nada de sandálias (também no treino); dorsal nas costas.", "Sem proteção auditiva ou ocular no posto = ausente, não atira.", "Atraso depois do primeiro pedido da esquadra: 25 zeros; é possível um recurso escrito no mesmo dia.", "Nada de treino; nada de críticas públicas às decisões; assinar a folha de marcação."], "terms": ["dress-code", "competitor-number", "hearing-protection", "safety-glasses", "conduct", "yellow-card", "score-sheet", "protest", "quiet-on-stand"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-late-appeal", "label": "9 · Appealing a lateness penalty"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}], "coach_says": [{"en": "Number on your back, please.", "meaning": "Árbitro: o dorsal tem de estar bem visível nas costas.", "say": "O dorsal nas costas, por favor."}, {"en": "Ears and eyes on.", "meaning": "Ponha as proteções auditivas e os óculos antes de chegar ao posto.", "say": "Proteções e óculos postos."}, {"en": "Sign the sheet, please.", "meaning": "Fim da série: o atirador assina a folha de marcação.", "say": "Assine a folha, por favor."}, {"en": "No coaching on the stand.", "meaning": "Advertência do árbitro: o treino é proibido em competição.", "say": "Nada de treino no posto."}], "quiz": [{"q": "Um atirador chega ao posto de sandálias para uma série de treino. É permitido?", "options": ["Sim, só no treino", "Não: as sandálias são proibidas no treino e em competição", "Sim, com meias", "Só com autorização do árbitro"], "answer": 1, "why": "O código de vestuário do Compak® proíbe as sandálias, por segurança, no treino e em competição."}, {"q": "Tiro por esquadras. Um atirador chega logo depois de o primeiro atirador da sua esquadra ter pedido o primeiro prato. Resultado?", "options": ["Sem penalização", "Zero só no primeiro prato", "Atira no fim da esquadra", "25 zeros na série; é possível um recurso escrito ao júri no mesmo dia"], "answer": 3, "why": "O prazo é o primeiro pedido da esquadra; depois dele, o atirador atrasado leva 25 zeros, a não ser que o júri aceite um motivo válido."}, {"q": "Depois da série, um atirador recusa-se a assinar a folha de marcação porque discorda de uma decisão. Qual é a consequência?", "options": ["Perde o direito de fazer qualquer reclamação", "O árbitro tem de alterar o resultado", "A série atira-se outra vez", "Não acontece nada"], "answer": 0, "why": "Assinar a folha no fim de cada série é obrigatório; recusar-se a assinar torna qualquer reclamação inadmissível."}]}]}, {"id": "referee", "icon": "whistle", "title": "Árbitro, pontuação e penalizações", "intro": "Numa competição, o árbitro é a pessoa cujas palavras vai traduzir com mais frequência e mais cuidado. Esta missão dá-lhe as vozes de comando, a folha de marcação, os cartões e as penalizações, o procedimento de protesto e as categorias de idade, para que cada decisão chegue ao seu atirador exatamente como foi tomada.", "lessons": [{"id": "referee-calls", "minutes": 5, "title": "O que o árbitro diz no posto", "body": ["Um posto tem a sua própria linguagem curta. O atirador pede o prato quando está pronto, normalmente com «Pull!» ou «Ready!». No Parcours de Chasse – Sporting™ o árbitro transmite esse pedido ao operador da máquina com um sinal sonoro, e o prato tem de sair no prazo de três segundos; um prato mais tardio é NULO. No Compak® Sporting, o lançamento manual também tem de ocorrer até três segundos depois do pedido, e o lançamento por voz (phono-pull) tem um atraso fixo de meio segundo.", "Antes de alguém atirar, o árbitro controla a arma. Só se pode carregar no posto, com a arma apontada para a zona de tiro, depois de o árbitro ter dito que o tiro pode começar. Durante a mostra dos pratos, e sempre que o tiro para, as armas estão abertas e vazias e só voltam a ser fechadas por ordem do árbitro. No Compak® o árbitro dá início à série com «Start» ou «Competition».", "Depois de cada prato, as regras conhecem três resultados: «one» (acerto, BOM), «zero» (falha, ZERO) e «No Bird» (NULO: o prato não conta e é lançado outra vez). Pelo mundo fora também vai ouvir «dead», «good», «lost», ou simplesmente silêncio no caso de um acerto. No Compak® o árbitro tem de anunciar cada zero em voz alta ou com um sinal sonoro, para que um atirador que discorde possa protestar de imediato.", "O atirador também tem uma palavra formal: com a mão levantada, «Protest!» ou «Appeal!» (protesto, recurso). Quando interpretar, mantenha estas vozes curtas e sempre iguais. Combine com o seu atirador, antes da série, que palavras vai usar, e nunca acrescente nada da sua parte entre o pedido e o tiro."], "key_points": ["O atirador pede «Pull!» ou «Ready!»; o prato tem de sair em 3 segundos", "Carregar só no posto e só quando o árbitro o permitir; armas abertas durante a mostra e as paragens", "Palavras das regras: one = acerto (BOM), zero = falha (ZERO), No Bird = NULO, lançado outra vez", "Compak®: cada zero é anunciado em voz alta ou por sinal sonoro", "Protesto = mão levantada + «Protest!» ou «Appeal!»"], "terms": ["call", "referee", "trapper", "sonopull", "one", "zero", "no-bird", "loading", "target-presentation", "protest"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch5-referee-oath", "label": "5 · Referee's commitments"}, {"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}], "coach_says": [{"en": "You may load.", "meaning": "O árbitro autoriza o início do tiro: carregue agora, com a arma apontada para a zona de tiro.", "say": "Pode carregar."}, {"en": "No bird!", "meaning": "Esse prato não conta; não lhe atire. Vai ser lançado outra vez.", "say": "Nulo!"}, {"en": "Lost.", "meaning": "O árbitro pontuou o prato como falha (zero).", "say": "Zero."}, {"en": "Dead. / Good.", "meaning": "O prato é um acerto (BOM).", "say": "Bom."}, {"en": "Guns open, please — we’re showing the targets.", "meaning": "Todos abrem e descarregam as armas; o árbitro vai lançar os pratos para a mostra.", "say": "Armas abertas, por favor — vamos mostrar os pratos."}, {"en": "Start. / Competition.", "meaning": "Compak®: a mostra acabou, a série conta a partir de agora.", "say": "Início. / Competição."}], "quiz": [{"q": "No Parcours de Chasse – Sporting™ o prato sai cinco segundos depois do sinal do árbitro. Qual é a decisão?", "options": ["Conta normalmente", "NULO", "Zero, porque o atirador pediu cedo demais", "Só uma advertência ao operador"], "answer": 1, "why": "Um prato tem de sair até três segundos depois do sinal do árbitro; um mais tardio é NULO e é lançado outra vez."}, {"q": "Quando pode um atirador carregar a arma?", "options": ["Enquanto caminha para o posto", "Atrás do posto, enquanto espera", "No posto, com a arma apontada para a zona de tiro, depois de o árbitro autorizar o tiro", "Sempre que o treinador o disser"], "answer": 2, "why": "Só se pode carregar no posto, com a arma apontada para a zona de tiro, e só depois de o árbitro ter autorizado o início."}, {"q": "Que palavra dá início a um protesto formal no posto?", "options": ["«Protest!» ou «Appeal!», com a mão levantada", "«Pull!»", "«No bird!»", "«Árbitro, veja!»"], "answer": 0, "why": "Os dois regulamentos indicam «protest» ou «appeal» com a mão levantada; «No bird» pertence apenas ao árbitro."}]}, {"id": "referee-scoring", "minutes": 5, "title": "Folhas de marcação, resultados e empates", "body": ["Cada prato acaba numa folha de marcação. No Parcours de Chasse – Sporting™ é o árbitro que preenche a folha, ou alguém sob a sua supervisão. O modelo da FITASC mostra a letra da máquina de cada prato, com X para um acerto e O para uma falha, um total e uma coluna para a assinatura. Antes de a esquadra seguir, o árbitro fotografa a folha.", "Os atiradores têm de verificar o seu resultado ao sair de cada posto. Um desacordo vai de imediato para o árbitro; o árbitro decide, eventualmente depois de ouvir outras pessoas, e depois disso não há recurso. No Compak® Sporting o atirador assina a folha de marcação no fim da série, e um atirador que se recuse a assinar perde o direito de reclamar. Traduza «check your card» como uma instrução urgente, não como um comentário de cortesia.", "Uma prova internacional tem 200 pratos, em séries de 25. Quando há empate nos três primeiros lugares, os atiradores fazem um desempate (shoot-off) de 25 pratos; se continuarem empatados, segue-se a morte súbita, em que o primeiro zero elimina. Abaixo do terceiro lugar não há desempate: os atiradores empatados partilham o lugar e são ordenados pela ordem inversa (countback), do último (oitavo) percurso ou campo de Compak® para o primeiro. As equipas nunca fazem desempate.", "Os desempates trazem mais uma armadilha para o intérprete. Se não tiver sido fixada uma hora, os atiradores têm de estar prontos até quinze minutos depois da chamada. Um atirador que falte é «disqualified» (desclassificado) nas regras do Sporting™ e «considered withdrawn» (considerado desistente) nas regras do Compak®. Use a palavra da disciplina em que está."], "key_points": ["X = acerto, O = falha nas folhas de marcação da FITASC", "Sporting™: verificar o resultado ao sair de cada posto; Compak®: assinar a folha ou perder o direito de reclamar", "Empates nos lugares 1–3: desempate de 25 pratos, depois morte súbita", "Abaixo do 3.º: ordem inversa a partir do 8.º percurso ou campo de Compak®; as equipas não fazem desempate", "Pronto até 15 minutos depois da chamada para um desempate"], "terms": ["score-sheet", "round", "one", "zero", "shoot-off", "countback", "team", "referee"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}, {"book": "sporting", "id": "ch18-team-ties", "label": "18 · Team ties"}, {"book": "compak", "id": "ch15-who-keeps", "label": "15 · Who keeps the score sheet"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}, {"book": "compak", "id": "ch14-shootoff-availability", "label": "14 · Staying available for a shoot-off"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}, {"book": "compak", "id": "ch14-team-ties", "label": "14 · Ties between national teams"}], "coach_says": [{"en": "Check your card before you leave the stand.", "meaning": "Veja agora as suas marcações; objeções posteriores não são aceites.", "say": "Verifique a sua folha antes de sair do posto."}, {"en": "Sign here, please.", "meaning": "Compak®: assinar confirma o resultado; recusar significa perder o direito de reclamar.", "say": "Assine aqui, por favor."}, {"en": "Twenty-three — you dropped two.", "meaning": "Resultado de 23 em 25; dois pratos foram perdidos.", "say": "Vinte e três — deixou cair dois."}, {"en": "There’s a tie for third — shoot-off in fifteen minutes.", "meaning": "Esteja no percurso indicado e pronto a atirar no prazo de quinze minutos.", "say": "Há um empate no terceiro lugar — desempate dentro de quinze minutos."}, {"en": "Sudden death: first zero is out.", "meaning": "Depois do desempate de 25 pratos, o primeiro atirador a falhar (com o mesmo número de pratos atirados) é eliminado.", "say": "Morte súbita: o primeiro zero sai."}], "quiz": [{"q": "Numa folha de marcação da FITASC, o que significa O?", "options": ["Um acerto", "Um NULO", "Uma falha", "Um posto vazio"], "answer": 2, "why": "O modelo da FITASC marca um acerto com X e uma falha com O."}, {"q": "Dois atiradores empatam no 7.º lugar. O que acontece?", "options": ["Um desempate de 25 pratos", "Morte súbita imediata", "Um sorteio à moeda feito pelo júri", "Partilham o lugar e são ordenados pela ordem inversa"], "answer": 3, "why": "Os desempates são só para os lugares 1–3; abaixo disso, os atiradores empatados são ordenados pela ordem inversa a partir do oitavo percurso ou campo de Compak®."}, {"q": "No Compak® Sporting, o seu atirador recusa-se a assinar a folha de marcação. Qual é a consequência?", "options": ["Perde o direito de fazer qualquer reclamação", "A série atira-se outra vez", "O árbitro assina e nada muda", "Leva automaticamente 25 zeros"], "answer": 0, "why": "As regras do Compak® dizem que um atirador que se recuse a assinar perde o direito de reclamar."}]}, {"id": "referee-cards", "minutes": 5, "title": "Advertências, cartões e penalizações", "body": ["As penalizações da FITASC sobem por uma escada. Ao inscrever-se numa competição, o atirador aceita as regras e as sanções. A primeira infração a uma regra dá normalmente uma advertência, mostrada com um cartão amarelo. No Parcours de Chasse – Sporting™ um exemplo clássico é a posição da arma: uma coronha acima da linha do colete, ou uma arma posta à cara antes de o prato aparecer, vale uma advertência verbal e um cartão amarelo.", "Uma reincidência no mesmo percurso (ou no mesmo campo de Compak®) dá cartão vermelho, e o prato é pontuado segundo uma tabela: zero num simples, zero e NULO num double ao tiro, zero e zero num double simultâneo ou rafale. A mesma escala aplica-se a disparar contra um prato declarado NULO e, no Sporting™, a exceder os quinze segundos entre pratos. No Compak® Sporting o limite é de dez segundos para pedir o prato.", "O treino durante uma competição também é penalizado: o atirador leva cartão amarelo, as repetições trazem novas sanções, e o árbitro manda a pessoa que estava a dar instruções sair da zona de tiro. Para um intérprete, este é o cartão mais importante de todo o regulamento.", "Para reincidências, recusa em obedecer ou tentativas de influenciar um árbitro, o júri pode retirar um prato, uma série inteira de 25, ou expulsar o atirador. Atirar uma arma ao chão, insultos ou violência, e disparar deliberadamente contra animais vivos podem significar expulsão imediata. Uma expulsão fica registada pela FITASC durante cinco anos e não dá direito a reembolso. Traduza «warning», «yellow card» e «red card» (advertência, cartão amarelo, cartão vermelho) à letra, com calma e de imediato."], "key_points": ["Primeira infração: advertência com cartão amarelo", "Reincidência no mesmo percurso ou campo de Compak®: cartão vermelho + prato pontuado segundo a tabela", "Treino em competição: cartão amarelo para o atirador, treinador afastado", "Escala do júri: um prato, uma série, ou expulsão", "Expulsão: fica registada 5 anos, sem reembolso"], "terms": ["yellow-card", "red-card", "penalty", "ready-position", "firing-time", "jury", "conduct"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch13-acceptance", "label": "13 · Acceptance of rules; first breach = warning"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch12-shooting-nobird", "label": "12 · Shooting at a declared No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch13-jury-penalties", "label": "13 · Jury penalty scale"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "sporting", "id": "ch13-immediate-expulsion", "label": "13 · Immediate expulsion"}, {"book": "sporting", "id": "ch13-expulsion-record", "label": "13 · Expulsion record and lifetime ban"}, {"book": "sporting", "id": "ch13-no-refund", "label": "13 · No refund after expulsion"}, {"book": "compak", "id": "ch23-yellow-card", "label": "23 · Accepting the rules; first a yellow card"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch23-exclusion-record", "label": "23 · Exclusions: record, repeat, no refund"}], "coach_says": [{"en": "Warning — your stock was above the line.", "meaning": "Sporting™: a arma estava demasiado alta antes de o prato aparecer; na próxima vez neste percurso custa o prato.", "say": "Advertência — a sua coronha estava acima da linha."}, {"en": "That’s a yellow card.", "meaning": "Uma primeira advertência oficial; fica registada.", "say": "Isto é um cartão amarelo."}, {"en": "Red card — the target is zero.", "meaning": "Uma reincidência: o prato é pontuado como perdido.", "say": "Cartão vermelho — o prato é zero."}, {"en": "You’re over time.", "meaning": "O atirador demorou mais do que o permitido (15 s no Sporting™, 10 s para pedir o prato no Compak®).", "say": "Passou do tempo."}, {"en": "Sir, please leave the shooting area.", "meaning": "O árbitro está a afastar alguém, por exemplo uma pessoa apanhada a dar instruções de treino.", "say": "O senhor, por favor, saia da zona de tiro."}], "quiz": [{"q": "Sporting™: depois de um cartão amarelo por arma à cara, o atirador volta a pôr a arma à cara cedo no mesmo percurso, num simples. Qual é o resultado?", "options": ["Outra advertência", "Cartão vermelho e o prato é zero", "NULO", "Expulsão imediata"], "answer": 1, "why": "Depois da primeira advertência, uma nova infração no mesmo percurso dá cartão vermelho; num simples, o prato é zero."}, {"q": "O árbitro vê um treinador a dar conselhos a um atirador durante uma competição. O que dizem as regras?", "options": ["Nada, o treino é permitido entre postos", "O treinador leva cartão vermelho", "O atirador leva cartão amarelo e o treinador é afastado da zona de tiro", "A série é anulada"], "answer": 2, "why": "Os dois regulamentos dão ao atirador um cartão amarelo e mandam o árbitro afastar da zona de tiro a pessoa que dá as instruções."}, {"q": "Qual destas sanções NÃO pode o júri aplicar segundo a escala de penalizações?", "options": ["Perda de um prato", "Perda de uma série de 25", "Expulsão", "Uma multa em dinheiro paga ao árbitro"], "answer": 3, "why": "A escala do júri é perda de um prato, perda de uma série ou expulsão; não há multa paga ao árbitro."}]}, {"id": "referee-appeals", "minutes": 5, "title": "Protestos, cauções e o júri", "body": ["Um protesto tem de ser feito no momento. O atirador levanta a mão e diz «Protest!» ou «Appeal!» no posto, antes de pedir o prato seguinte (no Compak® Sporting, antes de o atirador seguinte pedir o prato). O árbitro interrompe o tiro e ouve o motivo. Ao pedir o prato seguinte, o atirador aceita a decisão anterior, por isso, como intérprete, aqui tem de ser rápido.", "Se o árbitro tiver a certeza, a decisão é confirmada e torna-se definitiva. Em caso de dúvida, o árbitro pode consultar outro árbitro, o operador da máquina ou os atiradores da esquadra, apenas a título de conselho, e depois decide sozinho. Os atiradores nunca podem ir buscar ou apanhar um prato para o verificar, e um prato partido atrás de um obstáculo natural ou para lá de um limite da zona de tiro é decisão do árbitro.", "Algumas decisões nunca podem ir ao júri: se um prato foi BOM ou ZERO, um NULO, e se uma trajetória estava correta. Outras decisões podem ser objeto de recurso escrito ao júri, com caução: no Parcours de Chasse – Sporting™ são 40% da taxa de inscrição; no Compak®, o montante em vigor no dia, e só sobre incidentes desse mesmo dia. Se o recurso for aceite, a caução é devolvida.", "Depois da decisão definitiva, o atirador tem de retomar o tiro em quinze segundos no Sporting™ e em dez no Compak®; caso contrário, é recusa em obedecer. Continuar a discutir, desafiar o árbitro para dar espetáculo, ou outras pessoas criticarem abertamente uma decisão conta como tentativa de influenciar o árbitro. O seu trabalho é traduzir o protesto e a resposta com exatidão, não defender a causa."], "key_points": ["Protestar de imediato, no posto, com a mão levantada: «Protest!» / «Appeal!»", "Pedir o prato seguinte = aceitar a decisão anterior", "Nunca recorríveis: BOM/ZERO, NULO, trajetória correta", "Recurso escrito ao júri com caução (Sporting™: 40% da taxa de inscrição)", "Retomar em 15 s (Sporting™) ou 10 s (Compak®); continuar a discutir = influenciar o árbitro"], "terms": ["protest", "appeal", "jury", "referee", "entry-fee", "no-bird", "trajectory"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "sporting", "id": "ch9-consultation", "label": "9 · Referee in doubt: consultation"}, {"book": "sporting", "id": "ch9-jury-appeal", "label": "9 · What can go to the jury and the 40% deposit"}, {"book": "sporting", "id": "ch9-deposit-outcome", "label": "9 · Outcome of a jury appeal"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch15-appeal-jury", "label": "15 · Appeal jury"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}, {"book": "compak", "id": "ch19-consultation", "label": "19 · Referee in doubt: who may be consulted"}, {"book": "compak", "id": "ch4-complaint-limits", "label": "4 · What you cannot complain about"}, {"book": "compak", "id": "ch4-complaint-procedure", "label": "4 · How to lodge a complaint and the deposit"}, {"book": "compak", "id": "ch21-refusal-to-comply", "label": "21 · Refusal to comply: 10 seconds to resume"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Protest! The target was broken before I fired.", "meaning": "O atirador contesta formalmente a decisão e dá o motivo (aqui: foi lançado um prato partido).", "say": "Protesto! O prato estava partido antes de eu disparar."}, {"en": "I’m certain — the decision stands.", "meaning": "O árbitro confirma; a decisão é definitiva.", "say": "Tenho a certeza — a decisão mantém-se."}, {"en": "Did anyone see a piece come off?", "meaning": "O árbitro está em dúvida e pede à esquadra apenas um conselho; continua a ser o árbitro a decidir.", "say": "Alguém viu sair um pedaço?"}, {"en": "You can take it to the jury in writing, with the deposit.", "meaning": "Esta decisão admite recurso; é preciso um recurso escrito e uma caução.", "say": "Pode levar isto ao júri por escrito, com a caução."}, {"en": "Please carry on shooting.", "meaning": "A decisão é definitiva; retome agora, senão passa a ser recusa em obedecer.", "say": "Continue a atirar, por favor."}], "quiz": [{"q": "O seu atirador acha que um prato pontuado com zero foi atingido, mas já pediu o prato seguinte. Ainda pode protestar essa decisão?", "options": ["Sim, no fim da série", "Sim, por escrito ao júri", "Não: pedir o prato seguinte significa aceitar a decisão anterior", "Sim, se a esquadra concordar"], "answer": 2, "why": "Ao pedir o prato seguinte, o atirador aceita a decisão anterior, e as decisões BOM/ZERO nunca vão ao júri de qualquer forma."}, {"q": "Que decisão PODE ser objeto de recurso para o júri?", "options": ["Se um prato foi BOM ou ZERO", "Um NULO", "Se uma trajetória estava correta", "Outra decisão do árbitro, como uma penalização por atraso"], "answer": 3, "why": "As decisões de BOM/ZERO, NULO e trajetória são definitivas; outras decisões do árbitro podem ir ao júri por escrito, com caução."}, {"q": "No Parcours de Chasse – Sporting™, de quanto é a caução para um recurso escrito ao júri?", "options": ["40% da taxa de inscrição", "A taxa de inscrição completa", "50 euros fixos", "Não é precisa caução"], "answer": 0, "why": "As regras do Sporting™ fixam a caução em 40% da taxa de inscrição; é devolvida se o júri der razão ao atirador."}]}, {"id": "referee-categories", "minutes": 5, "title": "Categorias: Junior, Lady, Men, Senior, Veteran, Master", "body": ["Além da classificação geral (open), em que todos competem juntos, as provas da FITASC classificam os atiradores em categorias por idade e sexo. A partir de 1 de janeiro de 2027, a tabela internacional do Parcours de Chasse – Sporting™ e do Compak® Sporting tem seis categorias: Junior (13–20), Lady (senhoras, a partir dos 13), Men (homens, 21–55), Senior (56–65), Veteran (66–72) e Master (a partir dos 73, homens e mulheres). Para provas anteriores a essa data, consulte a tabela então em vigor no site da FITASC.", "O que conta é o ano de nascimento, não o dia de anos. Um atirador passa para uma nova categoria a 1 de janeiro do ano em que atinge a idade. Para a época de 2027 isto significa: Junior, nascidos em 2007–2014; Men, nascidos em 1972–2006; Senior, 1962–1971; Veteran, 1955–1961; Master, nascidos antes de 1955. Os limites avançam um ano a cada época.", "A maior armadilha para o intérprete é «Senior». Em inglês corrente soa a «adulto», mas na FITASC Senior designa o escalão dos 56–65 anos; a categoria principal de adultos é Men. Não o traduza por «adultos», e lembre-se de que em muitas provas nacionais a palavra «sénior» pode designar a categoria geral de adultos. «Master» é outra armadilha: a categoria de idade da FITASC a partir dos 73 anos não tem nada a ver com a «Master class» da NSCA, que é um nível de desempenho.", "As equipas têm regras próprias: normalmente três atiradores, mas a equipa Men no Sporting™ tem quatro. Um júnior colocado na equipa Men, ou uma júnior na equipa Lady, tem também de se inscrever individualmente nessa categoria. As federações nacionais e os clubes podem usar as suas próprias categorias, por isso verifique sempre o programa da competição, e nos desempates lembre-se de que as categorias têm os seus próprios três primeiros."], "key_points": ["Seis categorias da FITASC a partir de 2027: Junior, Lady, Men, Senior, Veteran, Master", "Decide o ano de nascimento; a nova categoria começa a 1 de janeiro", "Senior = 56–65, não «adultos»; a categoria principal de adultos é Men", "Master da FITASC (73+) ≠ Master class da NSCA", "Equipas de 3; equipa Men no Sporting™ = 4; os programas nacionais podem ser diferentes"], "terms": ["category", "veteran", "team", "shoot-off", "entry"], "sources": [{"title": "FITASC — Categories", "url": "https://www.fitasc.com/competitions/categories"}], "sim": null, "rule_refs": [{"book": "categories", "id": "junior", "label": "Junior"}, {"book": "categories", "id": "lady", "label": "Lady"}, {"book": "categories", "id": "men", "label": "Men"}, {"book": "categories", "id": "senior", "label": "Senior"}, {"book": "categories", "id": "veteran", "label": "Veteran"}, {"book": "categories", "id": "master", "label": "Master"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}], "coach_says": [{"en": "Which category are you shooting in?", "meaning": "Pergunta feita no secretariado: Junior, Lady, Men, Senior, Veteran ou Master.", "say": "Em que categoria vai atirar?"}, {"en": "He’s a Senior now.", "meaning": "Esta época está no escalão dos 56–65 anos.", "say": "Agora ele é Senior."}, {"en": "She won the Lady category and was fourth overall.", "meaning": "Primeira entre as senhoras, quarta na classificação geral.", "say": "Ganhou a categoria Lady e ficou em quarto na geral."}, {"en": "There’s a shoot-off for Veteran bronze.", "meaning": "Dois ou mais Veteran estão empatados no terceiro lugar da sua categoria.", "say": "Há um desempate para o bronze de Veteran."}], "quiz": [{"q": "Um atirador nascido em 1971 inscreve-se numa competição da FITASC em 2027. Em que categoria?", "options": ["Men", "Senior", "Veteran", "Master"], "answer": 1, "why": "Faz 56 anos em 2027, por isso é Senior a partir de 1 de janeiro, seja qual for o dia de anos."}, {"q": "Como deve traduzir para um cliente a categoria «Senior» da FITASC?", "options": ["«Adultos»", "«Atiradores experientes»", "«Classe de topo»", "«O escalão dos 56–65 anos»"], "answer": 3, "why": "Na FITASC, Senior é um escalão de idade de 56–65 anos; a categoria principal de adultos é Men."}, {"q": "Quantos atiradores tem uma equipa Men no Parcours de Chasse – Sporting™?", "options": ["Quatro", "Três", "Seis", "Cinco"], "answer": 0, "why": "As equipas têm normalmente três atiradores, mas a equipa Men no Sporting™ tem quatro."}]}]}, {"id": "etiquette", "icon": "shield", "title": "Segurança e etiqueta", "intro": "Num campo de tiro, a segurança vem antes de qualquer tradução, e as boas maneiras mantêm a esquadra calma e concentrada. Esta missão mostra como se manuseiam as armas, como as pessoas se comportam à volta do posto e numa esquadra, e o que todos, incluindo o intérprete, têm de usar.", "lessons": [{"id": "etiquette-gun-safety", "minutes": 5, "title": "Segurança com a arma: aberta, vazia, canos em segurança", "body": ["Todas as armas são tratadas como perigosas, mesmo quando estão vazias. Fora do posto transportam-se abertas: uma sobreposta aberta sobre o antebraço, uma semi-automática com a culatra aberta, os canos virados a direito para cima ou para baixo. Não são permitidas bandoleiras. Quando ninguém a está a usar, a arma fica de pé num armeiro (suporte de armas). Ninguém toca na arma de outro atirador sem autorização.", "Os cartuchos só entram na arma no posto, com os canos apontados para a zona de tiro, e só quando o árbitro ou o instrutor o permitir. Uma semi-automática não leva mais de dois. Antes de se virar no posto, o atirador abre a arma e tira todos os cartuchos, disparados ou não. Durante a mostra dos pratos, e em qualquer paragem, as armas ficam abertas.", "Se a arma não disparar, o atirador fica no lugar, com a arma apontada para a zona de tiro, e não a abre nem toca na patilha de segurança até o árbitro a ter verificado. É ao mesmo tempo uma regra de segurança e uma regra de pontuação: abrir antes do tempo custa o prato. Pôr a arma à cara e movê-la atrás de um prato imaginário fora do posto, ou enquanto outra pessoa está a atirar, também não é permitido, e as armas só se testam num posto de ensaio, nunca no posto de competição.", "Quando alguém grita «Stop!» ou «Cease fire!» (cessar fogo), todos param de imediato e abrem a arma. Não transforme isto numa frase: repita «Stop!» em voz alta na língua dos seus convidados e verifique se as armas deles estão abertas. Se um convidado se virar para si com a arma para perguntar alguma coisa, primeiro faça-lhe sinal para apontar os canos para baixo e só depois traduza."], "key_points": ["Fora do posto: arma aberta, vazia, canos para cima ou para baixo, sem bandoleiras", "Carregar só no posto, apontando para a zona de tiro, com autorização; semi-automática no máximo 2", "Abrir e descarregar antes de se virar; armas abertas durante a mostra e as paragens", "Depois de uma falha de percussão: ficar no lugar, não abrir, esperar pelo árbitro", "«Stop!» repete-se, não se explica"], "terms": ["safety", "gun-handling", "muzzle", "gun-rack", "loading", "malfunction", "mock-shooting", "gun-test", "cease-fire", "semi-automatic"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "sporting", "id": "ch7-touching-sharing", "label": "7 · Other shooters' guns; sharing a gun"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "sporting", "id": "ch3-testing-guns", "label": "3 · No test shots on the stand"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-open-gun", "label": "21 · Keep the gun open: turning round, target viewing, interruptions"}, {"book": "compak", "id": "ch11-testing-guns", "label": "11 · Where to test your gun"}], "coach_says": [{"en": "Guns open and empty between stands, please.", "meaning": "A caminho do posto seguinte, a arma vai aberta e sem cartuchos.", "say": "Armas abertas e descarregadas entre postos, por favor."}, {"en": "Break your gun and show me it’s clear.", "meaning": "Abra a arma (não a parta!) para eu ver que as câmaras estão vazias.", "say": "Abra a arma e mostre-me que está descarregada."}, {"en": "Don’t load until you’re on the stand and I say so.", "meaning": "Nada de cartuchos na arma enquanto caminha ou espera.", "say": "Não carregue até estar no posto e eu lhe dizer."}, {"en": "Muzzles down when you turn round.", "meaning": "Nunca deixe os canos apontarem para pessoas, mesmo com a arma aberta.", "say": "Canos para baixo quando se virar."}, {"en": "Stop! Stop! Guns open!", "meaning": "Paragem de emergência: parar de atirar, abrir a arma, esperar.", "say": "Stop! Stop! Armas abertas!"}], "quiz": [{"q": "Como se transporta uma semi-automática entre postos?", "options": ["Fechada, com a segurança engatada", "Com a culatra aberta, o cano a direito para cima ou para baixo", "A tiracolo, numa bandoleira", "Carregada com um cartucho"], "answer": 1, "why": "As armas transportam-se abertas, as semi-automáticas com a culatra aberta, os canos a direito para cima ou para baixo; as bandoleiras não são permitidas."}, {"q": "A arma faz clique mas não dispara. O que tem de fazer o atirador?", "options": ["Abri-la imediatamente e ver", "Virar-se para a mostrar ao treinador", "Ficar no lugar, com a arma apontada para a zona de tiro, sem a abrir nem tocar na segurança até o árbitro verificar", "Engatar a segurança e pedir outra vez"], "answer": 2, "why": "Os dois regulamentos exigem que o atirador fique no lugar até o árbitro inspecionar; abrir ou tocar na segurança antes dá zero."}, {"q": "Alguém grita «Cease fire!». Qual é a primeira tarefa do intérprete?", "options": ["Repetir «Stop!» em voz alta e verificar se os convidados abrem as armas", "Explicar porque parou o tiro", "Perguntar ao treinador o que aconteceu", "Esperar que o convidado pergunte"], "answer": 0, "why": "Uma paragem de emergência repete-se de imediato; as explicações só vêm quando todas as armas estiverem abertas."}]}, {"id": "etiquette-on-the-stand", "minutes": 5, "title": "À volta do posto: silêncio, distância, imobilidade", "body": ["Um atirador no posto precisa de concentração total, desde que carrega a arma até a abrir depois do último tiro. As regras põem os lugares de espera perto do posto, mas dizem que não podem distrair o atirador. Na prática isso significa: vozes baixas ou nenhumas, nenhum movimento brusco no campo de visão do atirador, armas abertas e telemóveis em silêncio e no bolso. As regras não falam de telemóveis, mas todos os campos esperam esta cortesia.", "Fique atrás do atirador, nunca ao lado nem à frente do posto. No Compak® Sporting, a estrutura do limitador de ângulo de tiro limita o movimento de cada atirador; no Parcours de Chasse – Sporting™, os postos de muitos campos têm uma gaiola. Todos os outros esperam atrás dela, fora de qualquer linha possível dos canos. No Compak® o atirador em espera fica atrás do posto 1, e um atirador que já terminou espera sem perturbar o seguinte.", "Perturbar um atirador tem consequências nas regras. Se o árbitro vir que um atirador foi claramente perturbado, o prato é NULO e é lançado outra vez. Não é permitido o simulacro de tiro enquanto um membro da esquadra está a atirar. Só atira o atirador cuja vez é, e só ao seu próprio prato.", "Para si, esta lição é prática. Pare de falar quando o seu convidado entrar no posto, mesmo a meio de uma frase. Não responda a perguntas enquanto a arma estiver fechada. Volte a falar só quando a arma estiver aberta: entre pratos, entre doubles, ou depois do posto. Um conselho perdido custa menos do que um double estragado pela sua voz."], "key_points": ["Silêncio, imobilidade, armas abertas, telemóveis em silêncio atrás do atirador", "Fique atrás do posto, da gaiola ou do L.A.T., nunca ao lado nem à frente", "Um atirador claramente perturbado tem direito a um NULO", "Nada de simulacro de tiro enquanto outra pessoa atira", "Intérprete: falar só quando a arma estiver aberta"], "terms": ["quiet-on-stand", "shooting-stand", "conduct", "no-bird", "mock-shooting", "rotation"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch8-own-turn-live-animals", "label": "8 · Shoot only in turn; not at others' targets or animals"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}], "coach_says": [{"en": "Quiet behind, please — she’s on.", "meaning": "A atiradora está no posto; todos param de falar.", "say": "Silêncio atrás, por favor — ela está no posto."}, {"en": "Wait until he’s opened his gun.", "meaning": "Ninguém fala nem se mexe até o atirador ter terminado e aberto a arma.", "say": "Espere até ele abrir a arma."}, {"en": "Stand right behind me so you can see what I see.", "meaning": "No treino, o treinador quer que fique mesmo atrás dele, fora do movimento da arma.", "say": "Ponha-se mesmo atrás de mim para ver o que eu vejo."}, {"en": "Keep out of his line, please.", "meaning": "Está no campo de visão do atirador ou perto da trajetória dos canos; afaste-se.", "say": "Saia da linha dele, por favor."}], "quiz": [{"q": "Onde fica o intérprete enquanto o convidado atira?", "options": ["Ao lado do atirador, para lhe ver a cara", "À frente do posto, para ver o prato", "Atrás do posto, fora de qualquer linha dos canos", "Onde o árbitro não o veja"], "answer": 2, "why": "Todos esperam atrás do posto ou da gaiola; ao lado do atirador é o sítio mais perigoso."}, {"q": "Uma chamada telefónica em voz alta atrás do posto perturba claramente o atirador no momento do tiro. O que pode o árbitro decidir?", "options": ["NULO: o prato é lançado outra vez", "Zero para o atirador", "Nada, os telemóveis não estão nas regras", "Cartão amarelo para o atirador"], "answer": 0, "why": "Se o árbitro vir que o atirador foi claramente perturbado, o prato é NULO."}, {"q": "Qual é o momento certo para transmitir o comentário do treinador?", "options": ["Enquanto o atirador pede o prato", "Entre o pedido e o tiro", "Sempre que o treinador acabe de falar", "Quando a arma está aberta: entre pratos, entre doubles ou depois do posto"], "answer": 3, "why": "A rotina do atirador não pode ser interrompida; fale só quando a arma estiver aberta."}]}, {"id": "etiquette-squad", "minutes": 5, "title": "Boas maneiras numa esquadra", "body": ["Uma esquadra são até seis atiradores sorteados que atiram juntos. A pontualidade é a primeira cortesia e também uma regra. No Parcours de Chasse – Sporting™ um atirador que falte é chamado três vezes no espaço de um minuto, e os pratos não atirados contam zero. No Compak® Sporting, um atirador que chegue depois de o primeiro atirador da esquadra ter pedido o prato leva 25 zeros nessa série, e é obrigatório apresentar-se antes ao árbitro.", "A ordem conta. No Sporting™ a ordem roda em cada posto e para os doubles; no Compak® os atiradores avançam um posto para a direita depois de cada sequência. Ninguém entra no posto antes de o atirador anterior ter saído. Quando é chamado, o atirador está pronto de imediato, com cartuchos suficientes para toda a série.", "O árbitro decide sozinho. Os membros da esquadra não comentam se um prato foi atingido, a não ser que o árbitro lhes pergunte. A crítica aberta a uma decisão, por parte de atiradores ou espectadores, conta como tentativa de influenciar o árbitro. Perder o autocontrolo, por exemplo atirar uma arma ao chão ou insultar alguém, vai ao júri e pode significar expulsão.", "Para além das regras, há costumes. Os atiradores costumam cumprimentar o árbitro e a esquadra no início, dizer «good shot» ou «well shot» (bom tiro) depois de um bom posto, e «bad luck» (pouca sorte) depois de uma falha, mas nunca comentam a técnica de um desconhecido. Uma palavra de agradecimento ao operador da máquina e ao árbitro no fim, um aperto de mão, e calma quando os resultados são afixados são comuns em muitos campos. Traduza estas cortesias com calor; elas contam."], "key_points": ["Chegue a horas e apresente-se ao árbitro; os atrasos custam zeros", "Siga a rotação; entre no posto só quando estiver livre", "Só o árbitro decide; nada de comentários sobre os acertos", "Perder o autocontrolo pode significar expulsão", "Costumes: cumprimentar, «well shot», agradecer ao operador e ao árbitro"], "terms": ["squad", "rotation", "referee", "trapper", "conduct", "round"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-ready", "label": "9 · Be ready with a full round of equipment and ammunition"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch21-loss-of-control", "label": "21 · Loss of self-control"}], "coach_says": [{"en": "Number twelve — last call!", "meaning": "O árbitro está a chamar um atirador que falta; se ele não vier, os seus pratos serão zeros.", "say": "Número doze — última chamada!"}, {"en": "You’re next — get ready.", "meaning": "Prepare-se agora: óculos, proteções auditivas, cartuchos, mas não entre no posto antes de ele estar livre.", "say": "É o próximo — prepare-se."}, {"en": "Well shot!", "meaning": "Elogio sincero depois de um bom prato ou de um bom posto.", "say": "Bom tiro!"}, {"en": "Bad luck.", "meaning": "Solidariedade amigável depois de uma falha, não uma crítica.", "say": "Pouca sorte."}, {"en": "Thanks, ref — thanks for pulling.", "meaning": "Agradecer ao árbitro e ao operador da máquina no fim da série.", "say": "Obrigado, senhor árbitro — obrigado pelos pratos."}], "quiz": [{"q": "Compak® Sporting, tiro por esquadras: o seu convidado chega depois de o primeiro atirador da sua esquadra ter pedido o primeiro prato. O que acontece?", "options": ["Junta-se no posto seguinte", "Leva 25 zeros nessa série", "Atira em último lugar, sem penalização", "A série recomeça"], "answer": 1, "why": "No Compak® por esquadras, o prazo é o primeiro pedido da esquadra; depois dele, o atirador atrasado leva 25 zeros (é possível recorrer ao júri)."}, {"q": "Um colega de esquadra diz em voz alta ao árbitro que ele se enganou num acerto. Como veem as regras isto?", "options": ["Como uma informação útil", "Como um protesto formal", "Como uma tentativa de influenciar o árbitro", "Como nada"], "answer": 2, "why": "Outras pessoas criticarem abertamente uma decisão sem autorização do árbitro conta como tentativa de influência; só o atirador em causa pode protestar."}, {"q": "No Parcours de Chasse – Sporting™, como funciona a ordem de tiro numa esquadra?", "options": ["Roda em cada posto e para os doubles", "É fixa durante todo o dia", "Começa sempre o melhor atirador", "O árbitro escolhe livremente"], "answer": 0, "why": "As esquadras de seis são sorteadas, e a ordem roda em cada posto e também para os doubles."}]}, {"id": "etiquette-protection-and-dress", "minutes": 5, "title": "Ouvidos, olhos e vestuário — os seus também", "body": ["As proteções auditivas são obrigatórias para todos os que estão num percurso ou perto dele: atiradores, árbitros, pessoal e espectadores. No Parcours de Chasse – Sporting™ os óculos de proteção são obrigatórios, sem exceção, para atiradores, árbitros, pessoal e qualquer pessoa perto de um posto. No Compak® Sporting a regra dos óculos menciona os atiradores, os árbitros e o pessoal. Um atirador que entre no posto sem uma delas é considerado ausente.", "Isso inclui-o a si. De pé atrás do posto, está «perto de um percurso». Os abafadores eletrónicos são a melhor ferramenta do intérprete: atenuam o tiro, mas deixam passar as vozes, por isso ouve o treinador e o árbitro. Óculos de tiro transparentes ou coloridos também o protegem dos fragmentos de prato que caem; um boné também ajuda.", "O código de vestuário tem a ver com segurança e respeito. Nada de calções curtos: só calções compridos tipo bermudas, que terminem no máximo 5 cm acima do joelho. As camisas precisam de ter pelo menos manga curta e um colarinho ou uma gola redonda tipo T-shirt; não é permitido um colete sobre o tronco nu. As sandálias são proibidas, e no Compak® isto aplica-se tanto no treino como em competição. O dorsal usa-se nas costas, entre os ombros e a cintura, bem visível, sem estar dobrado nem cortado.", "Uma primeira infração às regras de vestuário ou do dorsal dá uma advertência; se não for corrigida, seguem-se penalizações até à exclusão pelo júri. Nas cerimónias, os membros das equipas usam o equipamento da seleção nacional ou calças cuidadas e um blazer, e todos os premiados têm de estar presentes na entrega de prémios. Vista-se como um profissional sereno: sapatos fechados, roupa neutra, nada que esvoace ou brilhe nos olhos do atirador."], "key_points": ["Proteções auditivas para todos perto de um percurso, incluindo espectadores e intérpretes", "Óculos: Sporting™ — qualquer pessoa perto de um posto; Compak® — atiradores, árbitros, pessoal", "Sem elas, o atirador é considerado ausente", "Bermudas no máximo 5 cm acima do joelho, mangas, nada de tronco nu por baixo do colete, nada de sandálias", "Dorsal nas costas, bem visível; primeira infração = advertência"], "terms": ["hearing-protection", "electronic-ear-muffs", "earplugs", "safety-glasses", "dress-code", "competitor-number", "shooting-vest", "prize-giving"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "sporting", "id": "ch17-ceremonies", "label": "17 · Dress at the opening and closing ceremonies"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch7-ceremonies", "label": "7 · Dress for opening and closing ceremonies"}], "coach_says": [{"en": "Eyes and ears on before you leave the clubhouse.", "meaning": "Ponha os óculos e as proteções auditivas antes de sair para os percursos.", "say": "Óculos e proteções postos antes de sair da sede do clube."}, {"en": "Where are your ears?", "meaning": "«Ears» = proteções auditivas, não as próprias orelhas.", "say": "Onde estão as suas proteções auditivas?"}, {"en": "You can’t shoot in sandals here.", "meaning": "São obrigatórios sapatos fechados por razões de segurança.", "say": "Aqui não pode atirar de sandálias."}, {"en": "Your number’s folded — it has to be fully visible.", "meaning": "O dorsal nas costas tem de estar completo e visível; caso contrário, advertência.", "say": "O seu dorsal está dobrado — tem de estar bem visível."}], "quiz": [{"q": "O seu atirador entra no posto sem óculos de proteção. Como o tratam as regras?", "options": ["Leva uma advertência e pode atirar", "Pode atirar se o treinador concordar", "Perde um prato", "É considerado ausente"], "answer": 3, "why": "Nas duas disciplinas, um atirador sem proteção ocular ou auditiva no posto é considerado ausente."}, {"q": "Que calções são permitidos?", "options": ["Quaisquer calções desportivos", "Calções tipo bermudas que terminem no máximo 5 cm acima do joelho", "Calções só no Compak®", "Nenhuns calções"], "answer": 1, "why": "Os calções curtos são proibidos; as bermudas compridas, no máximo 5 cm acima do joelho, são aceites."}, {"q": "Porque são os abafadores eletrónicos uma boa escolha para um intérprete?", "options": ["Atenuam o tiro, mas deixam passar as vozes", "Não são obrigatórios para intérpretes", "Bloqueiam completamente todo o som", "Gravam o treinador"], "answer": 0, "why": "As proteções auditivas são obrigatórias perto de um percurso, e os abafadores eletrónicos permitem-lhe ouvir o treinador e o árbitro."}]}]}, {"id": "interpreter", "icon": "speech", "title": "O intérprete em ação", "intro": "Tudo o que aprendeu junta-se aqui: o que pode e não pode dizer, onde se colocar, as palavras que enganam até linguistas experientes, números e unidades, o vocabulário britânico e americano e, por fim, uma sessão de treino completa, do primeiro «bom dia» à análise final.", "lessons": [{"id": "interpreter-role", "minutes": 5, "title": "O seu papel: treino versus competição", "body": ["No treino, o intérprete é a voz do treinador. Transmita cada instrução por completo, pela ordem e no tom do treinador: firme quando se trata de segurança, caloroso quando é um elogio. Não suavize as críticas, não acrescente razões que o treinador não deu, e nunca acrescente dicas técnicas suas, mesmo que saiba a resposta. Se não ouviu uma palavra, pergunte antes de traduzir.", "Uma competição é diferente. Dar instruções de treino a um atirador durante a competição é proibido, tanto no Parcours de Chasse – Sporting™ como no Compak® Sporting: o atirador leva cartão amarelo, as repetições trazem novas sanções, e o árbitro afasta da zona de tiro a pessoa que estava a dar instruções. O árbitro também decide sozinho: ninguém na esquadra comenta os acertos, e a crítica aberta a uma decisão conta como tentativa de influenciar o árbitro.", "Agora, a parte honesta. Os regulamentos da FITASC não mencionam os intérpretes. Se transmitir palavra a palavra os conselhos de um treinador durante uma competição conta como treino, e onde se pode colocar um intérprete, as regras não dizem. É uma questão em aberto para a FITASC, e não deve apresentar nenhuma resposta como oficial.", "Até a FITASC responder, siga a prática segura. Em competição, interprete apenas a comunicação com o árbitro, o júri e o organizador: vozes de comando, decisões, advertências, protestos, horários e esquadras. Antes da prova, diga ao árbitro ou ao organizador quem é e combine onde se vai colocar. Se um treinador lhe pedir para transmitir conselhos durante a competição, recuse com delicadeza e explique porquê. Isso protege o seu atirador de um cartão amarelo."], "key_points": ["Treino: a voz do treinador — completa, no mesmo tom, nada da sua parte", "Competição: o treino é proibido (cartão amarelo, treinador afastado)", "Questão em aberto para a FITASC: os regulamentos não mencionam os intérpretes", "Prática segura: em competição, interpretar apenas a comunicação com o árbitro, o júri e o organizador", "Apresente-se ao árbitro e combine onde se coloca"], "terms": ["coach", "referee", "jury", "yellow-card", "conduct", "interpreter", "coaching"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Tell her she’s lifting her head on the second bird.", "meaning": "Treino: transmita-o por completo quando a arma estiver aberta.", "say": "Diga-lhe que está a levantar a cabeça no segundo prato."}, {"en": "Quick — tell him to give the crosser more.", "meaning": "Competição: isto é treino. Recuse com delicadeza; não o transmita.", "say": "Depressa — diga-lhe para dar mais avanço ao transversal."}, {"en": "Who are you with?", "meaning": "O árbitro pergunta porque está perto do posto; apresente-se e explique o seu papel.", "say": "Está com quem?"}, {"en": "Ask the referee if I can still change chokes.", "meaning": "Uma pergunta de procedimento ao árbitro: pode interpretá-la.", "say": "Pergunte ao árbitro se ainda posso trocar os chokes."}], "quiz": [{"q": "Durante uma série de competição, o treinador pede-lhe para dizer ao atirador «more lead on the crosser». O que faz?", "options": ["Sussurra-o depressa", "Tradu-lo depois do prato seguinte", "Recusa com delicadeza: seria treino, o que é proibido", "Pede ao árbitro que o transmita"], "answer": 2, "why": "O treino durante a competição é proibido e o atirador levaria cartão amarelo; as regras não dizem se transmitir conselhos é permitido, por isso jogue pelo seguro."}, {"q": "O que dizem os regulamentos da FITASC sobre os intérpretes?", "options": ["Podem estar no posto", "Precisam de uma licença de árbitro", "Contam como treinadores", "Nada: é uma questão em aberto"], "answer": 3, "why": "Os regulamentos não mencionam os intérpretes, por isso a sua posição exata em competição é uma questão em aberto para a FITASC."}, {"q": "No treino, o treinador diz «Not bad, but you stopped the gun.» Como traduz?", "options": ["Por completo e no mesmo tom, as duas partes", "Só o elogio, para manter o convidado contente", "Só o erro, para poupar tempo", "Acrescenta uma dica sua para corrigir"], "answer": 0, "why": "Não suaviza nem exagera: a mensagem inteira, no tom do treinador, sem nada da sua parte."}]}, {"id": "interpreter-position", "minutes": 5, "title": "Onde se colocar e quando falar", "body": ["No treino, coloque-se mesmo atrás do atirador, ao lado do treinador, atrás do posto ou da gaiola e fora de qualquer linha dos canos. Daí vê o que o treinador vê, o prato e as bocas dos canos ao mesmo tempo, e o treinador pode falar-lhe em voz baixa. Ao lado do atirador é o sítio mais perigoso; à frente do posto está fora de questão.", "Escolha o modo conforme o momento. A interpretação consecutiva (o treinador fala, faz uma pausa, o intérprete fala) adequa-se ao briefing de segurança, à caminhada entre postos e à análise final. A interpretação sussurrada, chuchotage, permite ao treinador continuar a falar enquanto o intérprete sussurra ao ouvido do atirador, por trás; é cansativa, por isso alterne os dois modos. Combine um sinal de «pausa, estou a traduzir», como uma palma da mão levantada.", "O momento certo é tudo. A rotina do atirador vai de fechar a arma até ao tiro. Fale só quando a arma estiver aberta: entre pratos, entre doubles, depois do posto. Entre doubles, reproduza as indicações curtas do treinador, «mais à frente», «cabeça em baixo», «outra vez igual», e guarde as explicações longas para depois. Lembre-se do relógio: no Parcours de Chasse – Sporting™ um atirador tem no máximo 15 segundos entre pratos ou doubles, e no Compak® Sporting 10 segundos para pedir o prato. As suas palavras também gastam esse tempo.", "Em competição, espere onde a esquadra espera, perto do posto mas sem nunca distrair o atirador: um atirador claramente perturbado tem direito a um NULO, e ninguém quer ser a causa. Aprenda os sinais com as mãos do treinador logo no início e traduza-os uma vez para os seus convidados; depois disso vão precisar menos de si, e isso é bom sinal."], "key_points": ["Treino: mesmo atrás do atirador, ao lado do treinador, fora da linha dos canos", "Consecutiva para briefings e análises finais; chuchotage no posto; alterne", "Fale só quando a arma estiver aberta", "Indicações curtas entre doubles; limites de tempo de 15 s (Sporting™) e 10 s (Compak®)", "Competição: espere com a esquadra, nunca distraia"], "terms": ["quiet-on-stand", "shooting-stand", "coach", "firing-time", "no-bird", "chuchotage", "consecutive-interpreting", "hand-signals"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Stand right behind me.", "meaning": "Atrás do treinador e do atirador, fora do movimento da arma.", "say": "Ponha-se mesmo atrás de mim."}, {"en": "Head on the stock — just whisper it to him, I’ll keep going.", "meaning": "Passe para chuchotage e transmita a indicação em voz baixa; o treinador não vai parar.", "say": "Cabeça na coronha — sussurre-lhe só isso, eu continuo."}, {"en": "When I do this — hands apart — it means more in front.", "meaning": "O treinador explica um sinal com as mãos; traduza-o uma vez para o grupo.", "say": "Quando eu fizer isto — mãos afastadas — quer dizer mais à frente."}, {"en": "Wait — let him finish the pair.", "meaning": "Guarde o conselho até a arma estar outra vez aberta.", "say": "Espere — deixe-o acabar o double."}, {"en": "Sorry — did you say “under it” or “on it”?", "meaning": "Pergunte de volta com as duas opções que ouviu; é mais rápido do que «repita, por favor».", "say": "Desculpe — disse «por baixo dele» ou «em cima dele»?"}], "quiz": [{"q": "Onde se deve colocar durante uma sessão de treino num posto de Sporting™?", "options": ["Ao lado do atirador, para lhe ver os olhos", "Atrás do atirador, ao lado do treinador, fora da linha dos canos", "À frente da gaiola, virado para o atirador", "Ao lado da máquina"], "answer": 1, "why": "Por trás vê o que o treinador vê e fica em segurança; ao lado ou à frente é perigoso."}, {"q": "O que é a chuchotage?", "options": ["Interpretar depois de o orador fazer uma pausa", "Tradução escrita das regras", "Traduzir sinais feitos com as mãos", "Interpretação simultânea sussurrada ao ouvido do ouvinte"], "answer": 3, "why": "A chuchotage é interpretação simultânea sussurrada; a consecutiva é o modo de pausa e fala."}, {"q": "No Compak® Sporting, quanto tempo tem um atirador para pedir o prato depois de o prato do posto anterior ter sido atirado?", "options": ["10 segundos", "15 segundos", "30 segundos", "Sem limite"], "answer": 0, "why": "O Compak® dá no máximo 10 segundos para pedir o prato; o Sporting™ permite 15 segundos entre pratos ou doubles."}]}, {"id": "interpreter-false-friends", "minutes": 6, "title": "Falsos amigos no campo de tiro", "body": ["A pior armadilha é o fumo. O «Smoked it!» de um treinador (ou «inked it», «powdered it») significa um acerto perfeito: o prato desapareceu numa nuvem. Mas nas regras, um prato que só larga pó ou fumo, sem pedaço visível, é zero. Uma «chip», um pequeno pedaço visível, é acerto. Por isso traduza o «smoked it» do treinador como «pulverizou-o», e o «only dust» do árbitro como «só pó — zero».", "As palavras de pontuação não são literais. «Dead» e «kill» significam acerto («bom», «partido»), nunca «morto» ou «matar». «Lost» é uma falha («zero», «falhado»), não «perdido» no sentido de extraviado. «Dropped two» significa dois pratos falhados. «Straight» em «25 straight» significa uma série perfeita, não «a direito».", "Palavras de equipamento e de lugar. Um «trap» é a máquina de lançar («máquina»), não uma «armadilha» (Trap é também uma disciplina olímpica, o Fosso). Um «stand» é uma posição de tiro («posto»), não o «stand» de tiro inteiro; um «peg» é o sítio marcado, não uma estaca; um «broken gun» é uma arma aberta. «Pull!» é a voz de comando, «pull-away» um método de avanço, «length of pull» uma medida da coronha. Um «card» é uma folha de marcação ou um cartão amarelo ou vermelho. «On report» significa ao som do tiro. Um «squad» é o grupo da FITASC de até seis (esquadra); na ClayAway designa também um subgrupo de uma viagem.", "Outras línguas acrescentam armadilhas. A «chandelle» francesa é um prato quase vertical (um teal inglês), não a chandelle inglesa. O francês «en battue» e o italiano «in battuta» significam caça de batida, não o prato batida; em português, «batida» é o prato battue e «de batida» significa driven. Para um acerto, um árbitro francês diz «Bon», um italiano «Buono»; o operador da máquina é um «pulleur» ou «puller». As regras italianas usam palavras diferentes para a esquadra: batteria no Parcours de Chasse – Sporting™, squadra di tiro no Compak®."], "key_points": ["«Smoked it» do treinador = acerto perfeito; «only dust or smoke» das regras = zero", "Dead / kill = acerto; lost / dropped = falha; straight = série perfeita", "Trap = máquina; stand = uma posição (posto); peg = o sítio marcado; broken gun = arma aberta", "Pull, card, report e squad têm todos mais de um sentido", "A chandelle francesa e «en battue» diferem das palavras inglesas"], "terms": ["one", "zero", "visible-piece", "trap", "shooting-stand", "squad", "call", "double-on-report", "pull-away", "length-of-pull", "yellow-card", "score-sheet", "battue", "teal", "false-friend", "peg", "smoked-it"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Smoked it!", "meaning": "Acerto perfeito, o prato desfez-se em pó. Não é o «só fumo» das regras.", "say": "Pulverizou-o!"}, {"en": "Only dust — zero.", "meaning": "Árbitro: não se soltou nenhum pedaço visível, por isso é falha.", "say": "Só pó — zero."}, {"en": "Just a chip, but it’s dead.", "meaning": "Soltou-se um pequeno pedaço visível: conta como acerto.", "say": "Só uma lasca, mas é bom."}, {"en": "Break your gun.", "meaning": "Abra a arma. Não tem nada a ver com parti-la.", "say": "Abra a arma."}, {"en": "Step into the peg.", "meaning": "Coloque-se no sítio de tiro marcado.", "say": "Entre no posto."}, {"en": "The second one’s on report.", "meaning": "O segundo prato é lançado pelo som do seu primeiro tiro.", "say": "O segundo é ao tiro."}], "quiz": [{"q": "O treinador grita «Smoked it!» depois de um tiro. O que aconteceu?", "options": ["Só saiu fumo: um zero", "O prato foi destruído: um acerto perfeito", "O cartucho falhou", "O prato era um prato flash"], "answer": 1, "why": "Na gíria dos treinadores, «smoked it» é um acerto perfeito; nas regras, «only dust or smoke» é um zero — sentidos opostos."}, {"q": "Qual é a melhor tradução portuguesa para o «Lost.» do árbitro?", "options": ["«Extraviado»", "«Perdeu tempo»", "«Zero»", "«O prato desapareceu»"], "answer": 2, "why": "«Lost» é a palavra de pontuação para uma falha (zero), não algo que se perdeu."}, {"q": "Um convidado francês diz que adora atirar «en battue». O que quer dizer?", "options": ["Caça de batida (aves empurradas por cima das espingardas)", "O prato plano batida", "Um prato lançado num double", "Um prato partido"], "answer": 0, "why": "O francês «en battue» (italiano «in battuta») significa caça de batida; o prato batida é outra coisa."}]}, {"id": "interpreter-numbers-and-units", "minutes": 5, "title": "Números e unidades: pés, jardas, calibres, números do chumbo", "body": ["Os treinadores britânicos e americanos medem o avanço em pés: «give it three feet» (dê-lhe três pés), «a yard in front» (uma jarda à frente), «half a bird» (meio prato), «a barrel's width» (a largura de um cano). Isto é uma imagem, não uma medição. Traduza a unidade tal como foi dita, «três pés», e não a converta a meio de uma instrução: 0,9 m soa preciso e muda o sentido. Explique uma vez, antes da sessão, que os pés dos treinadores são uma impressão, e mantenha «more», «less», «double it» (mais, menos, o dobro) exatamente como foram ditos.", "As distâncias até aos pratos são outra questão. «It's about thirty yards» pode ser dado em metros com «cerca de» («cerca de 27 metros»), porque uma jarda é um pouco menos de um metro. As direções vêm muitas vezes como um mostrador de relógio: em frente é 12, por isso «pick it up at eleven o'clock» (apanhe-o às onze horas) é ligeiramente à esquerda. Mantenha o relógio; não o transforme em graus.", "O calibre funciona ao contrário. Um «12-bore» ou «12 gauge» não tem 12 mm; quanto menor o número, mais largo o cano, por isso um calibre 20 é mais estreito. Os dois regulamentos da FITASC permitem no máximo o calibre 12, com canos de pelo menos 66 cm (26 polegadas). A linha do colete no Parcours de Chasse – Sporting™ fica a 25 cm, o que os atiradores britânicos podem chamar pouco menos de dez polegadas.", "Cartuchos: a FITASC permite no máximo 28 g de chumbo, perto da «one-ounce load» (carga de uma onça) que os atiradores britânicos referem, com esferas de 2,0 a 2,5 mm. Os números do chumbo não são iguais em todos os países: um n.º 9 tem cerca de 2 mm quase em todo o lado, mas outros números podem diferir ligeiramente entre os sistemas britânico, americano e continental. Quando for importante, peça os milímetros. Os chokes podem vir como nomes, frações ou «thou» (milésimas de polegada); traduza o sistema que o treinador usou."], "key_points": ["O avanço em pés é uma imagem: mantenha a unidade, nunca converta a meio de uma instrução", "Distância até ao prato: as jardas podem passar a «cerca de … metros»", "Mostrador do relógio para direções: 12 = em frente", "Calibre 12 ≠ 12 mm; calibre máximo da FITASC 12, canos ≥ 66 cm (26 pol.)", "28 g ≈ uma onça; chumbo de 2,0–2,5 mm; os números do chumbo variam de país para país — peça os mm"], "terms": ["lead", "gauge", "barrel-length", "shot-size", "load-weight", "choke", "cartridge", "clock-face"], "sources": [{"title": "Shotgun Life — Does barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}], "coach_says": [{"en": "Give it three feet.", "meaning": "A imagem de avanço que o treinador quer; uma distância percebida, não medida.", "say": "Dê-lhe três pés."}, {"en": "Half that.", "meaning": "Use metade do avanço anterior.", "say": "Metade disso."}, {"en": "Pick it up at eleven o’clock.", "meaning": "Procure o prato ligeiramente à esquerda de em frente.", "say": "Apanhe-o às onze horas."}, {"en": "It’s about forty yards out.", "meaning": "O prato está a cerca de 37 metros.", "say": "Está a umas quarenta jardas."}, {"en": "Put a nine in the bottom barrel.", "meaning": "Carregue um cartucho de chumbo n.º 9 (cerca de 2 mm) no cano de baixo, que normalmente dispara primeiro.", "say": "Ponha um nove no cano de baixo."}], "quiz": [{"q": "O treinador diz «Give it four feet.» Qual é a melhor interpretação?", "options": ["«Avanço — cerca de 1,22 metros»", "«Avanço — quatro pés»", "«Atire quatro metros mais longe»", "«Quatro pratos à frente»"], "answer": 1, "why": "O avanço em pés é uma imagem; convertê-lo a meio de uma instrução acrescenta uma falsa precisão e muda a mensagem."}, {"q": "Qual é o maior calibre permitido no Sporting™ e no Compak® da FITASC?", "options": ["10", "16", "20", "12"], "answer": 3, "why": "Os dois regulamentos permitem no máximo o calibre 12; um número de calibre menor significa um cano mais largo, por isso o 10 não é permitido."}, {"q": "Um convidado britânico pergunta se os seus cartuchos «one-ounce» são legais numa prova da FITASC. O que sabe?", "options": ["O limite da FITASC é de 28 g de chumbo (+2%), o que é cerca de uma onça", "A FITASC permite 36 g", "Qualquer carga é permitida", "Só são permitidos 24 g"], "answer": 0, "why": "As regras permitem até 28 g de chumbo, com uma tolerância de +2%; uma onça são cerca de 28 g. O tamanho do chumbo (2,0–2,5 mm) também tem de cumprir."}]}, {"id": "interpreter-english-sporting-vs-fitasc", "minutes": 5, "title": "Palavras britânicas e americanas versus FITASC", "body": ["Muitos dos treinadores com quem vai trabalhar cresceram com o English Sporting, regido em Inglaterra pela CPSA, ou com o Sporting Clays americano, da NSCA. As palavras são parecidas com as da FITASC, mas as regras por trás delas não, e a maior diferença é a posição da arma.", "No English Sporting e na NSCA, o atirador pode começar com «gun up», já com a arma à cara, antes de pedir o prato. No Parcours de Chasse – Sporting™ isso não é permitido: a coronha fica abaixo da linha do colete até o prato aparecer, e todos os pratos se atiram com a arma no ombro. O Compak® Sporting fica a meio caminho: a posição da arma no pedido é livre. Assim, «pre-mount this one» é um exercício no treino, mas um cartão amarelo numa competição de Sporting™ da FITASC. Traduza-o e, se o convidado estiver prestes a competir, pergunte ao treinador se deve mencionar a regra.", "Os doubles têm nomes diferentes. Um «true pair» (inglês e americano) é um double simultâneo da FITASC. Um «report pair» é um double ao tiro. Um «following pair» é um rafale da FITASC. Um «show pair» é a mostra dos pratos antes do tiro. Um «peg» é o posto de tiro, «station» é a palavra americana para posto, e uma «cage» é a estrutura à volta dele.", "A linguagem dos resultados também difere. «HOA», High Over All, é o vencedor da classificação geral. Classes como AA, A, B ou C são níveis nacionais de desempenho calculados a partir de médias, não categorias de idade da FITASC, nem as classes de dificuldade A, B e C da FITASC, que classificam trajetórias. Mesmo dentro da FITASC, os doubles diferem: no Sporting™ ambos os cartuchos podem ir para um só prato de um double, no Compak® só um cartucho por prato. Pergunte-se sempre que regulamento tem o orador em mente."], "key_points": ["Gun up: permitido no English Sporting e na NSCA, proibido no Sporting™ da FITASC, livre no Compak®", "True pair = simultâneo; report pair = ao tiro; following pair = rafale", "Peg = sítio de tiro; station = posto (EUA); cage = estrutura de proteção", "HOA = vencedor da geral; as classes AA/A/B/C não são categorias nem classes de dificuldade da FITASC", "Sporting™: os dois tiros a um só prato permitidos; Compak®: um por prato"], "terms": ["ready-position", "gun-mount", "simultaneous-double", "double-on-report", "rafale-double", "target-presentation", "shooting-stand", "english-sporting", "nsca", "cpsa", "gun-up", "true-pair", "peg", "cage", "hoa", "shooter-class"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "CPSA — English Sporting", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Pre-mount this one for now.", "meaning": "Exercício de treino: começar com a arma no ombro. Não permitido em competição de Sporting™ da FITASC.", "say": "Para já, este com a arma à cara."}, {"en": "It’s a true pair.", "meaning": "Os dois pratos saem ao mesmo tempo (FITASC: double simultâneo).", "say": "É um double simultâneo."}, {"en": "Following pair off the left trap.", "meaning": "Dois pratos da mesma máquina, um a seguir ao outro (FITASC: rafale).", "say": "Rafale da máquina da esquerda."}, {"en": "Let’s see a show pair.", "meaning": "Lançar o double uma vez para todos o verem antes do tiro.", "say": "Vamos ver a mostra do double."}, {"en": "He’s AA class and won HOA last year.", "meaning": "Uma classe nacional de desempenho elevada, e vencedor da classificação geral da prova.", "say": "Ele é classe AA e ganhou a geral no ano passado."}], "quiz": [{"q": "Um treinador britânico diz «It's a true pair.» Qual é o termo da FITASC?", "options": ["Um double ao tiro", "Um double rafale", "Um double simultâneo", "Um double correto"], "answer": 2, "why": "«True pair» é o nome inglês e americano para dois pratos lançados ao mesmo tempo, um double simultâneo da FITASC."}, {"q": "Em que disciplina NÃO é permitida a partida com «gun up»?", "options": ["Parcours de Chasse – Sporting™ (FITASC)", "Compak® Sporting", "English Sporting (CPSA)", "Sporting Clays (NSCA)"], "answer": 0, "why": "O Sporting™ da FITASC exige a coronha abaixo da linha do colete até o prato aparecer; o Compak® deixa a posição da arma livre."}, {"q": "Um convidado lê «Class C» em resultados britânicos. O que é?", "options": ["Uma categoria de idade da FITASC", "Um nível nacional de desempenho baseado em médias", "A classe de trajetória mais difícil da FITASC", "Um tipo de cartucho"], "answer": 1, "why": "Nos resultados britânicos e americanos, as classes são níveis de desempenho; a FITASC usa A/B/C apenas para a dificuldade das trajetórias e tem, em vez disso, categorias de idade."}]}, {"id": "interpreter-session-script", "minutes": 8, "title": "Uma sessão de treino completa, passo a passo", "body": ["Antes da sessão, encontre-se com o treinador durante cinco minutos. Combine um sinal de pausa, pergunte que método ensina e que palavras usa para o avanço, e aprenda os seus sinais com as mãos. Depois o grupo junta-se para o briefing de segurança: interprete-o em consecutiva, frase a frase, com firmeza e por completo.", "No primeiro posto, o treinador começa normalmente sem cartuchos: um teste de dominância ocular, depois a posição dos pés e a posição de partida. Num contexto FITASC, a arma começa em baixo, abaixo da linha do colete. Sussurre as correções dele por trás enquanto ele ajusta pés e mãos.", "Segue-se a leitura do prato. O treinador mostra-o, pergunta onde o atirador o vê nítido pela primeira vez, e define o ponto de visão, o ponto de espera da arma e o ponto de tiro. Mantenha estes três termos iguais durante todo o dia, «ponto de visão», «ponto de espera», «ponto de tiro», para que o convidado os aprenda.", "Agora o tiro. Entre pratos, o treinador dá indicações de duas a cinco palavras; reproduza-as, com o mesmo comprimento e pela mesma ordem, enquanto a arma está aberta. Quando uma falha é diagnosticada, «behind», «over the top», «you stopped» (atrás, por cima, parou), traduza o diagnóstico e a correção juntos. O elogio traduz-se com a mesma energia.", "Depois os doubles: a que prato atirar primeiro, «eyes first, then the gun» (primeiro os olhos, depois a arma), o segundo tiro. Por fim, a análise final, outra vez em consecutiva, em que o treinador resume dois ou três pontos. Escreva-os nas duas línguas e entregue a nota ao convidado. Abaixo está uma sequência real de frases, pela ordem em que as vai ouvir."], "key_points": ["Antes: sinal de pausa, método, palavras para o avanço, sinais com as mãos", "Briefing de segurança: consecutiva, firme, completo", "Os mesmos três termos durante todo o dia: ponto de visão, ponto de espera, ponto de tiro", "Indicações entre pratos: mesmo comprimento, arma aberta; diagnóstico + correção juntos", "Análise final: escrever os pontos-chave nas duas línguas"], "terms": ["coach", "safety", "eye-dominance", "master-eye", "stance", "ready-position", "gun-mount", "pick-up-point", "hold-point", "break-point", "lead", "maintained-lead", "pull-away", "head-lift", "stopping-the-gun", "follow-through", "double-on-report", "crosser", "rabbit", "choke"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "NSSA-NSCA — Foot position (Ask the instructor)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}], "coach_says": [{"en": "Morning, everyone. Before we load anything, a quick safety briefing.", "meaning": "Início da sessão; interprete o briefing em consecutiva e por completo.", "say": "Bom dia a todos. Antes de carregarmos o que quer que seja, um briefing rápido de segurança."}, {"en": "Guns stay open until you’re on the stand and I say “load”.", "meaning": "Nada de armas fechadas fora do posto; só se carrega à ordem do treinador.", "say": "As armas ficam abertas até estarem no posto e eu dizer «carregar»."}, {"en": "Point at my nose, both eyes open. Now close your left eye.", "meaning": "Teste de dominância ocular: se o dedo saltar, o olho direito não é o olho diretor.", "say": "Aponte para o meu nariz, com os dois olhos abertos. Agora feche o olho esquerdo."}, {"en": "Front foot pointing at the break point, weight forward.", "meaning": "Posição: coloque os pés para o sítio onde o prato vai ser partido; incline-se ligeiramente para a frente.", "say": "Pé da frente a apontar para o ponto de tiro, peso à frente."}, {"en": "Gun down, stock under the line. Mount only when you see it.", "meaning": "Posição de partida da FITASC: a arma só sobe depois de o prato aparecer.", "say": "Arma em baixo, coronha abaixo da linha. Ponha a arma à cara só quando o vir."}, {"en": "Watch this one. Where do you first see it clearly?", "meaning": "O treinador está a definir o ponto de visão.", "say": "Veja este. Onde é que o vê nítido pela primeira vez?"}, {"en": "Hold your muzzles about halfway back, just under the line.", "meaning": "Ponto de espera entre o ponto de visão e o ponto de tiro, ligeiramente abaixo da trajetória do prato.", "say": "Espere com os canos mais ou menos a meio caminho, mesmo por baixo da linha."}, {"en": "Behind it. Give it more.", "meaning": "O chumbo passou atrás do prato: mais avanço.", "say": "Atrás dele. Dê-lhe mais."}, {"en": "Call it three feet — that’s the picture you want.", "meaning": "A imagem de avanço a ver no momento do tiro; pés como impressão, mantenha a unidade.", "say": "Digamos três pés — é essa a imagem que quer."}, {"en": "Over the top. You lifted your head — stay in the gun.", "meaning": "Falha por cima, causada pela face a sair da coronha.", "say": "Por cima. Levantou a cabeça — fique na arma."}, {"en": "Smoked it! Same again.", "meaning": "Acerto perfeito; repita exatamente o que fez.", "say": "Pulverizou-o! Outra vez igual."}, {"en": "You stopped the gun. Keep it moving through the shot.", "meaning": "Falha atrás porque o movimento parou; acompanhe.", "say": "Parou a arma. Mantenha-a a mexer durante o tiro."}, {"en": "Next is a report pair: crosser first, then the rabbit.", "meaning": "O coelho é lançado pelo som do tiro ao transversal.", "say": "A seguir é um double ao tiro: primeiro o transversal, depois o coelho."}, {"en": "Eyes first, then the gun.", "meaning": "No segundo prato, encontre-o com os olhos antes de mover as bocas dos canos.", "say": "Primeiro os olhos, depois a arma."}, {"en": "Keep the muzzles under the rabbit.", "meaning": "Fique baixo num prato que rola, para que um salto encontre na mesma o chumbo.", "say": "Mantenha os canos por baixo do coelho."}, {"en": "Change to quarter and half for this stand.", "meaning": "Monte chokes de 1/4 e 1/2 (aberto e depois um pouco mais apertado).", "say": "Para este posto, mude para um quarto e meio."}, {"en": "Let’s call it a day. Three things for tomorrow: feet, head, follow-through.", "meaning": "Fim da sessão; o treinador faz o resumo — escreva-o para o convidado.", "say": "Por hoje chega. Três coisas para amanhã: pés, cabeça, acompanhamento."}], "quiz": [{"q": "Quando se interpreta o briefing de segurança, e como?", "options": ["Brevemente, em chuchotage, enquanto os convidados carregam", "No início, em consecutiva, frase a frase e por completo", "Só se um convidado pedir", "Depois do primeiro posto"], "answer": 1, "why": "A segurança vem primeiro e não pode ser encurtada; o modo consecutivo permite que cada regra seja bem compreendida."}, {"q": "O treinador diz «Behind it. Give it more.» Qual é a melhor tradução curta entre pratos?", "options": ["«Ficou um pouco atrasado, tente outra vez, talvez mais depressa»", "«Atrás. Mais avanço.»", "«Atire mais cedo»", "«Bem, outra vez igual»"], "answer": 1, "why": "Reproduza o treinador: mesmo comprimento, mesma ordem, diagnóstico mais correção, nada acrescentado."}, {"q": "Porque deve manter «pick-up point», «hold point» e «break point» com as mesmas palavras portuguesas durante todo o dia?", "options": ["As regras exigem-no", "Para que o treinador perceba português", "Para que o convidado aprenda três conceitos estáveis e não os confunda", "Não tem importância"], "answer": 2, "why": "Termos coerentes constroem o mapa mental que o convidado tem de um posto; mudar as palavras faz três conceitos parecerem seis."}]}]}]};
